insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-fd761ae5f4', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following is a selective β1-adrenoceptor blocker?', '["Pindolol", "Propranolol", "Labetalol", "Atenolol", "Sotalol"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol is cardioselective, blocking β1 receptors far more than β2, which makes it safer in patients with reactive airways. Propranolol, pindolol and sotalol block β1 and β2 non-selectively, and labetalol blocks α1 as well as both β subtypes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.004 Q32. Reworded the fill-in-the-blank stem as a question and specified β1.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-b3685b8418', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'Which of the following is not a bronchodilator anti-asthmatic?', '["Zafirlukast", "Isoproterenol", "Ephedrine", "Albuterol", "Theophylline"]'::jsonb, 'Zafirlukast', '[]'::jsonb, 'Zafirlukast is a leukotriene CysLT1 receptor antagonist used to prevent asthma by reducing inflammation and bronchial hyperreactivity; it is not used to relieve bronchospasm. Isoproterenol, ephedrine and albuterol are β-agonist bronchodilators, and theophylline bronchodilates through phosphodiesterase inhibition and adenosine antagonism.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.005 Q17') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-e0327e6dc9', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which statement about general anaesthetic agents is incorrect?', '["Propofol has good analgesic effects", "Ketamine increases blood pressure", "Etomidate causes adrenocortical suppression", "Thiopental has a rapid onset of action", "Halothane sensitises the myocardium to the actions of catecholamines"]'::jsonb, 'Propofol has good analgesic effects', '[]'::jsonb, 'Propofol has no useful analgesic action, so opioids or other analgesics must be added during surgery. Ketamine raises blood pressure through sympathetic stimulation, etomidate inhibits 11β-hydroxylase and suppresses cortisol synthesis, thiopental acts within one arm-brain circulation time, and halothane does sensitise the myocardium to catecholamine-induced arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.014. The paper''s marked answer was the halothane statement, which is true; propofol''s lack of analgesia makes that statement the incorrect one.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-edcff42d27', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which is the false statement about benzodiazepines used as sedatives?', '["Flumazenil is used in the management of benzodiazepine toxicity", "They facilitate opening of GABA-activated chloride channels", "They are safer than barbiturates", "Most are metabolised by dealkylation and conjugation reactions", "Longer-acting benzodiazepines are used in the treatment of provoked anxiety"]'::jsonb, 'Longer-acting benzodiazepines are used in the treatment of provoked anxiety', '[]'::jsonb, 'Short-acting benzodiazepines suit brief, situational (provoked) anxiety, while long-acting agents such as diazepam are preferred for intense, sustained anxiety. Benzodiazepines increase the frequency of GABA-A chloride channel opening, have a wider safety margin than barbiturates, are largely metabolised by dealkylation and glucuronidation, and flumazenil reverses them.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.015 Q18. Shortened option c from ''safer and more effective than barbiturates'' to ''safer than barbiturates'' so only one option is false.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-94a06dc19d', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which of the following antiseizure drugs is excreted unchanged in the urine without being metabolised?', '["Gabapentin", "Dimethadione", "Phenytoin", "Clonazepam", "Valproic acid"]'::jsonb, 'Gabapentin', '[]'::jsonb, 'Gabapentin is not metabolised in humans, does not bind plasma proteins and is eliminated unchanged by the kidneys, so its dose is reduced in renal impairment and it has few drug interactions. Phenytoin, clonazepam and valproate are extensively metabolised by the liver, and dimethadione is itself the active metabolite of trimethadione.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.018 Q25. Replaced vigabatrin (also largely excreted unchanged) with phenytoin so there is only one correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-280ff13519', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which dopamine receptor agonist causes severe nausea that requires pre-treatment with antiemetics?', '["Rotigotine", "Ropinirole", "Bromocriptine", "Pramipexole", "Apomorphine"]'::jsonb, 'Apomorphine', '[]'::jsonb, 'Apomorphine is a potent subcutaneous dopamine agonist used as rescue therapy for ''off'' episodes in Parkinson''s disease. It strongly stimulates the chemoreceptor trigger zone, so patients are pre-treated with a peripheral D2 antagonist such as domperidone or trimethobenzamide. Other dopamine agonists cause nausea too, but rarely enough to need routine pre-treatment.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.020') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-c5fde35ab0', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following is true of lignocaine?', '["It is an ester local anaesthetic", "It is a long-acting agent", "Medical procedures are performed at stage 3 of anaesthesia", "It is metabolised in the liver", "It is 90% bound to albumin in plasma"]'::jsonb, 'It is metabolised in the liver', '[]'::jsonb, 'Lignocaine (lidocaine) is an amide local anaesthetic, and amides are metabolised by hepatic microsomal enzymes, so toxicity increases in liver disease or low hepatic blood flow. It has a rapid onset and intermediate duration of action. In plasma it binds mainly to α1-acid glycoprotein, about 65% overall, not 90% to albumin.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.022 Q12. Changed option b from ''Rapidly acting agent'' (arguably true) to ''It is a long-acting agent'' so only one option is true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-9119fb557b', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which is not a clinical indication of carbamazepine?', '["Myoclonic seizures", "Trigeminal neuralgia", "Focal to bilateral tonic-clonic seizures", "Mania in bipolar mood disorder", "Focal seizures"]'::jsonb, 'Myoclonic seizures', '[]'::jsonb, 'Carbamazepine blocks voltage-gated sodium channels and is a first-line drug for focal seizures with or without secondary generalisation, the drug of choice for trigeminal neuralgia, and a mood stabiliser in bipolar disorder. It can worsen absence and myoclonic seizures, so it is avoided in generalised epilepsies such as juvenile myoclonic epilepsy.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.023 Q34') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-706df4d6d9', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'The following drugs are used in the management of portal hypertension and oesophageal varices EXCEPT:', '["Isosorbide 5-mononitrate", "Terlipressin", "Propranolol", "Tolvaptan", "Octreotide"]'::jsonb, 'Tolvaptan', '[]'::jsonb, 'Tolvaptan is an oral vasopressin V2 receptor antagonist used for hyponatraemia; it does not lower portal pressure. Non-selective β-blockers such as propranolol, with or without nitrates, prevent variceal bleeding, while terlipressin (a V1 agonist) and octreotide constrict splanchnic vessels and are used in acute variceal haemorrhage.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.026 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-8a118a7be6', 'pharm-local-anesthetic-agents', 'mcq', 'Which local anaesthetic agent has the highest risk of cardiotoxicity?', '["Benzocaine", "Bupivacaine", "Lignocaine", "Chloroprocaine", "Cocaine"]'::jsonb, 'Bupivacaine', '[]'::jsonb, 'Bupivacaine is highly lipid-soluble and binds cardiac sodium channels avidly, dissociating slowly, so accidental intravascular injection can cause ventricular arrhythmias and myocardial depression that resist resuscitation; lipid emulsion is used as rescue. Its S-enantiomers ropivacaine and levobupivacaine were developed to be less cardiotoxic. Cocaine''s cardiac toxicity is mainly sympathomimetic.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.029 Q16') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-9601356cf8', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which agent causes the fastest rate of induction of anaesthesia?', '["Sevoflurane", "Isoflurane", "Nitrous oxide", "Halothane", "Desflurane"]'::jsonb, 'Desflurane', '[]'::jsonb, 'Speed of induction varies inversely with the blood:gas partition coefficient. Desflurane has the lowest of these agents (about 0.42), so alveolar and brain partial pressures rise fastest; nitrous oxide is very close at about 0.47. Halothane has the highest coefficient and slowest induction. In practice desflurane''s airway pungency limits its use for gas induction.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.033 Q19. Desflurane and nitrous oxide have very similar blood:gas coefficients; some texts present nitrous oxide as fastest, so the intended answer depends on the source used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-4cdd20463c', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Use of high doses of which of the following is associated with drug-induced lupus?', '["Hydralazine", "Prazosin", "Minoxidil", "Methyldopa", "Sodium nitroprusside"]'::jsonb, 'Hydralazine', '[]'::jsonb, 'Hydralazine causes a dose-related lupus-like syndrome (arthralgia, rash, serositis, positive antinuclear and antihistone antibodies), mostly at doses above 200 mg/day and in slow acetylators. It resolves on stopping the drug. Minoxidil causes hirsutism and fluid retention, nitroprusside cyanide toxicity, and prazosin first-dose hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.038') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-56cd2a8a94', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following reduces the risk of calcium stones in the kidney?', '["Hydrochlorothiazide", "Acetazolamide", "Ethacrynic acid", "Furosemide", "Bumetanide"]'::jsonb, 'Hydrochlorothiazide', '[]'::jsonb, 'Thiazides enhance calcium reabsorption in the distal convoluted tubule, lowering urinary calcium, so they prevent recurrent calcium stones in idiopathic hypercalciuria. Loop diuretics such as furosemide, bumetanide and ethacrynic acid increase calcium excretion, and acetazolamide alkalinises the urine, which favours calcium phosphate stone formation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.046 Q16') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-e135be790b', 'pharm-major-tranquilizer', 'mcq', 'Which of the following is a low-potency antipsychotic?', '["Haloperidol", "Olanzapine", "Fluphenazine", "Risperidone", "Chlorpromazine"]'::jsonb, 'Chlorpromazine', '[]'::jsonb, 'Chlorpromazine is the classic low-potency typical antipsychotic: large doses are needed, and it causes more sedation, anticholinergic effects and postural hypotension but fewer extrapyramidal effects. Haloperidol and fluphenazine are high-potency typicals with prominent extrapyramidal effects, and risperidone and olanzapine are atypicals effective at low milligram doses.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.047 Q18. Reworded from ''Which is not a high potency antipsychotic'' because potency grading is usually applied only to typical antipsychotics, which made the atypical options arguable.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-7cb4be06ed', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which general anaesthetic agent is formulated as a gas?', '["Morphine", "Nitrous oxide", "Halothane", "Methohexital", "Diazepam"]'::jsonb, 'Nitrous oxide', '[]'::jsonb, 'Nitrous oxide is a gas at room temperature and is supplied in cylinders. Halothane, like isoflurane and sevoflurane, is a volatile liquid that must be vaporised before inhalation. Methohexital and diazepam are given intravenously, and morphine is an opioid analgesic rather than a general anaesthetic.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.051 Q24') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-5bba1b2196', 'pharm-intravenous-fluids', 'mcq', 'Which IV fluid contains sodium, potassium, calcium, chloride and lactate (a bicarbonate precursor)?', '["Sodium lactate solution", "Ringer''s solution", "Darrow''s solution", "Normal saline", "Hartmann''s solution"]'::jsonb, 'Hartmann''s solution', '[]'::jsonb, 'Hartmann''s solution (compound sodium lactate, Ringer''s lactate) contains sodium, potassium, calcium, chloride and lactate, which the liver converts to bicarbonate. Plain Ringer''s solution has no lactate, normal saline contains only sodium chloride, and Darrow''s solution is rich in potassium with lactate but no calcium.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.056 Q31. Reworded: the paper said the fluid ''contains bicarbonate'', but Hartmann''s contains lactate, which is metabolised to bicarbonate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-63dd92dd44', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which drug should be infused slowly to prevent toxicity?', '["Zileuton", "Salbutamol", "Guaifenesin", "Terbinafine", "Aminophylline"]'::jsonb, 'Aminophylline', '[]'::jsonb, 'Aminophylline (theophylline ethylenediamine) has a narrow therapeutic index; rapid intravenous injection produces high peak levels that can cause arrhythmias, seizures, hypotension and death. It is therefore given as a slow IV loading dose over about 20 minutes, then an infusion guided by plasma levels. The other drugs are given orally or by inhalation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.059 Q34') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-5605f65549', 'pharm-intravenous-fluids', 'mcq', 'What is the most appropriate IV fluid for a patient with 40% burns and low blood pressure?', '["Normal saline", "Dextran 70", "Hetastarch", "Albumin", "Pentastarch"]'::jsonb, 'Normal saline', '[]'::jsonb, 'Major burns lose large volumes of sodium-rich fluid, and initial resuscitation uses isotonic crystalloid (ideally Ringer''s lactate, or normal saline) by a formula such as Parkland, 4 mL/kg per % burn in 24 hours. Hydroxyethyl starches increase kidney injury and death in critically ill patients and are now avoided; albumin is reserved for later.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.060 Q35. The paper''s marked answer appears to be a starch, but current guidelines recommend crystalloid resuscitation in burns and avoid hydroxyethyl starch. Option text read from a blurry photograph.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-17be453c46', 'pharm-antidepressants-and-lithium', 'mcq', 'Which drug has no role in the treatment of mania?', '["Carbamazepine", "Lithium carbonate", "Trazodone", "Lamotrigine", "Sodium valproate"]'::jsonb, 'Trazodone', '[]'::jsonb, 'Trazodone is a sedating antidepressant (a 5-HT2 antagonist and weak serotonin reuptake inhibitor), often used at low dose for insomnia; antidepressants can precipitate mania. Lithium, valproate and carbamazepine treat acute mania, and lamotrigine is a mood stabiliser that mainly prevents relapse of bipolar depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.064 Q7') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-8f01930c0c', 'pharm-drugs-used-in-angina', 'mcq', 'All the following are true regarding organic nitrates EXCEPT:', '["They relax vascular smooth muscle", "They act as nitric oxide donors", "They can cause postural hypotension", "They relax oesophageal smooth muscle", "They have more effect on small resistance vessels than on larger muscular vessels"]'::jsonb, 'They have more effect on small resistance vessels than on larger muscular vessels', '[]'::jsonb, 'Organic nitrates release nitric oxide, which activates guanylyl cyclase and relaxes smooth muscle. Their main action is venodilation and dilation of large conductance arteries such as the epicardial coronaries, with much less effect on small arterioles, so they reduce preload and cause postural hypotension. They also relax biliary and oesophageal smooth muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.067 Q11') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-b9ce1f1998', 'pharm-major-tranquilizer', 'mcq', 'Which tranquilliser has a high affinity for D2 receptors?', '["Olanzapine", "Aripiprazole", "Quetiapine", "Clozapine", "Chlorpromazine"]'::jsonb, 'Aripiprazole', '[]'::jsonb, 'Aripiprazole binds D2 receptors with very high affinity as a partial agonist, stabilising dopaminergic transmission; haloperidol also binds D2 strongly. Clozapine and quetiapine have low D2 affinity and dissociate quickly, which explains their low risk of extrapyramidal effects, while olanzapine and chlorpromazine have moderate D2 affinity with strong actions at other receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.069 Q20') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-opioids-cocaine-amphetami-682621e55f', 'pharm-addiction-to-opioids-cocaine-amphetamines', 'mcq', 'Which drug is not used in the long-term treatment of heroin addiction?', '["Levomethadyl acetate", "Naloxone", "Naltrexone", "Methadone", "Buprenorphine"]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone is a short-acting injectable opioid antagonist used to reverse acute overdose; it is not used alone for maintenance. Opioid dependence is treated with substitution using the long-acting agonists methadone and levomethadyl acetate, the partial agonist buprenorphine, or the long-acting oral antagonist naltrexone to block relapse.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.070 Q24. Replaced option ''Heroin'' (heroin-assisted treatment exists in some countries) with naltrexone, and added ''long-term'' to the stem; naloxone is also combined with buprenorphine to deter injection.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-df2fc3bf3f', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'Leukotriene pathway inhibitors are useful in the management of which of the following conditions?', '["Asthma", "Hypertension", "Bleeding disorders", "Peptic ulcer disease", "Inflammatory bowel disease"]'::jsonb, 'Asthma', '[]'::jsonb, 'Cysteinyl leukotrienes cause bronchoconstriction, mucus secretion and airway oedema. Receptor antagonists such as montelukast and zafirlukast, and the 5-lipoxygenase inhibitor zileuton, are used in the prophylaxis of asthma, especially aspirin-exacerbated and exercise-induced asthma, and in allergic rhinitis. They have no established role in the other conditions listed.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.074 Q31') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-7e74f8a9b9', 'pharm-antibody-preparations', 'mcq', 'Which of the following drugs is used to prevent the primary immune response of an Rh-negative mother to an Rh-positive newborn?', '["Cyclophosphamide", "Rho(D) immune globulin", "Ciclosporin", "Methotrexate", "Tacrolimus"]'::jsonb, 'Rho(D) immune globulin', '[]'::jsonb, 'Anti-D immune globulin given within 72 hours of delivery coats and clears fetal Rh-positive red cells from the maternal circulation before the mother''s immune system mounts a primary response. This prevents anti-D antibodies forming and so protects later pregnancies from haemolytic disease of the newborn. The other drugs are general immunosuppressants.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.075 Q41') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-97e6902b52', 'pharm-sedative-hypnotic-drugs', 'mcq', 'What is the mechanism of action of zolpidem?', '["Blockade of the action of glutamic acid", "Inhibition of GABA aminotransferase", "Activation of GABA-B receptors", "Antagonism of glycine receptors in the spinal cord", "Increased GABA-mediated chloride ion conductance"]'::jsonb, 'Increased GABA-mediated chloride ion conductance', '[]'::jsonb, 'Zolpidem is a non-benzodiazepine hypnotic (''Z-drug'') that binds the benzodiazepine site of GABA-A receptors containing α1 subunits. It enhances GABA-induced chloride influx and hyperpolarises neurons, causing sedation with little anticonvulsant or muscle-relaxant effect. Vigabatrin inhibits GABA transaminase, and baclofen activates GABA-B receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.077 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thrombolytic-drugs-antifibrinolytic-dr-cf4da56900', 'pharm-thrombolytic-drugs-antifibrinolytic-drugs', 'mcq', 'Adjunctive drugs in thrombolytic therapy for coronary artery disease include the following EXCEPT:', '["Beta blockers", "Tranexamic acid", "Heparin", "Aspirin", "Angiotensin-converting enzyme inhibitors"]'::jsonb, 'Tranexamic acid', '[]'::jsonb, 'Tranexamic acid is an antifibrinolytic that blocks plasminogen activation, so it would directly oppose thrombolysis and promote re-thrombosis. After fibrinolysis for myocardial infarction, patients receive aspirin and an anticoagulant such as heparin to prevent reocclusion, and β-blockers and ACE inhibitors to reduce infarct size, remodelling and mortality.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.079 Q50') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-7a4d10885f', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following is a non-selective beta blocker?', '["Timolol", "Acebutolol", "Esmolol", "Metoprolol", "Atenolol"]'::jsonb, 'Timolol', '[]'::jsonb, 'Timolol blocks β1 and β2 receptors equally and is used mainly as eye drops for glaucoma, where it reduces aqueous humour production; systemic absorption can still cause bronchospasm. Acebutolol, esmolol, metoprolol and atenolol are relatively β1-selective. Other non-selective agents include propranolol, nadolol, pindolol and sotalol.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.080 Q54') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-c947a2f06d', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which of the following adrenergic agonists is most suitable for asthma prophylaxis?', '["Terbutaline", "Salmeterol", "Ritodrine", "Albuterol", "Metaproterenol"]'::jsonb, 'Salmeterol', '[]'::jsonb, 'Long-acting β2 agonists such as salmeterol and formoterol give 12 hours of bronchodilation and are used for maintenance (prophylaxis), always together with an inhaled corticosteroid. Terbutaline, albuterol and metaproterenol are short-acting relievers, and ritodrine is a β2 agonist used to delay premature labour.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.081 Q59. The original options had no long-acting agent (the paper''s marked answer was terbutaline); replaced rimiterol with salmeterol so the question has a clear correct answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-7ea9d1691d', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which statement regarding sodium nitroprusside is true?', '["It increases intracellular cyclic GMP", "It can be administered orally", "Its hypotensive action begins within 30 minutes of administration", "It only dilates arterioles", "Its metabolite thiocyanate accumulates rapidly in patients with hepatic insufficiency"]'::jsonb, 'It increases intracellular cyclic GMP', '[]'::jsonb, 'Nitroprusside releases nitric oxide, which activates soluble guanylyl cyclase and raises cGMP, relaxing both arterioles and venules. It is given only by continuous IV infusion, acts within 30 seconds and wears off within minutes. Cyanide released in red cells is converted by the liver to thiocyanate, which accumulates in renal failure, not liver failure.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.084 Q65') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3a3634b1ee', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Effects of carbonic anhydrase inhibitors include all the following EXCEPT:', '["Increased phosphate excretion", "Decrease in urinary pH", "Decreased formation of aqueous humour", "Increased afferent arteriolar resistance", "Development of metabolic acidosis"]'::jsonb, 'Decrease in urinary pH', '[]'::jsonb, 'Acetazolamide blocks bicarbonate reabsorption in the proximal tubule, so bicarbonate is lost in the urine, raising urinary pH and causing hyperchloraemic metabolic acidosis. Increased sodium delivery to the macula densa constricts the afferent arteriole by tubuloglomerular feedback. It also increases phosphate excretion and reduces aqueous humour formation in glaucoma.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.085 Q67') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-bc7f4260fc', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'The following signs and symptoms are typical in the post-operative period as general anaesthesia wears off EXCEPT:', '["Hypotension", "Shivering", "Emergence excitement", "Hypoxia", "Tachycardia"]'::jsonb, 'Hypotension', '[]'::jsonb, 'As anaesthesia wears off, pain and sympathetic stimulation typically cause hypertension and tachycardia. Patients often shiver from heat loss during surgery, may have emergence delirium (especially after ketamine or sevoflurane), and can become hypoxic from residual respiratory depression and atelectasis. Hypotension is more a feature of deep anaesthesia than of emergence.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.087 Q74. Added ''EXCEPT'' to the stem, which the paper omitted. Post-operative hypotension can still occur from bleeding or residual drug effects, so this is a relative distinction.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-8c8c25693f', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'A 50-year-old man has frequent renal colic from calcium-containing stones. Workup shows a defect in proximal tubular calcium reabsorption, giving high concentrations of calcium salts in the tubular urine. Which diuretic is most useful in preventing recurrent calcium stones?', '["Spironolactone", "Hydrochlorothiazide", "Furosemide", "Acetazolamide", "Mannitol"]'::jsonb, 'Hydrochlorothiazide', '[]'::jsonb, 'Thiazides increase calcium reabsorption in the distal convoluted tubule, lowering urinary calcium, so they are the diuretic of choice in idiopathic hypercalciuria with recurrent calcium stones. Furosemide does the opposite, inhibiting paracellular calcium reabsorption in the loop of Henle and increasing calciuria; acetazolamide alkalinises the urine and favours calcium phosphate stones.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.088 Q80. The paper''s marked answer was furosemide, which increases urinary calcium; hydrochlorothiazide is correct.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-51754cef45', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which statement regarding halothane is false?', '["It is eliminated mainly via the lungs", "It is hepatotoxic", "It causes respiratory depression", "It causes hypertension", "It is not flammable"]'::jsonb, 'It causes hypertension', '[]'::jsonb, 'Halothane depresses myocardial contractility and lowers blood pressure, so it causes hypotension, not hypertension; it also sensitises the heart to catecholamine-induced arrhythmias. Most is exhaled unchanged, about 20% is metabolised, and an immune reaction to its metabolites can cause severe halothane hepatitis. It depresses respiration and is non-flammable.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.090 Q85') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-e55cd3fbf6', 'pharm-local-anesthetic-agents', 'mcq', 'The following are true of lignocaine EXCEPT:', '["It is bound to α1-acid glycoprotein", "It is excreted mainly in the urine as metabolites", "It is metabolised in the liver", "Sodium bicarbonate increases its ionisation in urine", "It is administered parenterally"]'::jsonb, 'Sodium bicarbonate increases its ionisation in urine', '[]'::jsonb, 'Lignocaine is a weak base, so acidifying the urine increases its ionisation and trapping in the tubule, while alkalinising with sodium bicarbonate decreases ionisation and increases reabsorption. Lignocaine is bound mainly to α1-acid glycoprotein, metabolised by hepatic enzymes and excreted as metabolites in the urine, and has high first-pass metabolism, so it is given parenterally.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.091 Q86. Clarified option b to ''excreted mainly in the urine as metabolites''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-digestants-and-drugs-used-to-dissolve--b22f156936', 'pharm-digestants-and-drugs-used-to-dissolve-gallstones-bile-acids', 'mcq', 'Management of steatorrhoea is best accomplished by the use of which agent?', '["Sucralfate", "Omeprazole", "Ondansetron", "Pancrelipase", "Mineral oil"]'::jsonb, 'Pancrelipase', '[]'::jsonb, 'Steatorrhoea from exocrine pancreatic insufficiency (chronic pancreatitis, cystic fibrosis) is treated by replacing lipase with pancrelipase taken with meals. Enteric coating, or co-prescribing a proton pump inhibitor, protects the enzymes from gastric acid, so omeprazole is only an adjunct. Sucralfate protects ulcers, ondansetron is an antiemetic and mineral oil is a lubricant laxative.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 p.093 Q92') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-0164e41864', 'pharm-local-anesthetic-agents', 'mcq', 'What is the most important effect of inadvertent intravenous administration of a large dose of an amide local anaesthetic?', '["Bronchoconstriction", "Seizures", "Hepatic damage", "Renal failure", "Tachycardia"]'::jsonb, 'Seizures', '[]'::jsonb, 'High plasma concentrations of amide local anaesthetics first cause CNS toxicity: circumoral numbness, tinnitus and restlessness, then generalised seizures, followed by coma and respiratory depression. Cardiovascular collapse with bradycardia, arrhythmias and hypotension follows at higher levels, especially with bupivacaine. Seizures are treated with a benzodiazepine and airway support.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2021/22) p.102 Q40. The paper''s marked answer was tachycardia; the classic and most important early effect is CNS toxicity with seizures.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-1477077596', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which antihypertensive drug does not act by inhibiting a part of the renin-angiotensin-aldosterone axis?', '["Candesartan", "Spironolactone", "Alpha-methyldopa", "Propranolol", "Aliskiren"]'::jsonb, 'Alpha-methyldopa', '[]'::jsonb, 'Methyldopa acts centrally: its metabolite α-methylnoradrenaline stimulates α2 receptors in the brainstem and reduces sympathetic outflow. Each of the others acts on the RAAS: aliskiren inhibits renin, propranolol blocks β1-mediated renin release from the juxtaglomerular cells, candesartan blocks AT1 receptors and spironolactone blocks aldosterone receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2021/22) p.103 Q43') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-da86f8fd60', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which statement regarding thiopental sodium is false?', '["It decreases brain metabolism", "It is not metabolised in the body", "It is used in brain surgery", "It has a very short duration of action after a single dose", "It decreases blood pressure"]'::jsonb, 'It is not metabolised in the body', '[]'::jsonb, 'Thiopental''s anaesthetic effect ends by redistribution from the brain to muscle and fat, but the drug is ultimately metabolised by the liver (slowly, partly to pentobarbital), so it accumulates after repeated doses or infusions. It reduces cerebral metabolic rate and intracranial pressure, which suits neurosurgery, and lowers blood pressure.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2021/22) p.104 Q39. Changed option d from ''has a very short half life'' (its elimination half-life is actually long, about 12 hours) to ''very short duration of action after a single dose''; reworded c slightly.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-49c2d641d6', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement regarding digoxin is true?', '["It is contraindicated in atrial fibrillation", "It has a positive inotropic effect", "It has largely hepatobiliary clearance", "It has a wide therapeutic index", "It has no effect on smooth muscle"]'::jsonb, 'It has a positive inotropic effect', '[]'::jsonb, 'By inhibiting Na+/K+ ATPase, digoxin raises intracellular sodium and, through the Na+/Ca2+ exchanger, intracellular calcium, increasing myocardial contractility. It is used to control ventricular rate in atrial fibrillation, is cleared mainly unchanged by the kidneys (digitoxin is the hepatically cleared glycoside), and has a narrow therapeutic index. It also affects gut and vascular smooth muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2021/22) p.110 Q23. Simplified option e from ''No effect on other smooth muscle except the heart'' (the heart is not smooth muscle).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-d3ee37d48a', 'pharm-antidepressants-and-lithium', 'mcq', 'Which is a tricyclic antidepressant?', '["Escitalopram", "Citalopram", "Amitriptyline", "Fluoxetine", "Bupropion"]'::jsonb, 'Amitriptyline', '[]'::jsonb, 'Amitriptyline is a tertiary-amine tricyclic that inhibits serotonin and noradrenaline reuptake and blocks muscarinic, H1 and α1 receptors, so it sedates and causes anticholinergic effects; low doses are used for neuropathic pain. Escitalopram, citalopram and fluoxetine are SSRIs, and bupropion is a noradrenaline-dopamine reuptake inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2021/22) p.113 Q7') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-renal-pharmacology-dru-3cc37095d5', 'pharm-introduction-to-renal-pharmacology-drugs-affecting-renal-water-c', 'mcq', 'Which of the following is not an antagonist of vasopressin?', '["Lixivaptan", "Satavaptan", "Saxagliptin", "Lithium", "Demeclocycline"]'::jsonb, 'Saxagliptin', '[]'::jsonb, 'Saxagliptin is a DPP-4 inhibitor (a ''gliptin'') used in type 2 diabetes. The vaptans (conivaptan, tolvaptan, lixivaptan, satavaptan) are vasopressin receptor antagonists, while lithium and demeclocycline are non-selective agents that blunt the collecting duct''s response to ADH and can be used in SIADH.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.115 Q1') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-e0be0423dd', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement regarding cardiac glycosides is true?', '["Digoxin may cause aberrations of colour perception", "Digoxin is preferred over digitoxin in patients with acute renal failure", "They activate Na+/K+ ATPase", "Atrial fibrillation is a common adverse property of digoxin", "Ouabain is used in emergencies owing to its rapid oral absorption"]'::jsonb, 'Digoxin may cause aberrations of colour perception', '[]'::jsonb, 'Digoxin toxicity commonly causes visual disturbance, including blurred vision and yellow-green colour distortion (xanthopsia), along with nausea, confusion and arrhythmias. Cardiac glycosides inhibit, not activate, Na+/K+ ATPase. Digoxin is renally cleared, so digitoxin is preferred in renal failure, and ouabain is poorly absorbed and given only intravenously.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.115 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-2aa8e70eda', 'pharm-calcium-channel-blocker', 'mcq', 'Which drug does not improve outcomes in heart failure with reduced ejection fraction?', '["Benazepril", "Eplerenone", "Carvedilol", "Amlodipine", "Sacubitril-valsartan"]'::jsonb, 'Amlodipine', '[]'::jsonb, 'Calcium channel blockers have no place in treating heart failure with reduced ejection fraction: non-dihydropyridines such as verapamil and diltiazem are negatively inotropic and worsen it, and amlodipine is merely neutral. It can be used only if needed for another reason such as hypertension. ACE inhibitors, mineralocorticoid antagonists, carvedilol and sacubitril-valsartan reduce mortality.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.116 Q7. Reworded from ''Which drug would you not use in congestive heart failure?'', since amlodipine is safe if needed. Replaced digoxin (which improves symptoms and admissions but not mortality, so arguable) with sacubitril-valsartan.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antibody-preparations-9d0ea2e841', 'pharm-antibody-preparations', 'mcq', 'Which of the following is not an immunosuppressive monoclonal antibody?', '["Alemtuzumab", "Daclizumab", "Basiliximab", "Muromonab-CD3", "Trastuzumab"]'::jsonb, 'Trastuzumab', '[]'::jsonb, 'Trastuzumab targets the HER2 receptor and is an anticancer antibody for HER2-positive breast and gastric cancer. Alemtuzumab (anti-CD52), muromonab-CD3 (anti-CD3) and basiliximab and daclizumab (anti-CD25, the IL-2 receptor α chain) deplete or block T cells and have been used to prevent or treat transplant rejection.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.116 Q8. Replaced abatacept (a CTLA4-Ig fusion protein, not an antibody, which made two options correct) with daclizumab.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-e569bb4e5b', 'pharm-antimuscarinic-agents', 'mcq', 'For an acute asthmatic attack in a 20-year-old alcoholic man with hypertension and congestive cardiac failure, which bronchodilator adds least cardiovascular stress?', '["Albuterol", "Salmeterol", "Theophylline", "Cromolyn sodium", "Ipratropium bromide"]'::jsonb, 'Ipratropium bromide', '[]'::jsonb, 'Inhaled ipratropium blocks muscarinic receptors in the airways and is minimally absorbed, so it causes little tachycardia or blood pressure change, which suits patients with heart disease. β-agonists cause tachycardia and arrhythmias, theophylline has a narrow therapeutic index with arrhythmia and seizure risk, salmeterol is too slow for acute attacks, and cromolyn is only prophylactic.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.116 Q10. Reworded from ''the best drug for treating an acute asthmatic attack'' because a short-acting β2 agonist remains first-line in acute asthma even with heart disease; the reworded stem asks which adds least cardiovascular stress.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-65ad546fba', 'pharm-intravenous-fluids', 'mcq', 'Hartmann''s solution has the following components EXCEPT:', '["Magnesium", "Calcium", "Sodium", "Potassium", "Lactate"]'::jsonb, 'Magnesium', '[]'::jsonb, 'Hartmann''s solution (compound sodium lactate) contains sodium 131, potassium 5, calcium 2, chloride 111 and lactate 29 mmol/L. The lactate is metabolised to bicarbonate. It contains no magnesium, unlike some balanced crystalloids such as Plasma-Lyte. It is used to replace losses from diarrhoea, burns and surgery.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.117 Q11. Changed option e from ''Bicarbonate'' to ''Lactate'': Hartmann''s contains lactate, not bicarbonate, so the original had two correct answers.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-ce67006409', 'pharm-antimuscarinic-agents', 'mcq', 'Which of the following is a long-acting antimuscarinic bronchodilator?', '["Aclidinium", "Terbutaline", "Montelukast", "Ipratropium", "Atropine"]'::jsonb, 'Aclidinium', '[]'::jsonb, 'Aclidinium is an inhaled long-acting muscarinic antagonist (LAMA) given twice daily for maintenance treatment of obstructive airway disease; tiotropium and umeclidinium are others. Ipratropium and atropine are short-acting antimuscarinics, terbutaline is a short-acting β2 agonist, and montelukast is a leukotriene receptor antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.117 Q12. Removed ''used in asthma'' from the stem: aclidinium is licensed for COPD; tiotropium is the LAMA licensed for asthma.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-acute-opioid-toxicity-7167dec63b', 'pharm-acute-opioid-toxicity', 'mcq', 'Acute opioid toxicity commonly presents with which triad?', '["Miosis, hypotension and coma", "Coma, miosis and respiratory depression", "Respiratory depression, miosis and bradycardia", "Coma, constipation and respiratory depression", "Miosis, hypothermia and coma"]'::jsonb, 'Coma, miosis and respiratory depression', '[]'::jsonb, 'The classic triad of opioid overdose is depressed consciousness or coma, pinpoint pupils and respiratory depression, which is the usual cause of death. It is treated with ventilatory support and IV naloxone, repeated or infused because naloxone wears off before long-acting opioids. Pupils may dilate later if hypoxia develops.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.117 Q13') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-61ce41a9f9', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'All of the following are true of β2-selective adrenoceptor agonists EXCEPT:', '["They activate adenylyl cyclase and increase cAMP", "They are administered by the inhalation route", "They have no effect on chronic inflammation in asthma", "Salmeterol is long acting", "The onset of action of salbutamol is 6 hours"]'::jsonb, 'The onset of action of salbutamol is 6 hours', '[]'::jsonb, 'Inhaled salbutamol acts within 1 to 5 minutes, peaks at 15 to 30 minutes and lasts 3 to 4 hours, which is why it is the reliever. β2 agonists act through Gs proteins to activate adenylyl cyclase and raise cAMP, relaxing bronchial smooth muscle, but they do not treat the underlying airway inflammation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.117 Q14') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-76cbaa1846', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'All of the following are true of chloroquine in the treatment of rheumatic diseases EXCEPT:', '["It has an elimination half-life of 3 days", "It is extensively bound in the skin and eyes", "It is often used for skin manifestations of SLE", "It takes 3 to 6 months for a response to be seen", "Ophthalmic toxicity rarely occurs at doses below 250 mg/day"]'::jsonb, 'It has an elimination half-life of 3 days', '[]'::jsonb, 'Chloroquine and hydroxychloroquine have a very large volume of distribution, concentrate in melanin-containing tissues such as skin and retina, and have elimination half-lives of about 45 days. As DMARDs they act slowly, over 3 to 6 months, and are useful for cutaneous lupus. Retinal toxicity is dose-related, so annual eye screening is recommended.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.118 Q19') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-topical-antimicrobials-f85951acd7', 'pharm-topical-antimicrobials', 'mcq', 'The following topical antibiotics can be used in the management of acne EXCEPT:', '["Sulfacetamide", "Metronidazole", "Clindamycin", "Mupirocin", "Erythromycin"]'::jsonb, 'Mupirocin', '[]'::jsonb, 'Mupirocin inhibits bacterial isoleucyl-tRNA synthetase and is used topically for impetigo and to eradicate nasal MRSA carriage, not for acne. Topical clindamycin and erythromycin, usually combined with benzoyl peroxide, target Cutibacterium acnes, while sulfacetamide and metronidazole are used for acne and acne rosacea.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.119 Q21') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-disinfectants-and-antiseptics-f4fee51f8b', 'pharm-disinfectants-and-antiseptics', 'mcq', 'All of the following are true about chlorhexidine EXCEPT:', '["It has a low water solubility", "It is equally active against cocci and rods", "It is not inhibited by blood and organic materials", "It is slower in action than alcohols", "It has a residual effect"]'::jsonb, 'It is equally active against cocci and rods', '[]'::jsonb, 'Chlorhexidine is a cationic biguanide that disrupts bacterial membranes. It is more active against Gram-positive cocci than Gram-negative rods, and has little activity against spores and mycobacteria. It binds to skin, giving a persistent residual effect that makes it ideal for surgical scrubs. It acts more slowly than alcohol and is relatively unaffected by organic matter.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.119 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-83eb3e8369', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following anti-adrenergic drugs blocks both alpha and beta receptors?', '["Labetalol", "Propranolol", "Pindolol", "Acebutolol", "Atenolol"]'::jsonb, 'Labetalol', '[]'::jsonb, 'Labetalol blocks α1 receptors and β1 and β2 receptors, so it lowers peripheral resistance without reflex tachycardia; IV labetalol is used in hypertensive emergencies and it is safe in pregnancy. Carvedilol has similar dual blockade. Propranolol and pindolol are non-selective β-blockers, while acebutolol and atenolol are β1-selective.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.119 Q24') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-a54b9592fa', 'pharm-preanesthetic-agent', 'mcq', 'Which is not a goal or aim of a preanaesthetic agent?', '["Antiemetic effect", "Amnesia for pre- and postoperative events", "Increased vagal stimulation", "Supplementing analgesia so that less anaesthetic is needed", "Relief of anxiety"]'::jsonb, 'Increased vagal stimulation', '[]'::jsonb, 'Premedication aims to relieve anxiety (benzodiazepines), provide amnesia and analgesia that reduce anaesthetic requirements (opioids), prevent nausea and vomiting (antiemetics) and reduce aspiration risk. Antimuscarinics such as glycopyrrolate are given to dry secretions and to block, not increase, vagal reflexes such as bradycardia during intubation or traction.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.120 Q25') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-fa16684cb0', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement regarding the use of corticosteroids in asthma management is true?', '["Corticosteroids have no effect on the frequency of asthma exacerbations", "Steroids have a brisk bronchodilator effect", "Beclomethasone is less lipid soluble than ciclesonide", "Long-term steroid therapy reduces mast cells in the respiratory mucosa", "The optimal effect of inhaled corticosteroids is seen within 5 minutes"]'::jsonb, 'Long-term steroid therapy reduces mast cells in the respiratory mucosa', '[]'::jsonb, 'Inhaled corticosteroids reduce the number of mast cells, eosinophils and T lymphocytes in the airway mucosa and suppress cytokine production, so with long-term use they reduce bronchial hyperreactivity and exacerbations. They are not direct bronchodilators, and their full benefit takes weeks to months. Ciclesonide is highly lipophilic, which prolongs its retention in lung tissue.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.120 Q26. The paper asked ''true ... except'' but four options were false; reworded the stem to ''Which statement is true?''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-a2001818a4', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which statement regarding aspirin is true?', '["It undergoes ion trapping in acidic urine", "Its antiplatelet effect lasts 2 days", "Long-term use increases the risk of colon cancer", "It reversibly inactivates platelet cyclo-oxygenase", "It is uricosuric at high doses"]'::jsonb, 'It is uricosuric at high doses', '[]'::jsonb, 'Salicylates have a dose-dependent effect on urate: low doses inhibit tubular urate secretion and raise serum urate, while high doses (over about 5 g/day) also block reabsorption and become uricosuric. Aspirin, a weak acid, is trapped in alkaline urine, irreversibly acetylates platelet COX-1 so its effect lasts the 8 to 10-day platelet lifespan, and reduces colorectal cancer risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.120 Q29') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-fentanyl-and-congeners-levorphanol-and-f702aad0c1', 'pharm-fentanyl-and-congeners-levorphanol-and-congeners-pethidine-and-c', 'mcq', 'All of the following are true of meperidine EXCEPT:', '["It has significant antimuscarinic effects", "It has a negative inotropic action", "Fentanyl is a congener", "It may cause seizures", "It is safe in atrial tachycardia"]'::jsonb, 'It is safe in atrial tachycardia', '[]'::jsonb, 'Meperidine (pethidine) has antimuscarinic activity that can increase heart rate and AV conduction, so it is avoided in tachyarrhythmias. It is negatively inotropic, and its metabolite normeperidine is a CNS excitant that accumulates in renal failure and causes seizures. Fentanyl and its relatives belong to the phenylpiperidine series of which meperidine is the parent.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.120 Q30') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-06e6b815ca', 'pharm-local-anesthetic-agents', 'mcq', 'The injection of local anaesthetics directly into tissue without taking into consideration the course of cutaneous nerves is referred to as:', '["Nerve block anaesthesia", "Infiltration anaesthesia", "Bier''s block", "Epidural anaesthesia", "Topical anaesthesia"]'::jsonb, 'Infiltration anaesthesia', '[]'::jsonb, 'Infiltration anaesthesia means injecting local anaesthetic directly into the tissue to be cut, regardless of the nerve supply, for example to suture a laceration; adding adrenaline prolongs it. A field block injects around an area to catch the nerves supplying it, a nerve block targets a named nerve, and Bier''s block is IV regional anaesthesia under a tourniquet.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.121 Q31') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-0ee053304e', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which statement about thiopental is false?', '["It activates the GABA-A receptor complex", "It is used in the management of refractory status epilepticus", "It decreases cerebral blood flow", "Its anaesthetic effects are terminated by hepatic metabolism", "It is an ultra-short-acting barbiturate"]'::jsonb, 'Its anaesthetic effects are terminated by hepatic metabolism', '[]'::jsonb, 'After a single induction dose, thiopental''s effect ends within minutes because the drug redistributes from the well-perfused brain to muscle and then fat, not because it is metabolised; hepatic metabolism is slow. It is an ultra-short-acting barbiturate that enhances GABA-A receptor function, lowers cerebral blood flow and ICP, and is used for refractory status epilepticus.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.122 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-af4e78f990', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Which of the following diuretics produces a predominantly water (rather than sodium) diuresis?', '["Acetazolamide", "Mannitol", "Triamterene", "Furosemide", "Hydrochlorothiazide"]'::jsonb, 'Mannitol', '[]'::jsonb, 'Mannitol is filtered but not reabsorbed, so it holds water in the tubule osmotically and produces a diuresis rich in water relative to sodium, which can raise plasma sodium. The others are natriuretics that block specific sodium transport: acetazolamide in the proximal tubule, furosemide in the loop, hydrochlorothiazide in the distal tubule and triamterene in the collecting duct.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.124 Q47. Reworded ''aquaretic agent'' (a term usually reserved for vasopressin antagonists) to describe a predominantly water diuresis.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-4-8-aminoquinolones-quinoline-methanol-59be6362f1', 'pharm-4-8-aminoquinolones-quinoline-methanols-phenanthrene-methanols-a', 'mcq', 'Which statement about antimalarials is true?', '["Chloroquine enhances conversion of haem to haemozoin", "Chloroquine is contraindicated in pregnancy", "Amodiaquine is used as a chemoprophylactic antimalarial drug", "Primaquine acts against the latent hepatic stages of Plasmodium vivax", "Chloroquine is the drug of choice for uncomplicated malaria in Kenya"]'::jsonb, 'Primaquine acts against the latent hepatic stages of Plasmodium vivax', '[]'::jsonb, 'Primaquine (and tafenoquine) kills the dormant liver hypnozoites of P. vivax and P. ovale, giving radical cure and preventing relapse; G6PD status must be checked first. Chloroquine prevents haem being polymerised to haemozoin, is safe in pregnancy, and is no longer used for falciparum malaria in Kenya, where artemether-lumefantrine is first-line. Amodiaquine is too toxic for prophylaxis.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.124 Q48. Changed ''late hepatic stages'' to ''latent hepatic stages'' (hypnozoites) for accuracy.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-3e5df7b9cb', 'pharm-lipid-lowering-agents', 'mcq', 'Which drug is least effective at lowering LDL cholesterol?', '["Colestipol", "Niacin", "Gemfibrozil", "Atorvastatin", "Ezetimibe"]'::jsonb, 'Gemfibrozil', '[]'::jsonb, 'Fibrates such as gemfibrozil activate PPAR-α, increasing lipoprotein lipase activity; they lower triglycerides and VLDL markedly and raise HDL, but have little effect on LDL, which can even rise in hypertriglyceridaemic patients. Statins lower LDL most, and colestipol, niacin and ezetimibe each reduce LDL by roughly 15 to 25%.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.126 Q56') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-4844d8ecbb', 'pharm-lipid-lowering-agents', 'mcq', 'Which lipid-lowering agent is incorrectly matched with its class?', '["Evolocumab: Apo B-100 synthesis inhibitor", "Ezetimibe: intestinal sterol absorption inhibitor", "Colesevelam: bile acid-binding resin", "Lovastatin: HMG-CoA reductase inhibitor", "Bezafibrate: fibric acid derivative"]'::jsonb, 'Evolocumab: Apo B-100 synthesis inhibitor', '[]'::jsonb, 'Evolocumab and alirocumab are monoclonal antibodies against PCSK9; by stopping PCSK9 from degrading LDL receptors, they increase LDL clearance by about 60%. The apolipoprotein B-100 synthesis inhibitor is mipomersen, an antisense oligonucleotide. The other pairings are correct: ezetimibe blocks NPC1L1 in the gut and colesevelam binds bile acids.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB CAT 2 2021) p.126 Q57') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-erythropoietin-myeloid-growth-factors--60406e0b2c', 'pharm-erythropoietin-myeloid-growth-factors-megakaryocyte-growth-facto', 'mcq', 'Which statement regarding erythropoietin is false?', '["It can cause hypertension through vasoconstriction", "It increases demand for iron", "It has angiogenic effects", "It can induce proliferation of smooth muscle cells", "It causes dementia"]'::jsonb, 'It causes dementia', '[]'::jsonb, 'Besides stimulating red cell production, erythropoietin has non-haematopoietic actions: it raises blood pressure through increased viscosity and vasoconstriction, promotes angiogenesis and smooth muscle proliferation, and is neuroprotective, with suggested benefits for mood and cognition. Its main adverse effects are hypertension and thrombosis, and iron stores must be adequate for it to work.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2021) p.128 Q100. Options were terse (''Vasoconstrictor'', ''Increase iron absorption'') and expanded to clear statements; option b changed to ''increases demand for iron'', as EPO''s effect on iron absorption is indirect.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-971cb47b7a', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement regarding amitriptyline is true?', '["It is useful in the treatment of urine retention", "Its effect on endogenous depression becomes manifest about 2 weeks after starting treatment", "It causes irritable bowel syndrome", "It is non-sedative", "It is used only in peripheral neuropathy associated with diabetes"]'::jsonb, 'Its effect on endogenous depression becomes manifest about 2 weeks after starting treatment', '[]'::jsonb, 'Reuptake blockade by tricyclics is immediate, but the antidepressant response appears only after 2 to 4 weeks, as receptor adaptation and neuroplastic changes develop; patients must be told this. Amitriptyline''s antimuscarinic action causes urinary retention, it is strongly sedating, and low doses are used for several neuropathic and functional pain syndromes, including IBS.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.130 Q87') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-2c7f2685ff', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'Which of the following is not a centrally acting sympatholytic?', '["Alpha-methyldopa", "Guanfacine", "Clonidine", "Guanadrel", "Guanabenz"]'::jsonb, 'Guanadrel', '[]'::jsonb, 'Guanadrel, like guanethidine, is an adrenergic neuron-blocking drug: it is taken up into peripheral sympathetic nerve endings by the noradrenaline transporter and depletes and blocks release of noradrenaline. It is too polar to enter the brain. Methyldopa, clonidine, guanfacine and guanabenz act on central α2 receptors to reduce sympathetic outflow.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.132 Q84. Reworded the fill-in-the-blank stem as a question.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-c6a0009643', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which antidiarrhoeal drug is combined with atropine?', '["Octreotide", "Berberine", "Diphenoxylate", "Acetorphan", "Bismuth subsalicylate"]'::jsonb, 'Diphenoxylate', '[]'::jsonb, 'Diphenoxylate is an opioid antidiarrhoeal related to pethidine. It is formulated with a small, subtherapeutic dose of atropine (co-phenotrope, Lomotil) so that anyone taking large doses for an opioid effect gets unpleasant antimuscarinic symptoms, which deters abuse. Atropine may also add slightly to the antidiarrhoeal effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.133 Q80. Corrected the spelling ''Baberine'' to berberine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-bf02d71273', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which statement about the renin-angiotensin system is correct?', '["Angiotensin-converting enzyme acts selectively on angiotensin I and no other substrates", "Angiotensin I is a potent vasoconstrictor peptide", "Decreased stretch of the renal afferent arteriolar baroreceptors leads to the release of renin", "Angiotensin-converting enzyme catalyses the conversion of angiotensinogen to angiotensin I", "Renin is found only in the kidney"]'::jsonb, 'Decreased stretch of the renal afferent arteriolar baroreceptors leads to the release of renin', '[]'::jsonb, 'Juxtaglomerular cells in the afferent arteriole act as baroreceptors: reduced stretch, from low blood pressure or volume, triggers renin release, as do reduced sodium delivery to the macula densa and β1 stimulation. Renin converts angiotensinogen to the inactive angiotensin I, ACE then forms angiotensin II and also degrades bradykinin, and renin-like activity exists in other tissues.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.135 Q75. Clarified option c from ''Decreased stretch receptor leads to the release of renin''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-d6e5a510c3', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which drug is used for the treatment of absence seizures?', '["Ethosuximide", "Phenobarbital", "Carbamazepine", "Gabapentin", "Phenytoin"]'::jsonb, 'Ethosuximide', '[]'::jsonb, 'Ethosuximide blocks thalamic T-type calcium channels, which drive the 3 Hz spike-and-wave discharges of absence seizures; it is a first choice for pure absence epilepsy, with valproate preferred when tonic-clonic seizures coexist. Carbamazepine, phenytoin, gabapentin and phenobarbital are ineffective in absences, and carbamazepine and phenytoin may worsen them.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.136 Q69') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-191c8f2155', 'pharm-lipid-lowering-agents', 'mcq', 'Which lipid-lowering drug is not appropriately matched to its mechanism of action?', '["Colestipol: binds bile acids in the intestinal lumen to prevent their reabsorption", "Ezetimibe: inhibits intestinal absorption of cholesterol and phytosterols by targeting the transport protein NPC1L1", "Evolocumab: inhibits proprotein convertase subtilisin/kexin type 9 (PCSK9)", "Lomitapide: antisense inhibition of ApoB-100 synthesis", "Fenofibrate: binds PPAR-α to up-regulate lipoprotein lipase"]'::jsonb, 'Lomitapide: antisense inhibition of ApoB-100 synthesis', '[]'::jsonb, 'Lomitapide inhibits microsomal triglyceride transfer protein (MTP), which loads lipids onto apoB, so the liver secretes less VLDL; it is used in homozygous familial hypercholesterolaemia and causes fatty liver. Antisense inhibition of apoB-100 synthesis describes mipomersen. The other drug-mechanism pairings are correct.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.137 Q65') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-e74af865e0', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Intrinsic sympathomimetic activity is a property of which of the following agents?', '["Carvedilol", "Nebivolol", "Metoprolol", "Pindolol", "Propranolol"]'::jsonb, 'Pindolol', '[]'::jsonb, 'Pindolol is a β-blocker with partial agonist activity (ISA): it blocks the effects of catecholamines but mildly stimulates β receptors itself, so it causes less resting bradycardia and less effect on lipids. Acebutolol also has ISA. Carvedilol, nebivolol, metoprolol and propranolol are pure antagonists without intrinsic sympathomimetic activity.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.138 Q64. Replaced labetalol (which has some β2 partial agonist activity, making two options defensible) with propranolol.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-1f3cacbe36', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'Which statement about opioids is true?', '["Morphine is more potent than fentanyl", "Opioids cause mydriasis", "Morphine relieves sharp intermittent pain better than dull continuous pain", "Opioids cross the placental barrier poorly", "Morphine relieves nociceptive pain better than neuropathic pain"]'::jsonb, 'Morphine relieves nociceptive pain better than neuropathic pain', '[]'::jsonb, 'Opioids work best on nociceptive pain from tissue injury; neuropathic pain from nerve damage responds less well and is often treated with tricyclics, gabapentinoids or SNRIs. Fentanyl is about 100 times more potent than morphine, opioids cause miosis, and they readily cross the placenta, causing neonatal respiratory depression. Dull continuous pain responds better than sharp intermittent pain.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.139 Q63. Replaced option c (''Morphine relieves somatic pain better than visceral pain'', which is debatable) with a clearly false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-7270896858', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement about salbutamol is true?', '["It is administered intramuscularly", "It is a long-acting drug", "It is a β-adrenoceptor blocker", "Its main effect is anti-inflammatory", "It causes skeletal muscle tremor"]'::jsonb, 'It causes skeletal muscle tremor', '[]'::jsonb, 'Salbutamol is a short-acting β2-adrenoceptor agonist usually given by inhaler or nebuliser, and occasionally IV in severe asthma. It relaxes bronchial smooth muscle but has no useful anti-inflammatory effect. Stimulation of β2 receptors in skeletal muscle causes the characteristic fine tremor; tachycardia and hypokalaemia are other dose-related effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.140 Q62') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-5d49ddbd3d', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which is not an effect of benztropine?', '["It has little effect on bradykinesia", "It improves the tremor and rigidity of parkinsonism", "It may cause confusion", "It improves tardive dyskinesias that result from the use of antipsychotic drugs", "It causes drowsiness"]'::jsonb, 'It improves tardive dyskinesias that result from the use of antipsychotic drugs', '[]'::jsonb, 'Central antimuscarinics such as benztropine improve tremor and rigidity in Parkinson''s disease and treat acute antipsychotic-induced dystonia and parkinsonism, but have little effect on bradykinesia. They typically worsen tardive dyskinesia. Their adverse effects include confusion and hallucinations, especially in the elderly, drowsiness, dry mouth and urinary retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.142 Q58') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-4ebc1f563b', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following is not a hypnotic drug?', '["Eszopiclone", "Zolpidem", "Buspirone", "Ramelteon", "Suvorexant"]'::jsonb, 'Buspirone', '[]'::jsonb, 'Buspirone is a 5-HT1A partial agonist used as a non-sedating anxiolytic for generalised anxiety; it takes weeks to work and has no hypnotic effect. The newer hypnotics include the Z-drugs (zolpidem, zaleplon, zopiclone, eszopiclone), the melatonin receptor agonist ramelteon and the orexin receptor antagonist suvorexant.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.143 Q54. Reworded from ''not a novel sedative hypnotic''. The paper marked ramelteon, but ramelteon is itself a newer hypnotic; buspirone is the only non-hypnotic option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-3a43b29ec4', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is not an adverse effect of hydrochlorothiazide?', '["Impaired carbohydrate tolerance", "Hyperlipidaemia", "Hyperuricaemia", "Hyperkalaemia", "Metabolic alkalosis"]'::jsonb, 'Hyperkalaemia', '[]'::jsonb, 'Thiazides increase sodium delivery to the collecting duct, where its exchange for potassium increases potassium loss, causing hypokalaemia and metabolic alkalosis, not hyperkalaemia. Their other adverse effects include hyperuricaemia, hyperglycaemia, raised lipids, hyponatraemia and hypercalcaemia. Hyperkalaemia is a risk with potassium-sparing diuretics, ACE inhibitors and ARBs.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.144 Q51') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-d68aa9a39d', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'All of the following are true of lamotrigine EXCEPT:', '["It is effective as monotherapy for focal seizures", "It is a phenyltriazine", "It has weak antifolate activity", "It may cause a life-threatening dermatitis", "It is less effective when combined with valproate"]'::jsonb, 'It is less effective when combined with valproate', '[]'::jsonb, 'Valproate inhibits lamotrigine''s glucuronidation and roughly doubles its levels; the combination is therapeutically synergistic but needs a lower, slower lamotrigine titration because the risk of Stevens-Johnson syndrome rises. Lamotrigine is a phenyltriazine sodium channel blocker effective as monotherapy for focal and generalised seizures, and it is a weak dihydrofolate reductase inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.145 Q50') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-513d163389', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement regarding the use of lithium carbonate in bipolar disorder is true?', '["It has no role in mania", "It has a wide therapeutic index", "It has a better side-effect profile than carbamazepine", "It is used only for acute episodes and has no value in prophylaxis", "It is not safe in patients with kidney disease"]'::jsonb, 'It is not safe in patients with kidney disease', '[]'::jsonb, 'Lithium is excreted almost entirely by the kidneys and has a narrow therapeutic index, so renal impairment, dehydration, thiazides, ACE inhibitors and NSAIDs cause toxicity. It can also damage the kidney (nephrogenic diabetes insipidus, interstitial nephritis). It treats acute mania and is the reference drug for long-term prophylaxis, reducing suicide risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.147 Q47') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-7acfc37a42', 'pharm-adrenoceptor-blockers', 'mcq', 'The following are non-selective α-adrenoceptor blockers EXCEPT:', '["Phenoxybenzamine", "Dibenamine", "Terazosin", "Tolazoline", "Phentolamine"]'::jsonb, 'Terazosin', '[]'::jsonb, 'Terazosin is a selective α1 antagonist used for hypertension and benign prostatic hyperplasia, with little effect on presynaptic α2 receptors, so it causes less reflex tachycardia. Phenoxybenzamine and dibenamine bind α1 and α2 receptors irreversibly, and phentolamine and tolazoline are competitive non-selective α antagonists that cause marked reflex tachycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.148 Q37. Replaced urapidil (also α1-selective, which made two options correct) with dibenamine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-64e4350be9', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which statement regarding hydralazine is true?', '["It has high oral bioavailability", "It is associated with drug-induced lupus in slow acetylators", "It acts via activation of potassium channels", "It causes predominantly venous vasodilation", "It is more potent than minoxidil"]'::jsonb, 'It is associated with drug-induced lupus in slow acetylators', '[]'::jsonb, 'Hydralazine is metabolised by N-acetylation, so slow acetylators have higher levels and a greater risk of a lupus-like syndrome. It dilates arterioles rather than veins, possibly through nitric oxide and cGMP, and has low oral bioavailability (about 25%) because of first-pass acetylation. Minoxidil, a potassium channel opener, is the more potent vasodilator.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.149 Q35') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-86faca6b75', 'pharm-calcium-channel-blocker', 'mcq', 'All of the following are true regarding calcium channel blocking drugs EXCEPT:', '["Nifedipine may cause reflex tachycardia", "Verapamil causes hypertension", "Nimodipine prevents spasm of cerebral vessels", "Diltiazem is contraindicated in Wolff-Parkinson-White syndrome with atrial fibrillation", "They may cause peripheral leg swelling"]'::jsonb, 'Verapamil causes hypertension', '[]'::jsonb, 'Verapamil lowers blood pressure and is used as an antihypertensive and antiarrhythmic. Dihydropyridines such as nifedipine dilate arterioles strongly, causing reflex tachycardia and ankle oedema. Nimodipine reduces vasospasm after subarachnoid haemorrhage, and AV nodal blockers such as diltiazem are avoided in WPW with atrial fibrillation because they can accelerate conduction down the accessory pathway.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.151 Q31. Replaced option a (''Nifedipine may worsen asthmatic attacks'', which is also false) with ''may cause reflex tachycardia''; clarified option d.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-73e86853d6', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which of the following is a selective β-adrenoceptor blocker?', '["Nadolol", "Timolol", "Atenolol", "Propranolol", "Pindolol"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol is a β1-selective (cardioselective) antagonist, as are metoprolol, bisoprolol, esmolol and acebutolol, so it is less likely to cause bronchospasm. Nadolol, timolol, propranolol and pindolol block β1 and β2 receptors equally. Selectivity is relative and is lost at high doses, so caution is still needed in asthma.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.152 Q28') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-327f40e3b7', 'pharm-inhalational-anesthetic-agents', 'mcq', 'All of the following are true of halothane EXCEPT:', '["It sensitises the myocardium to adrenaline", "It is a volatile liquid", "It is not explosive", "It is eliminated entirely via the lungs", "It causes hypotension"]'::jsonb, 'It is eliminated entirely via the lungs', '[]'::jsonb, 'About 20% of absorbed halothane is metabolised by hepatic cytochrome P450, and its trifluoroacetyl metabolites are implicated in immune-mediated halothane hepatitis; most of the rest is exhaled. It is a non-flammable volatile liquid that lowers blood pressure by myocardial depression and sensitises the heart to catecholamine-induced arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.154 Q3') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-193184959e', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is NOT an adverse effect of loop diuretics?', '["Severe dehydration", "Hypokalaemic metabolic alkalosis", "Ototoxicity", "Hypermagnesaemia", "Hyperuricaemia"]'::jsonb, 'Hypermagnesaemia', '[]'::jsonb, 'Loop diuretics block the Na+/K+/2Cl- cotransporter in the thick ascending limb, which abolishes the lumen-positive potential that drives paracellular reabsorption of magnesium and calcium. They therefore cause hypomagnesaemia and hypocalcaemia. Other adverse effects are volume depletion, hypokalaemic alkalosis, hyperuricaemia and dose-related ototoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.155 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-6610fc67df', 'pharm-drug-interactions', 'mcq', 'Which is a pharmacodynamic drug interaction?', '["Omeprazole and ketoconazole", "Warfarin and phenylbutazone", "Rifampicin and oral contraceptives", "Diazepam and pethidine", "Ciprofloxacin and aluminium hydroxide"]'::jsonb, 'Diazepam and pethidine', '[]'::jsonb, 'A pharmacodynamic interaction happens at the site of action without changing drug levels; diazepam and pethidine cause additive CNS and respiratory depression. Omeprazole reduces ketoconazole absorption by raising gastric pH, aluminium chelates ciprofloxacin, rifampicin induces contraceptive metabolism, and phenylbutazone displaces warfarin and inhibits its metabolism; these are pharmacokinetic.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.157 Q93') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-3c96943833', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'Which of the following is not an antitussive?', '["Codeine", "Dextromethorphan", "Noscapine", "Levopropoxyphene", "Nalmefene"]'::jsonb, 'Nalmefene', '[]'::jsonb, 'Nalmefene is an opioid receptor antagonist (μ and δ antagonist, partial κ agonist) used to reverse opioid overdose and to reduce alcohol consumption; it does not suppress cough. Codeine, pholcodine and levopropoxyphene are opioid antitussives, and dextromethorphan and noscapine are non-analgesic antitussives that act centrally on the cough centre.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.158 Q73') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-e25d976e28', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'Which is an example of allosteric modulation of receptors?', '["Phenoxybenzamine binding to α-adrenoceptors", "Heparin binding to protamine", "Aspirin binding to cyclo-oxygenase", "Buprenorphine interacting with morphine", "Benzodiazepines binding to GABA receptors"]'::jsonb, 'Benzodiazepines binding to GABA receptors', '[]'::jsonb, 'Benzodiazepines bind a site on the GABA-A receptor distinct from the GABA site and increase GABA''s effect on chloride channel opening, without opening the channel themselves; this is positive allosteric modulation. Phenoxybenzamine irreversibly blocks the orthosteric site, protamine neutralises heparin chemically, aspirin irreversibly acetylates COX, and buprenorphine competes with morphine at the μ receptor.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.160 Q61') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-25abaf1256', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which statement about alpha-methyldopa is false?', '["It is a prodrug", "It is a centrally acting sympathoplegic drug", "It is used in the treatment of hypertension in pregnancy", "It can cause gynaecomastia", "It is converted in the liver to its active form"]'::jsonb, 'It is converted in the liver to its active form', '[]'::jsonb, 'Methyldopa is taken up into central adrenergic neurons, where it is decarboxylated to α-methyldopamine and then converted to α-methylnoradrenaline, the active false transmitter that stimulates central α2 receptors. Its activation therefore occurs in the brain, not the liver. It is a first-line drug for hypertension in pregnancy, and raised prolactin can cause gynaecomastia and galactorrhoea.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.162 Q25. Simplified option e from ''Metabolized in the liver to alpha-methyldopamine''. Methyldopa does undergo some hepatic conjugation, but its activation is central.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-ff7a680492', 'pharm-calcium-channel-blocker', 'mcq', 'Which drug is not used in the treatment of chronic heart failure?', '["Nifedipine", "Digoxin", "Eplerenone", "Carvedilol", "Furosemide"]'::jsonb, 'Nifedipine', '[]'::jsonb, 'Short-acting dihydropyridines such as nifedipine cause reflex sympathetic activation and have negative inotropic effects, worsening heart failure and increasing events, so they are avoided. Furosemide relieves congestion, digoxin improves symptoms and reduces admissions, and carvedilol and eplerenone reduce mortality in heart failure with reduced ejection fraction.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.163 Q56') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-kinins-536ff261f5', 'pharm-kinins', 'mcq', 'Which drug enhances the effects of kinins?', '["Aprotinin", "Berinert", "Captopril", "Ecallantide", "Cinryze"]'::jsonb, 'Captopril', '[]'::jsonb, 'Angiotensin-converting enzyme is identical to kininase II, which breaks down bradykinin. ACE inhibitors such as captopril therefore increase bradykinin, which contributes to their vasodilator effect and causes dry cough and angioedema. Aprotinin is a protease inhibitor that blocks kallikrein, ecallantide inhibits kallikrein, and Berinert and Cinryze are C1-esterase inhibitor concentrates, all reducing kinin formation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2020/21) p.164 Q15') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-f803bc1f92', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement regarding inhaled corticosteroids used in the treatment of asthma is false?', '["They reduce bronchial reactivity", "Use of a spacer device can reduce oropharyngeal adverse effects", "They can be administered as dry powder", "Optimal bronchodilation is achieved within 30 minutes", "They decrease mast cell numbers in the respiratory mucosa"]'::jsonb, 'Optimal bronchodilation is achieved within 30 minutes', '[]'::jsonb, 'Inhaled corticosteroids are not bronchodilators; they reduce airway inflammation and bronchial hyperreactivity over weeks. They are given by metered-dose or dry-powder inhaler, and a spacer plus rinsing the mouth reduces oral thrush and dysphonia by cutting oropharyngeal deposition. Rapid bronchodilation within minutes comes from short-acting β2 agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.168 Q12') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-013b2d4385', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which anticonvulsant may cause a fatal aplastic anaemia?', '["Trimethadione", "Lamotrigine", "Piracetam", "Felbamate", "Levetiracetam"]'::jsonb, 'Felbamate', '[]'::jsonb, 'Felbamate causes aplastic anaemia in roughly 1 in 3,000 to 5,000 patients, plus severe hepatitis, so it is reserved for refractory epilepsy such as Lennox-Gastaut syndrome, with informed consent and blood monitoring. Lamotrigine''s main serious risk is Stevens-Johnson syndrome, trimethadione causes hemeralopia, and levetiracetam causes mood and behavioural changes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.170 Q24') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-e46ba16bb0', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which class of diuretics is effective in nephrogenic diabetes insipidus?', '["Osmotic diuretics", "Carbonic anhydrase inhibitors", "Loop diuretics", "Mercurial diuretics", "Thiazides"]'::jsonb, 'Thiazides', '[]'::jsonb, 'Thiazides paradoxically reduce urine volume in nephrogenic diabetes insipidus. Mild volume depletion increases proximal sodium and water reabsorption, so less fluid reaches the ADH-insensitive collecting duct. They are combined with a low-salt diet and sometimes amiloride, which is specific for lithium-induced nephrogenic DI.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.172 Q33. Specified ''nephrogenic'' diabetes insipidus; central DI is treated with desmopressin.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-68af56f069', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is not a clinical indication for carbonic anhydrase inhibitors?', '["Acute mountain sickness", "Calcium stone nephrolithiasis", "Glaucoma", "Urinary alkalinisation", "Metabolic alkalosis"]'::jsonb, 'Calcium stone nephrolithiasis', '[]'::jsonb, 'Acetazolamide raises urinary pH, and calcium phosphate is less soluble in alkaline urine, so it promotes calcium stones rather than preventing them. It is used for glaucoma (less aqueous humour), acute mountain sickness (metabolic acidosis stimulates breathing), alkalinising urine to clear uric acid or cystine, and correcting metabolic alkalosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.173 Q14') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-e03c7c35d5', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which antiemetic selectively blocks levodopa-induced vomiting without blocking its antiparkinsonian action?', '["Domperidone", "Ondansetron", "Carbidopa", "Metoclopramide", "Cisapride"]'::jsonb, 'Domperidone', '[]'::jsonb, 'Domperidone blocks D2 receptors in the chemoreceptor trigger zone, which lies outside the blood-brain barrier, but does not enter the brain itself, so it stops dopamine-induced nausea without reversing levodopa''s benefit in the striatum. Metoclopramide crosses into the brain and worsens parkinsonism. Carbidopa reduces nausea indirectly by limiting peripheral dopamine formation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.174 Q25') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-e8dceaddd7', 'pharm-antidepressants-and-lithium', 'mcq', 'Which drug is commonly used in the treatment of nicotine dependence?', '["Amitriptyline", "Duloxetine", "Bupropion", "Venlafaxine", "Mirtazapine"]'::jsonb, 'Bupropion', '[]'::jsonb, 'Bupropion inhibits noradrenaline and dopamine reuptake and is a weak nicotinic antagonist, reducing craving and withdrawal; it doubles quit rates. It lowers the seizure threshold, so it is avoided in epilepsy and eating disorders. Other smoking-cessation aids are nicotine replacement and varenicline, a partial agonist at α4β2 nicotinic receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.176 Q57') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-6fd0b9f5ba', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which statement about gabapentin is true?', '["It is poorly lipid soluble", "It is a cytochrome P450 enzyme inducer", "It increases presynaptic release of glutamate", "It is not bound to plasma proteins", "It is extensively metabolised in the liver"]'::jsonb, 'It is not bound to plasma proteins', '[]'::jsonb, 'Gabapentin is not protein-bound, not metabolised and not an enzyme inducer, so it has very few drug interactions; it is excreted unchanged by the kidneys. Although it was designed as a lipophilic GABA analogue, it acts by binding the α2δ subunit of voltage-gated calcium channels, which reduces release of excitatory transmitters such as glutamate.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.177 Q60') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-the-polypeptides-57f4e1c495', 'pharm-the-polypeptides', 'mcq', 'Which is not a vasoconstrictor peptide?', '["Bradykinin", "Vasopressin", "Urotensin II", "Angiotensin II", "Neuropeptide Y"]'::jsonb, 'Bradykinin', '[]'::jsonb, 'Bradykinin is a potent vasodilator: it acts on endothelial B2 receptors to release nitric oxide, prostacyclin and EDHF, and it increases capillary permeability. Angiotensin II, vasopressin (through V1 receptors), urotensin II and neuropeptide Y (co-released with noradrenaline from sympathetic nerves) are all vasoconstrictor peptides.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.178 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-36fec534dd', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'In the treatment of portal hypertension, which β-adrenoceptor antagonist would you use?', '["Atenolol", "Nebivolol", "Metoprolol", "Propranolol", "Carvedilol"]'::jsonb, 'Propranolol', '[]'::jsonb, 'Non-selective β-blockers lower portal pressure by two routes: β1 blockade reduces cardiac output, and β2 blockade leaves α-mediated splanchnic vasoconstriction unopposed, reducing portal inflow. Propranolol and nadolol are standard for preventing variceal bleeding. Selective β1 blockers such as atenolol, metoprolol and nebivolol lack the β2 effect.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.181 Q5. Carvedilol (a non-selective β-blocker with α1-blocking activity) is also recommended in current portal hypertension guidelines, so it is a defensible second answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-294abfa2e2', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which opioid antagonist has the longest duration of action?', '["Naloxone", "Nalbuphine", "Nalmefene", "Nalorphine", "Naltrexone"]'::jsonb, 'Naltrexone', '[]'::jsonb, 'Naltrexone is orally active and, with its active metabolite 6β-naltrexol, blocks opioid effects for up to 48 hours, so it is used once daily to prevent relapse in opioid and alcohol dependence. Naloxone acts for only 1 to 2 hours after IV injection, and nalmefene for about 8 to 10 hours. Nalbuphine and nalorphine are mixed agonist-antagonists.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.182 Q84. Reworded from ''longest half-life'': nalmefene''s plasma half-life is similar to or longer than naltrexone''s parent half-life, but naltrexone has the longest duration of action.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-5ef710c816', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement regarding lithium carbonate is true?', '["It is contraindicated in bipolar disorder", "It is safer than carbamazepine in mood disorders", "It can cause nephrogenic diabetes insipidus", "It has a wide therapeutic index", "It has no effect on the thyroid"]'::jsonb, 'It can cause nephrogenic diabetes insipidus', '[]'::jsonb, 'Lithium enters collecting duct cells through ENaC and reduces their response to ADH, causing polyuria and polydipsia in up to 40% of patients (nephrogenic diabetes insipidus); amiloride helps. Lithium is the reference mood stabiliser for bipolar disorder, has a narrow therapeutic index needing level monitoring, and commonly causes hypothyroidism and goitre.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.186 Q88') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cytoprotective-agents-bismuth-compound-4bfcff192f', 'pharm-cytoprotective-agents-bismuth-compounds-sucralfate-etc', 'mcq', 'Which statement regarding drug use in the treatment of peptic ulcer disease is false?', '["Misoprostol can protect against NSAID-associated gastric ulcer", "Bismuth has direct action against H. pylori", "Sucralfate is most effective at basic pH", "Cimetidine may cause decreased libido in men", "Proton pump inhibitors are prodrugs"]'::jsonb, 'Sucralfate is most effective at basic pH', '[]'::jsonb, 'Sucralfate needs an acid environment (pH below about 4) to polymerise into a sticky gel that binds ulcer bases, so it works best in acid conditions and should not be given with antacids or PPIs. Misoprostol replaces prostaglandins suppressed by NSAIDs, bismuth is directly toxic to H. pylori, cimetidine is anti-androgenic, and PPIs are prodrugs activated by acid.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.187 Q73') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-0d8748b43f', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which statement about propranolol is true?', '["A major mechanism of its antihypertensive action is reduction of cardiac output", "It increases insulin production and release", "Its use is safe in asthmatics", "It causes increased renin production", "It increases mortality in heart failure patients"]'::jsonb, 'A major mechanism of its antihypertensive action is reduction of cardiac output', '[]'::jsonb, 'Propranolol lowers blood pressure by reducing heart rate and cardiac output and by inhibiting β1-mediated renin release; peripheral resistance falls slowly over time. It blocks β2 receptors, so it can provoke bronchospasm and should be avoided in asthma, and it can impair insulin release and mask hypoglycaemia. β-blockers reduce mortality in heart failure.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.189 Q32. The paper said ''the primary mechanism ... is by reducing cardiac output''. Reduced renin release also contributes, so ''primary'' was softened to ''a major mechanism''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-945ac33754', 'pharm-local-anesthetic-agents', 'mcq', 'Which sensation disappears first after a local anaesthetic is administered?', '["Temperature", "Motor function", "Touch", "Deep pressure", "Pain"]'::jsonb, 'Pain', '[]'::jsonb, 'Small-diameter, unmyelinated C fibres and thinly myelinated Aδ fibres, which carry pain and temperature, are blocked before larger myelinated fibres. The usual order of loss is pain, then temperature, touch, deep pressure and finally motor function. Recovery occurs in the reverse order.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.191 Q47') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-h2-receptor-antagonist-proton-pump-inh-fd662befac', 'pharm-h2-receptor-antagonist-proton-pump-inhibitor', 'mcq', 'Which statement about cimetidine is true?', '["It acts on both H1 and H2 receptors", "It is poorly absorbed when taken orally", "It is a microsomal enzyme inducer", "It inhibits prolactin production", "It alters oestrogen metabolism in men"]'::jsonb, 'It alters oestrogen metabolism in men', '[]'::jsonb, 'Cimetidine inhibits hepatic oestradiol hydroxylation and blocks androgen receptors, so high doses cause gynaecomastia, impotence and galactorrhoea in men; it can also raise prolactin. It is a selective H2 antagonist, well absorbed orally, and a potent inhibitor (not inducer) of cytochrome P450, causing interactions with warfarin, phenytoin and theophylline.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.195 Q45') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-382499bbf2', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which drug is a prodrug that is activated in the brain?', '["Verapamil", "Methyldopa", "Doxazosin", "Nitroprusside", "Clonidine"]'::jsonb, 'Methyldopa', '[]'::jsonb, 'Methyldopa enters adrenergic neurons in the brain, where dopa decarboxylase and dopamine β-hydroxylase convert it to α-methylnoradrenaline. This false transmitter stimulates presynaptic α2 receptors in the brainstem and reduces sympathetic outflow. Clonidine acts on the same receptors directly, without activation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.196 Q13') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-dcea4b383f', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'All of the following are true of routes of drug administration EXCEPT:', '["Absorption of drugs from the gluteus muscle is less in females than in males", "Inadvertent intra-arterial injection during IV administration can cause gangrene", "Oral absorption of aspirin is slowed by food", "In the inhalation route, an anaesthetic''s potency is proportional to its fat/blood partition coefficient", "First-pass effect is avoided by rectal administration into the lower third of the rectum"]'::jsonb, 'In the inhalation route, an anaesthetic''s potency is proportional to its fat/blood partition coefficient', '[]'::jsonb, 'Inhaled anaesthetic potency correlates with lipid solubility measured as the oil:gas partition coefficient (the Meyer-Overton rule), and is expressed as MAC. The blood:gas coefficient governs speed of induction, not potency. Women have more gluteal fat, so IM gluteal absorption is slower, and drugs absorbed from the lower rectum partly bypass the portal circulation.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.199 Q90. Reworded option b from ''Gangrene is a complication of the venous route'' to inadvertent intra-arterial injection, and option c to ''slowed by food''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-fcf154e1f6', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which of the following is not a side effect of phenytoin?', '["Iron deficiency anaemia", "Gum hypertrophy", "Hirsutism", "Acne", "Ataxia"]'::jsonb, 'Iron deficiency anaemia', '[]'::jsonb, 'Phenytoin interferes with folate absorption and metabolism, causing megaloblastic anaemia rather than iron deficiency. Its other chronic effects include gingival hyperplasia, hirsutism, acne and coarsening of facial features, osteomalacia, and dose-related cerebellar signs such as nystagmus and ataxia. Plasma levels are monitored because of saturation kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.200 Q93') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-c723f3225d', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which drug is not used in chronic heart failure?', '["Carvedilol", "Salbutamol", "Digoxin", "Furosemide", "Spironolactone"]'::jsonb, 'Salbutamol', '[]'::jsonb, 'Salbutamol is a β2 agonist bronchodilator; in heart failure it causes tachycardia and arrhythmias and has no role. Chronic heart failure with reduced ejection fraction is treated with loop diuretics such as furosemide for congestion, ACE inhibitors or ARNIs, β-blockers such as carvedilol, mineralocorticoid antagonists such as spironolactone, SGLT2 inhibitors, and digoxin for symptoms.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB EOY 2019/20) p.201 Q28') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-4490b91830', 'pharm-inhalational-anesthetic-agents', 'mcq', 'The rate at which a therapeutic concentration of an inhaled anaesthetic is achieved depends on all of the following EXCEPT:', '["Pulmonary ventilation", "Pulmonary blood flow", "Its solubility properties", "Its concentration in the inspired air", "Renal blood flow"]'::jsonb, 'Renal blood flow', '[]'::jsonb, 'Uptake of an inhaled anaesthetic depends on its inspired concentration, alveolar ventilation, its blood:gas solubility, pulmonary blood flow (cardiac output), and the arteriovenous concentration gradient. These agents are eliminated mainly through the lungs, so renal blood flow plays no part in reaching therapeutic brain concentrations.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.205 Q16. Photographed screen with faint option text; options were read with some difficulty.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-cf919ce8d2', 'pharm-preanesthetic-agent', 'mcq', 'Atropine is used as a preanaesthetic medication to reduce:', '["Pain", "Secretions", "Vomiting", "Gastric acid", "Anxiety"]'::jsonb, 'Secretions', '[]'::jsonb, 'Atropine blocks muscarinic receptors on salivary and bronchial glands, drying secretions that might otherwise obstruct the airway or cause laryngospasm, especially with irritant agents such as ether. It also prevents vagal bradycardia during intubation or surgical traction. Glycopyrrolate is now preferred because it does not cross the blood-brain barrier.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.206 Q14. Photographed screen with faint option text.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-3feac47066', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following local anaesthetic agents is an ester?', '["Ropivacaine", "Procaine", "Bupivacaine", "Lidocaine", "Prilocaine"]'::jsonb, 'Procaine', '[]'::jsonb, 'Local anaesthetics are esters or amides, a distinction that determines metabolism and allergy. Esters (cocaine, procaine, chloroprocaine, tetracaine, benzocaine) are hydrolysed by plasma cholinesterase, and their metabolite PABA can cause allergy. Amides have an ''i'' before ''-caine'' (lidocaine, bupivacaine, ropivacaine, prilocaine) and are metabolised in the liver.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.207 Q6') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-14d8762f47', 'pharm-major-tranquilizer', 'mcq', 'Which of the following is not an adverse effect of chlorpromazine?', '["Tardive dyskinesia", "Postural hypotension", "Xerostomia", "Schizophrenia", "Neuroleptic malignant syndrome"]'::jsonb, 'Schizophrenia', '[]'::jsonb, 'Schizophrenia is the main indication for chlorpromazine, not an adverse effect. As a low-potency phenothiazine it blocks D2, muscarinic, α1 and H1 receptors, causing extrapyramidal effects, tardive dyskinesia and neuroleptic malignant syndrome, dry mouth (xerostomia), postural hypotension and sedation, plus cholestatic jaundice and photosensitivity.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.208 Q20. Replaced option b (read as ''Narcolepsy'', also not an adverse effect) with postural hypotension. Photographed screen hard to read.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-eace9f2965', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which of the following is a class Ib antiarrhythmic agent?', '["Quinidine", "Propafenone", "Procainamide", "Lidocaine", "Flecainide"]'::jsonb, 'Lidocaine', '[]'::jsonb, 'Class Ib drugs such as lidocaine and mexiletine block sodium channels with very rapid kinetics, preferentially affecting depolarised, ischaemic tissue and shortening the action potential; they are used for ventricular arrhythmias. Quinidine and procainamide are class Ia, and flecainide and propafenone are class Ic, which have the slowest binding kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.211 Q53') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-1436dd589f', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which statement about succinylcholine is true?', '["Its duration of action is 1 to 2 hours", "It does not release histamine", "Its onset of action is 20 minutes", "It paralyses respiratory muscles first", "It has a longer duration of action than acetylcholine"]'::jsonb, 'It has a longer duration of action than acetylcholine', '[]'::jsonb, 'Succinylcholine resists acetylcholinesterase and is hydrolysed only by plasma butyrylcholinesterase, so it persists at the end plate far longer than acetylcholine (milliseconds), causing prolonged depolarisation and block. It acts within about a minute, lasts 5 to 10 minutes and releases some histamine. Paralysis spreads from small muscles to limbs and trunk, and the diaphragm is affected last.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.212 Q43') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-908827c49d', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which of the following agents used in asthma is a mast cell stabiliser?', '["Omalizumab", "Formoterol", "Salbutamol", "Cromolyn sodium", "Aminophylline"]'::jsonb, 'Cromolyn sodium', '[]'::jsonb, 'Sodium cromoglycate (cromolyn) and nedocromil inhibit mast cell degranulation, possibly through chloride channel effects. They are poorly absorbed, so they are inhaled, used prophylactically before allergen or exercise exposure, and have no bronchodilator action. Omalizumab is an anti-IgE antibody, formoterol and salbutamol are β2 agonists, and aminophylline is a methylxanthine.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.213 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-12fde3d947', 'pharm-major-tranquilizer', 'mcq', 'Which of the following is a second-generation antipsychotic drug?', '["Risperidone", "Fluphenazine", "Pimozide", "Haloperidol", "Chlorpromazine"]'::jsonb, 'Risperidone', '[]'::jsonb, 'Risperidone is an atypical (second-generation) antipsychotic that blocks 5-HT2A receptors more strongly than D2 receptors, giving fewer extrapyramidal effects at low doses, though it raises prolactin. Fluphenazine and chlorpromazine (phenothiazines), haloperidol (a butyrophenone) and pimozide (a diphenylbutylpiperidine) are first-generation typical agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.215 Q37') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-9aab44865f', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following statements is false?', '["Ethanol has sedative and anxiolytic effects", "Benzodiazepines cause retrograde amnesia", "Benzodiazepines are safer hypnotics than barbiturates", "Chloral hydrate can cause GIT irritation and epigastric pain", "Diphenhydramine is effective in the treatment of some types of insomnia"]'::jsonb, 'Benzodiazepines cause retrograde amnesia', '[]'::jsonb, 'Benzodiazepines cause anterograde amnesia, impairing memory of events after the dose, which is why midazolam is useful before procedures; memories formed before the dose are not lost. They are safer than barbiturates because they have a ceiling on CNS depression when taken alone. Chloral hydrate irritates the stomach, and sedating antihistamines are used for mild insomnia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.216 Q18') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-a66729c086', 'pharm-antidepressants-and-lithium', 'mcq', 'Which is not an antidepressant drug?', '["Escitalopram", "Mirtazapine", "Cabergoline", "Amitriptyline", "Venlafaxine"]'::jsonb, 'Cabergoline', '[]'::jsonb, 'Cabergoline is an ergot-derived dopamine D2 agonist used for hyperprolactinaemia, prolactinomas and to suppress lactation. Escitalopram is an SSRI, mirtazapine an α2 antagonist that increases noradrenaline and serotonin release, amitriptyline a tricyclic, and venlafaxine a serotonin-noradrenaline reuptake inhibitor.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.217 Q51') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-85c8ec18ef', 'pharm-adrenoceptor-blockers', 'mcq', 'Phenoxybenzamine is a ______ at the α-adrenoceptor. Which term fits?', '["Full agonist", "Non-competitive (irreversible) antagonist", "Competitive antagonist", "Allosteric modulator", "Partial agonist"]'::jsonb, 'Non-competitive (irreversible) antagonist', '[]'::jsonb, 'Phenoxybenzamine forms a reactive ethyleneimonium intermediate that binds covalently to α1 and α2 receptors, blocking them irreversibly. Its effect lasts until new receptors are synthesised, about 14 to 48 hours, and cannot be overcome by more agonist. It is used to prepare patients with phaeochromocytoma for surgery. Phentolamine, by contrast, is a reversible competitive antagonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.218 Q46') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-lipid-lowering-agents-bddc213d90', 'pharm-lipid-lowering-agents', 'mcq', 'Which drug acts by inhibition of HMG-CoA reductase?', '["Ezetimibe", "Febuxostat", "Clofibrate", "Niacin", "Atorvastatin"]'::jsonb, 'Atorvastatin', '[]'::jsonb, 'Atorvastatin, like all statins, competitively inhibits HMG-CoA reductase, the rate-limiting step in cholesterol synthesis. Falling hepatic cholesterol up-regulates LDL receptors, increasing LDL clearance from the blood. Ezetimibe blocks intestinal sterol uptake, clofibrate is a fibrate, niacin reduces VLDL secretion, and febuxostat inhibits xanthine oxidase.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.220') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-2550850e88', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Indicate a cholinesterase inhibitor that has an additional direct nicotinic agonist effect:', '["Carbachol", "Echothiophate", "Lobeline", "Neostigmine", "Edrophonium"]'::jsonb, 'Neostigmine', '[]'::jsonb, 'Neostigmine is a quaternary carbamate cholinesterase inhibitor that also stimulates nicotinic receptors at the neuromuscular junction directly, which adds to its value in myasthenia gravis and in reversing non-depolarising block. Carbachol is a direct agonist, not a cholinesterase inhibitor, echothiophate is an organophosphate, and lobeline is a nicotinic agonist only.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (BDS EOY 2020) p.221. Edrophonium is also reported to have some direct nicotinic agonist action, so the distinction depends on the textbook used.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-33498015dc', 'pharm-local-anesthetic-agents', 'mcq', 'Which is an amide local anaesthetic agent?', '["Benzocaine", "Cocaine", "Procaine", "Bupivacaine", "Tetracaine"]'::jsonb, 'Bupivacaine', '[]'::jsonb, 'Bupivacaine is a long-acting amide local anaesthetic used for epidural and spinal anaesthesia; amides are metabolised by hepatic CYP enzymes and rarely cause allergy. Benzocaine, cocaine, procaine and tetracaine are esters hydrolysed by plasma cholinesterase. A quick rule: amide names contain an ''i'' before ''-caine''.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB Special/Supp 2020) p.224') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-receptors-and-signal-transduction-mech-ccc2a0a7ed', 'pharm-receptors-and-signal-transduction-mechanisms', 'mcq', 'In which drug action are receptors (in the broad sense of a specific macromolecular target) involved?', '["Osmotic effect of mannitol", "Bulk-forming laxatives", "Neutralisation of hydrochloric acid by an antacid", "Chelation of heavy metals like lead", "Inhibition of acetylcholinesterase by neostigmine"]'::jsonb, 'Inhibition of acetylcholinesterase by neostigmine', '[]'::jsonb, 'In the broad pharmacological sense, a receptor is any specific macromolecule that a drug binds to produce its effect, including enzymes such as acetylcholinesterase. Mannitol and bulk laxatives act through physical (osmotic or bulk) properties, antacids by chemical neutralisation, and chelators by binding metal ions, none of which involves a specific receptor.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB Special/Supp 2020) p.227. Added the broad definition of ''receptor'' to the stem: acetylcholinesterase is an enzyme target, so the item depends on that definition.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-1e1ae79a39', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which is a non-sedative anxiolytic?', '["Buspirone", "Hydroxyzine", "Meprobamate", "Diazepam", "Alprazolam"]'::jsonb, 'Buspirone', '[]'::jsonb, 'Buspirone is a 5-HT1A partial agonist that relieves generalised anxiety without sedation, muscle relaxation, anticonvulsant effect, dependence or interaction with alcohol. Its effect takes 1 to 2 weeks to appear, so it is useless for acute panic. Hydroxyzine is a sedating antihistamine, meprobamate a carbamate sedative, and diazepam and alprazolam are benzodiazepines.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB Special/Supp 2020) p.236. Photographed screen with faint option text.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-f4e942b6ae', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which diuretic inhibits the action of aldosterone?', '["Spironolactone", "Hydrochlorothiazide", "Amiloride", "Triamterene", "Torsemide"]'::jsonb, 'Spironolactone', '[]'::jsonb, 'Spironolactone competitively blocks the cytoplasmic mineralocorticoid receptor in collecting duct cells, preventing aldosterone-induced synthesis of sodium channels and Na+/K+ ATPase. Amiloride and triamterene also spare potassium but act by directly blocking epithelial sodium channels, independently of aldosterone. Hydrochlorothiazide and torsemide act earlier in the nephron.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt1 (MBChB Special/Supp 2020) p.237') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-e8cadb08b1', 'pharm-major-tranquilizer', 'mcq', 'Which of the following is not a high-potency antipsychotic agent?', '["Fluphenazine", "Haloperidol", "Thiothixene", "Quetiapine", "Pimozide"]'::jsonb, 'Quetiapine', '[]'::jsonb, 'Quetiapine binds D2 receptors weakly and dissociates quickly, so it needs doses of several hundred milligrams and causes few extrapyramidal effects; it is a low-potency atypical with prominent sedation from H1 blockade. Fluphenazine, haloperidol, thiothixene and pimozide are high-potency typical antipsychotics effective at a few milligrams but with frequent extrapyramidal reactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.002. Replaced olanzapine (whose potency classification is debatable) with pimozide.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-absorption-fbc724b29b', 'pharm-absorption', 'mcq', 'The main mechanism of absorption of most drugs from the GI tract is:', '["Endocytosis and exocytosis", "Passive diffusion (lipid diffusion)", "Osmosis", "Filtration (aqueous diffusion)", "Active transport (carrier-mediated diffusion)"]'::jsonb, 'Passive diffusion (lipid diffusion)', '[]'::jsonb, 'Most drugs are absorbed by passive diffusion of the un-ionised, lipid-soluble form across epithelial membranes, down a concentration gradient and without energy. The rate depends on lipid solubility, pKa and surface area, which is why the small intestine absorbs most drugs. Carrier-mediated transport matters only for drugs resembling nutrients, such as levodopa.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.008') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-290b675e76', 'pharm-local-anesthetic-agents', 'mcq', 'Which adverse effect is characteristic of lidocaine?', '["Extrapyramidal disorders", "Paraesthesia", "Agranulocytosis", "Myalgia", "Bronchospasm"]'::jsonb, 'Paraesthesia', '[]'::jsonb, 'Early systemic lidocaine toxicity affects the CNS: circumoral and tongue numbness or tingling (paraesthesia), light-headedness, tinnitus, visual disturbance and slurred speech, progressing to muscle twitching, seizures and coma at higher levels. These warning signs appear before cardiovascular depression. Lidocaine does not cause extrapyramidal effects, agranulocytosis or bronchospasm.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.009. Photographed screen; paper marks differed between two copies of the question (bronchospasm and paraesthesia).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cough-suppressants-and-expectorants-be1988a050', 'pharm-cough-suppressants-and-expectorants', 'mcq', 'The following are all mucolytic agents EXCEPT:', '["Carbocisteine", "Acetylcysteine", "Noscapine", "Bromhexine", "Ambroxol"]'::jsonb, 'Noscapine', '[]'::jsonb, 'Noscapine is a non-addictive opium alkaloid that suppresses cough centrally; it does not alter mucus. Mucolytics thin sputum: acetylcysteine and carbocisteine break disulphide bonds in mucoproteins, and bromhexine and its metabolite ambroxol depolymerise mucopolysaccharides and increase serous secretion.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.012') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-effects-of-disease-on-drug-disposition-3b48aaef6d', 'pharm-effects-of-disease-on-drug-disposition', 'mcq', 'In which of the following conditions are drug dose adjustments most easily predictable?', '["Thyrotoxicosis", "Congestive heart failure", "Chronic renal failure", "Ulcerative colitis", "Acute hepatic failure"]'::jsonb, 'Chronic renal failure', '[]'::jsonb, 'Renal elimination of many drugs falls in proportion to glomerular filtration rate, which can be estimated from serum creatinine (creatinine clearance or eGFR), so doses of renally cleared drugs can be calculated. No equivalent marker predicts hepatic clearance in liver failure, and the effects of heart failure, thyrotoxicosis or bowel disease on drug handling are variable.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.013') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thyroid-physiology-thyroid-hormonal-tr-93b7c4d8c7', 'pharm-thyroid-physiology-thyroid-hormonal-treatment-antithyroid-drugs', 'mcq', 'Which β-adrenoceptor antagonist is used in thyrotoxicosis treatment?', '["Atenolol", "Propranolol", "Labetalol", "Carvedilol", "Nebivolol"]'::jsonb, 'Propranolol', '[]'::jsonb, 'Propranolol rapidly controls the adrenergic symptoms of thyrotoxicosis, such as tachycardia, tremor, anxiety and sweating, while antithyroid drugs take weeks to work. In high doses it also weakly inhibits peripheral conversion of T4 to T3. It is the traditional choice, though cardioselective agents can be used where β2 blockade is a problem.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.022. Atenolol is also used for symptom control in thyrotoxicosis; propranolol is the classic answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-826698cdfa', 'pharm-drug-agonists-and-antagonists', 'mcq', 'An antagonist is a substance that:', '["Binds to receptors and initiates changes in cell function, producing a maximal effect", "Binds to receptors and initiates changes in cell function, producing a submaximal effect", "Facilitates excretion of another drug", "Interacts with plasma proteins and doesn''t produce any effect", "Binds to receptors without directly altering their functions"]'::jsonb, 'Binds to receptors without directly altering their functions', '[]'::jsonb, 'An antagonist has affinity for a receptor but no intrinsic efficacy: it occupies the receptor without activating it and so prevents agonists from acting. A full agonist produces a maximal response and a partial agonist only a submaximal response even at full occupancy. Antagonism may be competitive (surmountable) or non-competitive.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (MBChB Special/Supp 2020) p.027') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-c78d4c50a6', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Angiotensin-converting enzyme inhibitors increase the levels of which vasodilator?', '["Vasopressin", "Angiotensin II", "Urotensin", "Bradykinin", "Endothelins"]'::jsonb, 'Bradykinin', '[]'::jsonb, 'ACE is the same enzyme as kininase II, which inactivates bradykinin. ACE inhibitors therefore raise bradykinin levels, which adds to their vasodilator effect through nitric oxide and prostaglandins. Excess bradykinin also explains the dry cough and angioedema. Angiotensin II, vasopressin, urotensin and endothelins are vasoconstrictors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.038 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-1adcb73343', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which antiemetic causes galactorrhoea?', '["Metoclopramide", "Dolasetron", "Hyoscine", "Aprepitant", "Dronabinol"]'::jsonb, 'Metoclopramide', '[]'::jsonb, 'Metoclopramide blocks D2 receptors, including those on pituitary lactotrophs, where dopamine normally inhibits prolactin release. The resulting hyperprolactinaemia can cause galactorrhoea, gynaecomastia and menstrual disturbance; domperidone does the same. Dolasetron (5-HT3), hyoscine (muscarinic), aprepitant (NK1) and dronabinol (cannabinoid) do not raise prolactin.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.039 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-511bbdf2e1', 'pharm-drugs-used-in-angina', 'mcq', 'Which statement regarding organic nitrates is false?', '["They can cause postural hypotension", "They relax biliary and oesophageal smooth muscle", "Tolerance develops with repeated doses", "They improve the balance of myocardial oxygen supply and demand", "They have no effect on coronary artery tone"]'::jsonb, 'They have no effect on coronary artery tone', '[]'::jsonb, 'Nitrates dilate large epicardial coronary arteries and collaterals and relieve coronary spasm, which is why they work in variant angina; their main antianginal benefit, however, comes from venodilation reducing preload and oxygen demand. Continuous exposure produces tolerance, so a nitrate-free interval is needed, and venous pooling causes postural hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.040 Q48. Clarified option d from ''Improve myocardial oxygen consumption''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-b130a90cee', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which of the following is not a positive inotropic drug?', '["Propranolol", "Digoxin", "Levosimendan", "Milrinone", "Dobutamine"]'::jsonb, 'Propranolol', '[]'::jsonb, 'Propranolol blocks cardiac β1 receptors and is negatively inotropic and chronotropic. Digoxin inhibits Na+/K+ ATPase, levosimendan sensitises troponin C to calcium, milrinone inhibits phosphodiesterase-3 to raise cAMP, and dobutamine stimulates β1 receptors, so all four increase contractility.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.041 Q46') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-b2d2e1f00e', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'What are the features of stage 3 of anaesthesia?', '["Increased blood pressure, respiratory rate and heart rate", "Delirium and vocalisation", "Analgesia and amnesia", "Severe depression of the vasomotor centre in the central nervous system", "Loss of consciousness, stable blood pressure and relaxation of skeletal muscles"]'::jsonb, 'Loss of consciousness, stable blood pressure and relaxation of skeletal muscles', '[]'::jsonb, 'Stage III, surgical anaesthesia, begins with regular respiration and loss of the eyelash reflex; consciousness is lost, cardiovascular parameters are stable and skeletal muscles relax progressively, allowing surgery. Analgesia and amnesia characterise stage I, excitement with irregular breathing and raised blood pressure stage II, and medullary depression with circulatory collapse stage IV.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.042 Q50') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-c4c5239a7d', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which diuretic acts via enzyme inhibition?', '["Hydrochlorothiazide", "Mannitol", "Acetazolamide", "Amiloride", "Spironolactone"]'::jsonb, 'Acetazolamide', '[]'::jsonb, 'Acetazolamide inhibits carbonic anhydrase in the proximal tubule brush border and cells, blocking bicarbonate reabsorption and producing a bicarbonate diuresis with mild metabolic acidosis. The other diuretics act on transporters (hydrochlorothiazide on the Na+/Cl- cotransporter), channels (amiloride on ENaC), receptors (spironolactone) or osmotically (mannitol).', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.044') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-72033dc0a3', 'pharm-antidepressants-and-lithium', 'mcq', 'All of the following are adverse effects of amitriptyline EXCEPT:', '["Blurred vision", "Urine retention", "Dry mouth", "Constipation", "Hypertension"]'::jsonb, 'Hypertension', '[]'::jsonb, 'Amitriptyline blocks α1 adrenoceptors, causing postural hypotension with reflex tachycardia, rather than hypertension. Its muscarinic blockade causes blurred vision, dry mouth, constipation and urinary retention, and its H1 blockade causes sedation and weight gain. In overdose, sodium channel blockade causes QRS widening and arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.044 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-14116799f4', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which of the following has no action on the renin-angiotensin-aldosterone axis?', '["Remikiren", "Valsartan", "Diltiazem", "Perindopril", "Propranolol"]'::jsonb, 'Diltiazem', '[]'::jsonb, 'Diltiazem is a non-dihydropyridine calcium channel blocker that relaxes arterioles and slows the heart without acting on the RAAS. Remikiren directly inhibits renin, perindopril inhibits ACE, valsartan blocks AT1 receptors, and propranolol reduces renin release by blocking β1 receptors on juxtaglomerular cells.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.045') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-b6ab9e1e0f', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'The following are centrally acting skeletal muscle relaxants EXCEPT:', '["Baclofen", "Diazepam", "Dantrolene", "Tizanidine", "Chlorzoxazone"]'::jsonb, 'Dantrolene', '[]'::jsonb, 'Dantrolene acts directly on skeletal muscle, blocking ryanodine receptors and calcium release from the sarcoplasmic reticulum; it treats malignant hyperthermia and spasticity. Baclofen (GABA-B agonist), diazepam (GABA-A modulator), tizanidine (α2 agonist) and chlorzoxazone act in the spinal cord or brain to reduce muscle tone.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.045 Q30') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-6b7bd90675', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which statement about inhaled general anaesthetics is correct?', '["Nitrous oxide must be administered with oxygen", "Halothane is nephrotoxic", "They cause hypertension", "They have a wide therapeutic index", "They are mainly excreted via the kidneys"]'::jsonb, 'Nitrous oxide must be administered with oxygen', '[]'::jsonb, 'Nitrous oxide is given with at least 30% oxygen to avoid hypoxia. At the end of anaesthesia, its rapid outflow into the alveoli dilutes oxygen (diffusion hypoxia), so 100% oxygen is given for several minutes. Inhaled anaesthetics are mainly eliminated by the lungs, lower blood pressure and have a narrow therapeutic index; methoxyflurane, not halothane, was nephrotoxic.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.046') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-e0219eb903', 'pharm-antidepressants-and-lithium', 'mcq', 'Which antidepressant acts by selectively inhibiting noradrenaline reuptake?', '["Citalopram", "Fluoxetine", "Maprotiline", "Amitriptyline", "Duloxetine"]'::jsonb, 'Maprotiline', '[]'::jsonb, 'Maprotiline, a tetracyclic, is a selective noradrenaline reuptake inhibitor, as are desipramine and reboxetine; it carries a higher seizure risk than other antidepressants. Citalopram and fluoxetine selectively block serotonin reuptake, while amitriptyline and duloxetine block reuptake of both serotonin and noradrenaline.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.047 Q38') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-cc288d5039', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which anxiolytic acts on serotonin receptors?', '["Diphenhydramine", "Zaleplon", "Secobarbital", "Buspirone", "Clonazepam"]'::jsonb, 'Buspirone', '[]'::jsonb, 'Buspirone is a partial agonist at 5-HT1A receptors, and possibly acts on D2 receptors too; it relieves generalised anxiety over 1 to 2 weeks without sedation or dependence. Diphenhydramine is an H1 antagonist, zaleplon and clonazepam act at the GABA-A benzodiazepine site, and secobarbital is a barbiturate.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.049. Changed stem from ''sedative hypnotic'' to ''anxiolytic'': buspirone is not a hypnotic.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-473eeab3b7', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which statement about digoxin is false?', '["It is given orally", "It causes cardiac arrhythmias", "Its dose must be reduced in severe renal disease", "It stimulates the Na+/K+ ATPase pump", "It is used in treatment of severe heart failure"]'::jsonb, 'It stimulates the Na+/K+ ATPase pump', '[]'::jsonb, 'Digoxin inhibits Na+/K+ ATPase; the rise in intracellular sodium reduces calcium extrusion by the Na+/Ca2+ exchanger, increasing intracellular calcium and contractility. It is taken orally, excreted by the kidneys so doses are reduced in renal impairment, and toxicity causes almost any arrhythmia. It improves symptoms in severe heart failure with reduced ejection fraction.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.050 Q18. Changed ''Contraindicated in severe renal disease'' to ''dose must be reduced'', which is accurate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-32ff895a4f', 'pharm-major-tranquilizer', 'mcq', 'Which antipsychotic agent is most associated with motor (extrapyramidal) adverse effects?', '["Clozapine", "Olanzapine", "Risperidone", "Quetiapine", "Chlorpromazine"]'::jsonb, 'Chlorpromazine', '[]'::jsonb, 'Typical antipsychotics such as chlorpromazine strongly block D2 receptors in the nigrostriatal pathway, causing dystonia, parkinsonism, akathisia and tardive dyskinesia. Among atypicals, risperidone causes dose-related extrapyramidal effects, while clozapine and quetiapine carry the lowest risk because of weak, rapidly dissociating D2 binding.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.051. Chlorpromazine is low-potency and causes fewer extrapyramidal effects than high-potency typicals; high-dose risperidone also causes them.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-e7f4f08439', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which of the following is a depolarising skeletal muscle relaxant?', '["Cisatracurium", "Pancuronium", "Suxamethonium", "Quinine", "d-Tubocurarine"]'::jsonb, 'Suxamethonium', '[]'::jsonb, 'Suxamethonium (succinylcholine) is the only depolarising neuromuscular blocker in clinical use. It acts as a nicotinic agonist at the end plate, causing fasciculations followed by flaccid paralysis as the membrane stays depolarised (phase I block). Cisatracurium, pancuronium and tubocurarine are competitive non-depolarising blockers.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.051 Q16') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-3b47566532', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following local anaesthetics is an ester?', '["Bupivacaine", "Tetracaine", "Lidocaine", "Prilocaine", "Mepivacaine"]'::jsonb, 'Tetracaine', '[]'::jsonb, 'Tetracaine (amethocaine) is an ester, hydrolysed by plasma cholinesterase; it is potent and used topically on the eye and skin and for spinal anaesthesia. Bupivacaine, lidocaine, prilocaine and mepivacaine are amides metabolised by the liver, recognisable by the ''i'' before ''-caine''.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.054') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-92b34aa151', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'All of the following are true of angiotensin-converting enzyme inhibitors EXCEPT:', '["They cause cough", "They cause hypokalaemia", "Some are prodrugs", "They include captopril", "They are contraindicated in pregnancy"]'::jsonb, 'They cause hypokalaemia', '[]'::jsonb, 'ACE inhibitors reduce aldosterone secretion, so they cause potassium retention and hyperkalaemia, especially with renal impairment, potassium supplements or potassium-sparing diuretics. They cause dry cough through bradykinin accumulation and are fetotoxic in the second and third trimesters. Captopril is active, but enalapril and ramipril are prodrugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.055 Q8. Changed ''Are prodrugs'' to ''Some are prodrugs'' since captopril and lisinopril are not.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-b1c7f5484c', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'The following drugs are used to relieve acute exacerbation of asthma EXCEPT:', '["Salbutamol", "Magnesium sulphate", "Aminophylline", "Nedocromil", "Ipratropium"]'::jsonb, 'Nedocromil', '[]'::jsonb, 'Nedocromil is a mast cell stabiliser that only prevents bronchoconstriction when taken before exposure; it has no bronchodilator effect in an acute attack. Acute severe asthma is treated with nebulised salbutamol and ipratropium, systemic corticosteroids, IV magnesium sulphate, and sometimes IV aminophylline.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (BDS CAT 2022) p.056. Replaced tiotropium (a long-acting maintenance LAMA, so arguably also not used acutely) with short-acting ipratropium.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-respiratory-pharmacolo-ffe6ee4e72', 'pharm-introduction-to-respiratory-pharmacology-drugs-used-in-asthma', 'mcq', 'Identify the true statement about inhaled drug delivery:', '["Pressurised metered-dose inhalers are easy to use", "When using spacer chambers, most of the drug is deposited in the oropharynx", "Dry powder inhalers require careful coordination of actuation and inhalation", "Nebulisers deliver much higher doses of drug than a pressurised metered-dose inhaler", "Theophylline can be given by inhalation"]'::jsonb, 'Nebulisers deliver much higher doses of drug than a pressurised metered-dose inhaler', '[]'::jsonb, 'A nebulised dose of salbutamol (2.5 to 5 mg) is many times the 100 to 200 micrograms from a metered-dose inhaler, though less of it reaches the airways. Metered-dose inhalers need coordinated actuation and inhalation, which many patients find hard; spacers reduce oropharyngeal deposition; dry powder inhalers are breath-activated; theophylline is given orally or IV.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.058 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-1e17707494', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which is not true of methylxanthines?', '["They are classified as relievers", "Enprofylline does not antagonise adenosine receptors", "Their only mechanism of action is inhibition of phosphodiesterase enzymes", "They have positive chronotropic and inotropic effects on the heart", "They can exacerbate peptic ulcer disease"]'::jsonb, 'Their only mechanism of action is inhibition of phosphodiesterase enzymes', '[]'::jsonb, 'Methylxanthines act by several mechanisms: non-selective phosphodiesterase inhibition, adenosine receptor antagonism and possibly histone deacetylase activation. Enprofylline is a potent bronchodilator with little adenosine antagonism, suggesting PDE inhibition is important. They stimulate the heart, increase gastric acid secretion and can aggravate peptic ulcers.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.059 Q5') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-5e2de389db', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'Which statement about corticosteroids used in asthma is false?', '["They inhibit production of inflammatory cytokines", "They inhibit eicosanoid synthesis", "They decrease vascular permeability", "They cause bronchodilation", "They inhibit accumulation of inflammatory cells in lung tissue"]'::jsonb, 'They cause bronchodilation', '[]'::jsonb, 'Corticosteroids do not relax airway smooth muscle directly. They change gene transcription to reduce cytokine production, induce annexin-1 and inhibit COX-2 (reducing eicosanoids), decrease vascular permeability and mucosal oedema, and reduce eosinophils and mast cells in the airways. They also increase β2 receptor expression, helping β2 agonists work.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.059 Q6') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antimuscarinic-agents-e9319cf333', 'pharm-antimuscarinic-agents', 'mcq', 'Which statement about ipratropium bromide is true?', '["It is a tertiary ammonium compound", "It has good systemic and oral absorption", "It has a faster onset of action than salbutamol", "It is an inhaled antiasthma drug", "It has a duration of action of 24 hours"]'::jsonb, 'It is an inhaled antiasthma drug', '[]'::jsonb, 'Ipratropium is a quaternary ammonium antimuscarinic, so it is poorly absorbed from the lungs and gut and does not cross the blood-brain barrier, giving few systemic effects. It is inhaled, acts more slowly than β2 agonists (peak about 30 to 60 minutes) and lasts 4 to 6 hours. Tiotropium is the once-daily agent.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.060 Q9. Changed option c from ''Has a fast onset of action'' to a comparison with salbutamol so that only one option is true.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-a05f02b81d', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'mcq', 'The seizure type in which a person appears to be daydreaming is:', '["Absence seizure", "Tonic-clonic seizure", "Grand mal seizure", "Myoclonic seizure", "Atonic seizure"]'::jsonb, 'Absence seizure', '[]'::jsonb, 'Absence (petit mal) seizures cause sudden, brief lapses of awareness lasting seconds, with staring and sometimes eyelid fluttering, and no post-ictal confusion; children may seem to be daydreaming. The EEG shows 3 Hz spike-and-wave discharges. Ethosuximide and valproate are first-line, and carbamazepine and phenytoin can worsen them.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.062 Q14. Replaced options ''Petit mal seizure'' (a synonym of absence, so a second correct answer) and ''None of the above'' with myoclonic and atonic seizures.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anticonvulsant-drugs-c-c15920a6b1', 'pharm-introduction-to-anticonvulsant-drugs-classification-of-seizures', 'mcq', 'Antiseizure drugs act via all the following mechanisms EXCEPT:', '["Inhibition of T-type Ca2+ channels in thalamic neurons", "Modulation of release of synaptic vesicles", "Reduction of electrical excitability of neuronal membranes", "Attenuating the effects of GABA", "Decreasing the influx of Ca2+ during depolarisation"]'::jsonb, 'Attenuating the effects of GABA', '[]'::jsonb, 'Antiseizure drugs enhance, rather than attenuate, GABA-mediated inhibition: benzodiazepines and barbiturates potentiate GABA-A receptors, tiagabine blocks GABA reuptake and vigabatrin blocks its breakdown. Other mechanisms include sodium channel blockade, T-type calcium channel blockade (ethosuximide), α2δ binding, and SV2A modulation of vesicle release (levetiracetam).', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.062 Q15') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-875b5c25ec', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Hepatic microsomal metabolism of phenytoin is inhibited by all the following EXCEPT:', '["Chloramphenicol", "Phenobarbitone", "Cimetidine", "Sulfonamides", "Isoniazid"]'::jsonb, 'Phenobarbitone', '[]'::jsonb, 'Phenobarbitone induces cytochrome P450 enzymes and generally speeds phenytoin metabolism, although at high levels it can compete for the same enzymes, so the net effect varies. Chloramphenicol, cimetidine, sulfonamides and isoniazid inhibit phenytoin metabolism. Because phenytoin follows saturable kinetics, even small inhibition can cause marked toxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.062 Q16. Dropped dicoumarol to keep five options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-7c1907709e', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which of the following is not an adverse effect of phenytoin?', '["Hyperplasia of the gums", "Gastrointestinal upset", "CNS stimulation", "Megaloblastic anaemia", "Behavioural changes"]'::jsonb, 'CNS stimulation', '[]'::jsonb, 'Phenytoin''s dose-related CNS effects are depressant: nystagmus, ataxia, diplopia, sedation and, at high levels, confusion and coma. It does not stimulate the CNS. Other adverse effects are gingival hyperplasia, hirsutism, nausea and GI upset, folate-related megaloblastic anaemia, osteomalacia, lymphadenopathy and behavioural changes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.063 Q17') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-844dbdad38', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'What is the main difference between barbiturates used as antiseizure drugs and other barbiturates?', '["All antiseizure barbiturates are methylated", "Antiseizure barbiturates inhibit seizures at doses that produce little sedation", "Other barbiturates are not sedative", "Antiseizure barbiturates do not act on GABA-A receptors", "Antiseizure barbiturates are given only intravenously"]'::jsonb, 'Antiseizure barbiturates inhibit seizures at doses that produce little sedation', '[]'::jsonb, 'Phenobarbital and mephobarbital suppress seizures at doses below those causing marked sedation, a selective anticonvulsant action, probably related to their phenyl substituent. Other barbiturates, such as pentobarbital or thiopental, stop seizures only at anaesthetic, sedating doses. All barbiturates act partly by enhancing GABA-A receptor function.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.063 Q18. The paper''s options were confusingly worded; options b to e were rewritten.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-8d3a10150c', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Phenobarbital is believed to act through all the following mechanisms EXCEPT:', '["Acting on GABA receptors to prolong the opening of chloride channels", "Enhancement of central inhibitory processes", "Enhancement of glutamate-induced transmission", "Selective suppression of abnormal neurons and inhibition of spread of firing from these foci", "Blockade of L-type and N-type Ca2+ channels at high concentrations"]'::jsonb, 'Enhancement of glutamate-induced transmission', '[]'::jsonb, 'Phenobarbital reduces, not enhances, excitatory glutamate transmission, partly by blocking AMPA receptors. It potentiates GABA-A receptors by prolonging the opening of chloride channels (unlike benzodiazepines, which increase opening frequency), suppresses abnormal neurons and limits seizure spread, and at high concentrations blocks calcium channels.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.064 Q19') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-8c620e72d9', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'All of the following are true about phenobarbital EXCEPT:', '["Its elimination can be enhanced by acidification of the urine", "It is an inducer of uridine diphosphate glucuronosyltransferase", "It produces sedation, to which tolerance develops", "It is associated with haemorrhagic disease of the newborn", "It has additive CNS depressant effects when co-administered with antihistamines"]'::jsonb, 'Its elimination can be enhanced by acidification of the urine', '[]'::jsonb, 'Phenobarbital is a weak acid (pKa about 7.2), so alkalinising the urine with sodium bicarbonate ionises it in the tubule, reducing reabsorption and increasing excretion; this is used in overdose. It induces CYP enzymes and glucuronyl transferase, causes sedation to which tolerance develops, and taken in pregnancy can cause neonatal vitamin K deficiency bleeding.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.064 Q20. Corrected ''uridine triphosphate glucoronosyl transferase'' to uridine diphosphate glucuronosyltransferase.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-34a0b85586', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Choose the false statement:', '["Primidone is available only as an oral preparation", "Primidone and its active metabolites, phenobarbital and phenylethylmalonamide (PEMA), are active anticonvulsants", "Primidone is converted to phenobarbital, but its own mechanism of action may be more like that of phenytoin", "Phenytoin increases the metabolism of primidone", "Primidone is effective in absence seizures"]'::jsonb, 'Primidone is effective in absence seizures', '[]'::jsonb, 'Primidone, like phenobarbital, is used for focal and generalised tonic-clonic seizures and essential tremor, but it is ineffective against absence seizures. It is given orally, and both the parent drug and its metabolites phenobarbital and PEMA have anticonvulsant activity. Enzyme inducers such as phenytoin increase its conversion to phenobarbital.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.064 Q21') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-fd1fdd346c', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which statement about iminostilbenes is false?', '["They are first-line agents in focal seizures", "They include carbamazepine and oxcarbazepine", "Carbamazepine is only given orally, with slow and erratic absorption", "Carbamazepine reduces the propagation of abnormal impulses in the brain by blocking Ca2+ channels", "Carbamazepine can be used in the treatment of trigeminal neuralgia"]'::jsonb, 'Carbamazepine reduces the propagation of abnormal impulses in the brain by blocking Ca2+ channels', '[]'::jsonb, 'Carbamazepine and oxcarbazepine block voltage-gated sodium channels in their inactivated state, preventing high-frequency repetitive firing; they do not act mainly on calcium channels. Carbamazepine is given orally with slow, variable absorption, is first-line for focal seizures, and is the drug of choice for trigeminal neuralgia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.065 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-5197bac44a', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'The antiseizure drug that inhibits GABA transaminase is:', '["Valproate", "Ethosuximide", "Levetiracetam", "Phenytoin", "Gabapentin"]'::jsonb, 'Valproate', '[]'::jsonb, 'Valproate raises brain GABA partly by inhibiting GABA transaminase and succinic semialdehyde dehydrogenase, which break GABA down, and possibly by stimulating glutamic acid decarboxylase; it also blocks sodium and T-type calcium channels. Vigabatrin, not listed here, is the irreversible GABA transaminase inhibitor designed for that purpose.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.065 Q24. Valproate''s GABA transaminase inhibition is weak; vigabatrin is the classic answer but is not among the options.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-7d376570c1', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'The drug that modifies the synaptic release of glutamate and GABA through an action on the SV2A synaptic vesicle protein is:', '["Levetiracetam", "Phenytoin", "Carbamazepine", "Tiagabine", "Gabapentin"]'::jsonb, 'Levetiracetam', '[]'::jsonb, 'Levetiracetam, and its analogue brivaracetam, bind the synaptic vesicle glycoprotein SV2A and modulate neurotransmitter release; the exact mechanism is unclear. It is a broad-spectrum antiseizure drug with near-complete oral absorption, renal excretion and few interactions. Its main adverse effects are drowsiness and mood or behavioural changes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.066 Q25') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-800196358b', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which drug is suitable for use in neonatal seizures?', '["Valproate", "Ethosuximide", "Levetiracetam", "Phenobarbital", "Gabapentin"]'::jsonb, 'Phenobarbital', '[]'::jsonb, 'Phenobarbital has long been the first-line drug for neonatal seizures; it is given IV and its long half-life in neonates allows once-daily maintenance. Levetiracetam is increasingly used as a second-line or alternative agent. Valproate is avoided in infants because of the risk of fatal hepatotoxicity.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.066 Q26. Levetiracetam is now also used for neonatal seizures in many units.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-a148b504b3', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which drug reduces glutamate release by binding to the α2δ subunit of voltage-gated calcium channels?', '["Levetiracetam", "Phenytoin", "Carbamazepine", "Tiagabine", "Gabapentin"]'::jsonb, 'Gabapentin', '[]'::jsonb, 'Gabapentin and pregabalin bind the α2δ subunit of presynaptic voltage-gated calcium channels, reducing calcium entry and the release of glutamate, noradrenaline and substance P. Although designed as GABA analogues, they do not act on GABA receptors. They are used for focal seizures, neuropathic pain and, for pregabalin, generalised anxiety disorder.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.066 Q27') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-dcac01e848', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which hydantoin is a water-soluble prodrug for intravenous infusion in convulsive status epilepticus?', '["Phenytoin", "Mephenytoin", "Fosphenytoin", "Phenacemide", "Ethotoin"]'::jsonb, 'Fosphenytoin', '[]'::jsonb, 'Fosphenytoin is a phosphate ester prodrug that is freely water-soluble and rapidly converted to phenytoin by plasma phosphatases. It can be infused faster and given IM, with less phlebitis, tissue injury (purple glove syndrome) and hypotension than IV phenytoin, which needs a propylene glycol and alkaline vehicle.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.066 Q28. Added ''water-soluble prodrug'' to the stem because plain phenytoin is also given IV in status epilepticus.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-4b6ff9e7b5', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Ethosuximide is a drug of choice in:', '["Generalised tonic-clonic (grand mal) seizures", "Absence (petit mal) seizures", "Tonic seizures", "Atonic seizures", "Clonic and myoclonic seizures"]'::jsonb, 'Absence (petit mal) seizures', '[]'::jsonb, 'Ethosuximide blocks low-threshold T-type calcium currents in thalamic neurons, which generate the rhythmic discharges of absence seizures. It is first-line for childhood absence epilepsy without other seizure types; valproate is preferred when tonic-clonic seizures coexist because ethosuximide does not protect against them.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.067 Q30') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-01b9e650bd', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'The following are proposed mechanisms of valproic acid EXCEPT:', '["Blockade of voltage-gated Na+ channels", "Blockade of NMDA receptor excitation", "Stimulation of glutamic acid decarboxylase", "Stimulation of GABA transaminase", "Blockade of T-type calcium channels"]'::jsonb, 'Stimulation of GABA transaminase', '[]'::jsonb, 'Valproate inhibits, rather than stimulates, GABA transaminase, raising GABA levels. Its other proposed actions are prolonging sodium channel inactivation, blocking T-type calcium currents (explaining its effect in absence seizures), attenuating NMDA-mediated excitation and possibly stimulating glutamic acid decarboxylase, the enzyme that makes GABA.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.068 Q31. Replaced option e (''Inhibition of GABA transporter-1'', which is tiagabine''s action and also not valproate''s) with T-type calcium channel blockade.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-a0c6bef873', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'Identify the true statement:', '["Paramethadione is the active metabolite of the oxazolidinediones", "Dimethadione reduces the T-type calcium current, inhibiting pacemaker action of thalamic neurons", "Gabapentin and pregabalin act directly on GABA receptors", "Gabapentin does not enter the brain", "Pregabalin consists of a GABA molecule covalently bonded to a lipophilic cyclohexane ring"]'::jsonb, 'Dimethadione reduces the T-type calcium current, inhibiting pacemaker action of thalamic neurons', '[]'::jsonb, 'Dimethadione, the active metabolite of trimethadione, reduces T-type calcium currents in thalamic neurons and so suppresses absence seizures, like ethosuximide. Gabapentin, not pregabalin, is GABA bonded to a cyclohexane ring; it crosses into the brain via the L-amino acid transporter, and both drugs act on α2δ calcium channel subunits rather than GABA receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.068 Q33') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-ac788fdb72', 'pharm-sedative-hypnotic-drugs', 'mcq', 'All the following statements are true EXCEPT:', '["Clonidine is an α2 receptor agonist with anxiolytic effects", "Benzodiazepines used to treat anxiety often have long half-lives", "β-antagonists relieve anxiety by blocking central sympathetic responses", "Buspirone is a 5-HT1A receptor partial agonist", "Atypical antipsychotics such as olanzapine have more adverse effects than other anxiolytic drugs"]'::jsonb, 'β-antagonists relieve anxiety by blocking central sympathetic responses', '[]'::jsonb, 'β-blockers such as propranolol reduce the peripheral autonomic features of anxiety, such as tremor, palpitations and sweating, in performance anxiety; they do little for the psychological symptoms and do not act by central sympathetic blockade. Clonidine reduces central noradrenergic activity, and buspirone is a 5-HT1A partial agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.070 Q39') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-80aacdfbdd', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'The anticonvulsant medication associated with progressive and permanent vision loss is:', '["Nitrazepam", "Levetiracetam", "Tiagabine", "Vigabatrin", "Topiramate"]'::jsonb, 'Vigabatrin', '[]'::jsonb, 'Vigabatrin irreversibly inhibits GABA transaminase. It causes concentric visual field constriction in about a third of patients, which is usually permanent, so it is reserved for infantile spasms (especially with tuberous sclerosis) and refractory focal seizures, with regular field testing. Topiramate can cause acute angle-closure glaucoma, which is reversible.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.069 Q35') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-25ac2ac197', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'The main mechanism of action of tiagabine is:', '["Inhibition of GABA transporter-1", "Modification of synaptic release of GABA and glutamate", "Blockade of voltage-gated sodium channels", "Blockade of T-type calcium channels", "Prolongation of opening of chloride channels"]'::jsonb, 'Inhibition of GABA transporter-1', '[]'::jsonb, 'Tiagabine, a nipecotic acid derivative, inhibits GAT-1, the main GABA reuptake transporter in neurons and glia, so GABA lingers in the synapse and inhibition is prolonged. It is an add-on drug for focal seizures. SV2A modulation describes levetiracetam, and prolonged chloride channel opening describes barbiturates.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.069 Q36') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-46f64af051', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Choose the correct statement regarding sedative-hypnotics:', '["A sedative drug reduces anxiety and exerts a calming effect", "An effective sedative drug markedly depresses motor and mental function", "Sedative doses are the standard treatment for insomnia", "Hypnotics and sedatives attain the same degree of CNS depression", "Sedative drugs cannot induce a state of hypnosis"]'::jsonb, 'A sedative drug reduces anxiety and exerts a calming effect', '[]'::jsonb, 'A sedative (anxiolytic) reduces anxiety and calms with minimal impairment of motor or mental function; a hypnotic produces drowsiness and promotes sleep. Most sedative-hypnotics produce a dose-dependent continuum: higher doses of the same drug cause hypnosis, then anaesthesia and coma. Hypnotics therefore depress the CNS more than sedatives.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.070 Q37. Options were reworded for clarity; the original statements were ambiguous.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-6e31f66cc8', 'pharm-antidepressants-and-lithium', 'mcq', 'All the following are true about antidepressants EXCEPT:', '["They are effective in the management of phobias and post-traumatic stress disorder", "Fluoxetine and sertraline are examples", "Some act via inhibition of serotonin and noradrenaline reuptake", "Tricyclic antidepressants and monoamine oxidase inhibitors are the most preferred agents", "They are advantageous in management of anxiety associated with depression"]'::jsonb, 'Tricyclic antidepressants and monoamine oxidase inhibitors are the most preferred agents', '[]'::jsonb, 'SSRIs and SNRIs are now first-line for depression and for anxiety disorders including panic disorder, phobias and PTSD, because they are better tolerated and much safer in overdose. Tricyclics cause anticholinergic and cardiotoxic effects, and MAO inhibitors need dietary tyramine restriction and have dangerous interactions, so both are reserved for refractory cases.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.070 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-13e555b958', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which statement about sedative-hypnotics is true?', '["Most are administered parenterally", "Phenobarbital has low lipid solubility and penetrates the brain slowly", "Thiopental and triazolam have a slow onset of CNS effects", "N-dealkylation of benzodiazepines is a phase 2 reaction", "Most metabolites of barbiturates are pharmacologically active"]'::jsonb, 'Phenobarbital has low lipid solubility and penetrates the brain slowly', '[]'::jsonb, 'Phenobarbital is among the least lipid-soluble barbiturates, so it enters the brain slowly and is useless for rapid induction, unlike highly lipid-soluble thiopental and triazolam, which act quickly. Most sedative-hypnotics are taken orally. N-dealkylation is an oxidative phase 1 reaction, and barbiturate metabolites are mostly inactive.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.072 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-563d46fbb7', 'pharm-sedative-hypnotic-drugs', 'mcq', 'All the following benzodiazepines are converted to active metabolites EXCEPT:', '["Clorazepate", "Diazepam", "Flurazepam", "Lorazepam", "Chlordiazepoxide"]'::jsonb, 'Lorazepam', '[]'::jsonb, 'Lorazepam, like oxazepam and temazepam, is directly glucuronidated to inactive products. Its metabolism is therefore little affected by age or liver disease, which makes it preferred in the elderly and in hepatic impairment. Clorazepate, diazepam, chlordiazepoxide and flurazepam are converted to long-acting active metabolites such as desmethyldiazepam.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.072 Q45. Replaced ''Demoxepam'' (itself a metabolite) with chlordiazepoxide.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-329b81f9a0', 'pharm-antidepressants-and-lithium', 'mcq', 'Regarding antidepressants, which statement is true?', '["Tricyclic antidepressants are more efficacious than heterocyclics", "Phenelzine and isocarboxazid inhibit serotonin reuptake", "The antidepressant effect is achieved rapidly after starting treatment", "Some antidepressants also block 5-HT2, α1-adrenergic, H1 and muscarinic receptors", "Increased concentration of monoamines in the synaptic cleft causes depression"]'::jsonb, 'Some antidepressants also block 5-HT2, α1-adrenergic, H1 and muscarinic receptors', '[]'::jsonb, 'Many antidepressants, especially tricyclics, block several receptors besides inhibiting reuptake: muscarinic (dry mouth), H1 (sedation), α1 (postural hypotension) and 5-HT2. All antidepressant classes have similar efficacy, the effect takes 2 to 4 weeks, phenelzine and isocarboxazid are MAO inhibitors, and the monoamine hypothesis links depression to reduced, not increased, monoamines.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.073 Q47') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-4920356277', 'pharm-antidepressants-and-lithium', 'mcq', 'Tricyclic antidepressants can be used in the management of all the following EXCEPT:', '["Severe endogenous depression", "Nocturnal enuresis", "Migraine prophylaxis", "Adjunct in pain management", "Motion sickness"]'::jsonb, 'Motion sickness', '[]'::jsonb, 'Motion sickness is treated with antimuscarinics such as hyoscine or antihistamines such as cinnarizine and promethazine, not tricyclics. Tricyclics are used for depression, nocturnal enuresis (imipramine), migraine prophylaxis (amitriptyline), and neuropathic and chronic pain at low doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.073 Q48') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-efc419cb71', 'pharm-antidepressants-and-lithium', 'mcq', 'All the following are true statements EXCEPT:', '["Nefazodone is a potent inhibitor of the CYP3A4 isozyme", "Venlafaxine is a potent inhibitor of noradrenaline transport and a weak inhibitor of serotonin reuptake", "Maprotiline is a selective noradrenaline reuptake inhibitor with fewer sedative and muscarinic actions", "Mirtazapine is a potent antihistaminic drug with marked sedative effects", "Tricyclic antidepressants can cause orthostatic hypotension"]'::jsonb, 'Venlafaxine is a potent inhibitor of noradrenaline transport and a weak inhibitor of serotonin reuptake', '[]'::jsonb, 'Venlafaxine is the reverse: it inhibits serotonin reuptake strongly at low doses and noradrenaline reuptake mainly at higher doses, which is why higher doses raise blood pressure. Nefazodone inhibits CYP3A4, maprotiline is a selective noradrenaline reuptake inhibitor, mirtazapine is strongly H1-blocking and sedating, and tricyclics cause postural hypotension via α1 blockade.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.074 Q49') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-71eea53884', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which is the most effective drug treatment in parkinsonism?', '["Bromocriptine", "Selegiline", "Levodopa + carbidopa + entacapone", "Biperiden", "Apomorphine"]'::jsonb, 'Levodopa + carbidopa + entacapone', '[]'::jsonb, 'Levodopa remains the most effective symptomatic treatment for Parkinson''s disease. Carbidopa blocks its peripheral decarboxylation, and entacapone blocks peripheral COMT, so more levodopa reaches the brain for longer, smoothing wearing-off. Dopamine agonists, MAO-B inhibitors such as selegiline and antimuscarinics such as biperiden are less effective.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.074 Q50') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-7b92bea94f', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'In parkinsonian patients, levodopa exerts the following effects EXCEPT:', '["It reduces skeletal muscle contractility", "It decreases muscle tone (rigidity)", "It increases locomotor activity", "It inhibits muscle tremor", "It causes dyskinesia as an adverse effect"]'::jsonb, 'It reduces skeletal muscle contractility', '[]'::jsonb, 'Levodopa restores striatal dopamine, relieving bradykinesia, rigidity and, to a lesser extent, tremor; it has no direct effect on skeletal muscle contractility. Long-term therapy commonly leads to peak-dose dyskinesias (involuntary choreiform movements) and on-off fluctuations as the disease progresses.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.074 Q52') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-f13cd1a145', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which drug abolishes the therapeutic effect of levodopa in parkinsonism, but not that of the levodopa-carbidopa combination?', '["Metoclopramide", "Pyridoxine", "Chlorpromazine", "Isoniazid", "Selegiline"]'::jsonb, 'Pyridoxine', '[]'::jsonb, 'Pyridoxine (vitamin B6) is the cofactor for dopa decarboxylase, so supplements increase peripheral conversion of levodopa to dopamine, leaving less to enter the brain. Carbidopa blocks peripheral decarboxylase, so pyridoxine no longer matters. Metoclopramide and chlorpromazine block dopamine receptors and antagonise both levodopa and the combination.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.074 Q53') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-d0e1e568f1', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which antiparkinsonian drug acts by inhibiting the degradation of dopamine in the brain?', '["Carbidopa", "Amantadine", "Selegiline", "Bromocriptine", "Entacapone"]'::jsonb, 'Selegiline', '[]'::jsonb, 'Selegiline and rasagiline selectively and irreversibly inhibit monoamine oxidase B, the main enzyme degrading dopamine in the striatum, so they prolong the action of endogenous and levodopa-derived dopamine. Carbidopa and entacapone act peripherally on levodopa metabolism, bromocriptine is a D2 agonist, and amantadine increases dopamine release and blocks NMDA receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.076 Q55') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-ea841355e6', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'The primary action by which entacapone and tolcapone enhance the therapeutic effect of levodopa-carbidopa in parkinsonism is:', '["Inhibition of levodopa methylation in peripheral tissues", "Inhibition of dopamine methylation in the brain", "Inhibition of oxidative deamination of dopamine in the brain", "Facilitation of active transport of levodopa across brain capillaries", "Inhibition of dopa decarboxylase in the gut"]'::jsonb, 'Inhibition of levodopa methylation in peripheral tissues', '[]'::jsonb, 'Entacapone and tolcapone inhibit catechol-O-methyltransferase (COMT). With dopa decarboxylase already blocked by carbidopa, COMT becomes the main peripheral route of levodopa breakdown, to 3-O-methyldopa. Blocking it raises and prolongs plasma levodopa, increasing brain delivery. Entacapone acts only peripherally; tolcapone also enters the brain.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.076 Q56. Replaced ''All of the above'' with a decarboxylase distractor and changed ''in the liver'' to ''peripheral tissues''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-dc7650f560', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'The following are true about entacapone EXCEPT:', '["It acts by inhibiting degradation of dopamine in the brain", "It prolongs the therapeutic effect of levodopa-carbidopa in parkinsonism", "It can accentuate levodopa-induced dyskinesias", "It can cause diarrhoea as a side effect", "It does not cause hepatotoxicity"]'::jsonb, 'It acts by inhibiting degradation of dopamine in the brain', '[]'::jsonb, 'Entacapone does not cross the blood-brain barrier; it inhibits COMT in peripheral tissues, reducing levodopa breakdown before it reaches the brain. This prolongs levodopa''s effect but also increases dopaminergic adverse effects such as dyskinesia. It can cause diarrhoea and orange urine, and unlike tolcapone it is not associated with fulminant hepatotoxicity.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.076 Q57') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-e81b1a4792', 'pharm-antidepressants-and-lithium', 'mcq', 'The most commonly used antidepressants in clinical practice are:', '["Selective serotonin reuptake inhibitors", "5-HT2 antagonists", "Serotonin-noradrenaline reuptake inhibitors", "Tetracyclic and unicyclic antidepressants", "Monoamine oxidase inhibitors"]'::jsonb, 'Selective serotonin reuptake inhibitors', '[]'::jsonb, 'SSRIs such as fluoxetine, sertraline and escitalopram are the most prescribed antidepressants because they are as effective as older drugs, better tolerated, and much safer in overdose. They are first-line for depression and most anxiety disorders. SNRIs are a common second choice, while MAO inhibitors are rarely used because of interactions and dietary restrictions.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.076 Q58') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-c4c8d37d9b', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement regarding the use of lithium salts in the management of mood disorders is false?', '["Diuretic therapy can precipitate toxic levels of lithium", "It is safe in pregnancy and breastfeeding", "It may act by altering the cellular concentration of the second messenger inositol triphosphate", "It has a low therapeutic index", "Long-term effects include non-toxic goitre and hypothyroidism"]'::jsonb, 'It is safe in pregnancy and breastfeeding', '[]'::jsonb, 'Lithium is teratogenic (associated with Ebstein''s anomaly, though the risk is lower than once thought) and passes into breast milk, so it needs specialist review in pregnancy and is usually avoided when breastfeeding. Thiazides raise lithium levels by increasing proximal reabsorption. It inhibits inositol monophosphatase, depleting inositol and IP3 signalling, and commonly causes goitre and hypothyroidism.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.076 Q59. Option e originally said ''hyperthyroidism'', a second false statement; corrected to hypothyroidism.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-226b7363c2', 'pharm-major-tranquilizer', 'mcq', 'All the following are true statements about neuroleptics EXCEPT:', '["First-generation neuroleptics are competitive inhibitors of dopamine receptors", "Atypical neuroleptics have more extrapyramidal side effects", "Neuroleptics are not curative medications", "Clinical efficacy correlates closely with their ability to block D2 receptors in the mesolimbic system", "They also block the effects of drugs such as apomorphine and bromocriptine"]'::jsonb, 'Atypical neuroleptics have more extrapyramidal side effects', '[]'::jsonb, 'Atypical antipsychotics have fewer extrapyramidal effects, thanks to 5-HT2A antagonism and lower or faster-dissociating D2 binding; their main problems are weight gain and metabolic effects. Antipsychotics block D2 receptors competitively, so they oppose dopamine agonists, and their potency correlates with mesolimbic D2 blockade. They control symptoms but do not cure psychosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.077 Q60') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-cbc7b050ba', 'pharm-major-tranquilizer', 'mcq', 'All the following are high-potency typical neuroleptics EXCEPT:', '["Haloperidol", "Pimozide", "Thiothixene", "Chlorpromazine", "Fluphenazine"]'::jsonb, 'Chlorpromazine', '[]'::jsonb, 'Chlorpromazine is a low-potency phenothiazine needing doses in the hundreds of milligrams; it causes more sedation, anticholinergic effects and postural hypotension but fewer extrapyramidal effects. Haloperidol, pimozide, thiothixene and fluphenazine are effective at a few milligrams and cause more extrapyramidal reactions.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.078 Q61') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-dcac2f0bbd', 'pharm-major-tranquilizer', 'mcq', 'Which statement regarding extrapyramidal effects caused by neuroleptic agents is false?', '["They are caused by a relative excess of cholinergic influence in the CNS", "They are time- and dose-dependent", "Atypical antipsychotics have fewer extrapyramidal effects owing to 5-HT2A blockade", "Thioridazine has excessive extrapyramidal effects", "Acute dystonia and parkinsonism can be relieved by benztropine"]'::jsonb, 'Thioridazine has excessive extrapyramidal effects', '[]'::jsonb, 'Thioridazine is a low-potency phenothiazine with strong intrinsic antimuscarinic activity, so it causes few extrapyramidal effects; its main dangers are QT prolongation and pigmentary retinopathy. Extrapyramidal effects arise when D2 blockade in the striatum leaves cholinergic activity relatively unopposed, which is why antimuscarinics such as benztropine relieve them.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.078 Q62. Clarified option e: benztropine relieves acute dystonia and parkinsonism but not tardive dyskinesia.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-96510b1456', 'pharm-major-tranquilizer', 'mcq', 'Which of the following antipsychotic drugs is typical?', '["Clozapine", "Quetiapine", "Olanzapine", "Haloperidol", "Risperidone"]'::jsonb, 'Haloperidol', '[]'::jsonb, 'Haloperidol is a butyrophenone typical (first-generation) antipsychotic with high D2 affinity and frequent extrapyramidal effects; it is also used for acute agitation and delirium. Clozapine, quetiapine, olanzapine and risperidone are atypical (second-generation) agents with prominent 5-HT2A antagonism.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.078 Q63') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-d2ff3595ba', 'pharm-major-tranquilizer', 'mcq', 'Acute extrapyramidal reactions to antipsychotics can be treated by:', '["Levodopa", "Benztropine mesylate", "Bromocriptine", "Dopamine", "All of the above"]'::jsonb, 'Benztropine mesylate', '[]'::jsonb, 'Acute dystonia and drug-induced parkinsonism respond to central antimuscarinics such as benztropine, procyclidine or biperiden, which restore the dopamine-acetylcholine balance in the striatum. Dopamine agonists and levodopa are avoided because they would oppose the antipsychotic effect and worsen psychosis, and dopamine itself does not cross the blood-brain barrier.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.078 Q64') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-71f9fc6914', 'pharm-antidepressants-and-lithium', 'mcq', 'Which of the following may cause nephrogenic diabetes insipidus?', '["Fluoxetine", "Haloperidol", "Lithium", "Phenytoin", "Diazepam"]'::jsonb, 'Lithium', '[]'::jsonb, 'Lithium accumulates in collecting duct principal cells via epithelial sodium channels and impairs the response to ADH by down-regulating aquaporin-2. This causes polyuria and polydipsia in a large minority of long-term users. Amiloride, which blocks lithium entry, and thiazides can reduce the polyuria. Phenytoin inhibits ADH release, causing central rather than nephrogenic DI.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Tutorial MCQs, Season 3) p.082 Q73') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-gabapentin-vigabatrin-and-others-ff3f8610aa', 'pharm-gabapentin-vigabatrin-and-others', 'mcq', 'Which antiseizure agent is incorrectly matched with its chemical class?', '["Lamotrigine: phenyltriazine", "Lacosamide: sulfonamide derivative", "Rufinamide: triazole derivative", "Trimethadione: oxazolidinedione", "Primidone: deoxybarbiturate"]'::jsonb, 'Lacosamide: sulfonamide derivative', '[]'::jsonb, 'Lacosamide is a functionalised amino acid that enhances slow inactivation of sodium channels; the sulfonamide antiseizure drug is zonisamide. The other pairs are correct: lamotrigine is a phenyltriazine, rufinamide a triazole, trimethadione an oxazolidinedione, and primidone a 2-deoxybarbiturate metabolised to phenobarbital.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.084 Q3. Changed primidone''s class from ''Barbiturate'' to the more precise ''deoxybarbiturate''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-24f95bf028', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Digoxin at therapeutic doses causes all the following effects on the heart EXCEPT:', '["It increases the QT interval on the ECG", "It reduces the refractory period of atrial muscle", "It increases the refractory period at the atrioventricular node", "It reduces the rate at the sinoatrial node", "It increases the PR interval on the ECG"]'::jsonb, 'It increases the QT interval on the ECG', '[]'::jsonb, 'Digoxin shortens the QT interval by shortening ventricular action potentials, and causes the characteristic scooped (reverse-tick) ST depression and T-wave flattening. Its vagal effects slow the sinus rate and lengthen AV nodal refractoriness, prolonging the PR interval, while atrial refractory period shortens, which is why digoxin can convert flutter to fibrillation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.084 Q4') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-2664164b1a', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Nordiazepam (desmethyldiazepam) is an active metabolite of all the following benzodiazepines EXCEPT:', '["Flurazepam", "Clorazepate", "Diazepam", "Prazepam", "Chlordiazepoxide"]'::jsonb, 'Flurazepam', '[]'::jsonb, 'Flurazepam is converted to its own active metabolites, hydroxyethylflurazepam and N-desalkylflurazepam, the latter with a half-life of 2 to 4 days. Diazepam, chlordiazepoxide, clorazepate and prazepam all form desmethyldiazepam (nordiazepam), a long-acting active metabolite that contributes to accumulation in the elderly.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.084 Q5') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-67aa1ed76e', 'pharm-intravenous-fluids', 'mcq', 'Which intravenous fluid is recommended for rehydration of a patient with severe vomiting?', '["Ringer''s lactate solution", "Darrow''s solution", "Normal saline (with potassium supplementation)", "5% dextrose solution", "Plasma-Lyte"]'::jsonb, 'Normal saline (with potassium supplementation)', '[]'::jsonb, 'Prolonged vomiting loses gastric hydrochloric acid, potassium and water, causing hypochloraemic hypokalaemic metabolic alkalosis. Normal saline replaces volume and chloride, which lets the kidney excrete the excess bicarbonate, and potassium chloride is added. Lactate-containing fluids add a bicarbonate precursor, and 5% dextrose provides no sodium or chloride.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.086 Q11. The paper offered Ringer''s, Darrow''s, normal saline, dextrose and Hartmann''s; some local notes recommend plain Ringer''s (also chloride-rich). Options and stem were adjusted so normal saline with potassium is the single best answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-aed35a2bd6', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'All of the following are true of clonidine EXCEPT:', '["It can be administered as a transdermal preparation", "It is a centrally acting sympathoplegic agent", "It causes sedation", "Abrupt withdrawal can cause rebound hypertension", "It is an α-adrenergic receptor antagonist"]'::jsonb, 'It is an α-adrenergic receptor antagonist', '[]'::jsonb, 'Clonidine is an α2-adrenoceptor agonist: it stimulates presynaptic and central α2 receptors in the brainstem, reducing sympathetic outflow. It causes sedation and dry mouth, is available as weekly transdermal patches, and must be tapered, because abrupt withdrawal causes a catecholamine surge with severe rebound hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.088 Q16') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-e0112978ae', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'The following agents are used in the management of shock EXCEPT:', '["Digoxin", "Adrenaline", "Dobutamine", "Vasopressin", "Amrinone"]'::jsonb, 'Digoxin', '[]'::jsonb, 'Digoxin has a slow onset, a narrow therapeutic index and is arrhythmogenic in the setting of hypoxia, acidosis and electrolyte disturbance, so it has no role in acute circulatory shock. Vasopressors such as adrenaline and vasopressin, the inotrope dobutamine, and phosphodiesterase-3 inhibitors such as amrinone and milrinone are used.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.088 Q17') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-fe1ed292ad', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which is false?', '["Ouabain is given intravenously", "Digitoxin is highly lipid soluble", "Digoxin has a narrow therapeutic index", "Digoxin is lost predominantly via the renal route", "Digoxin is contraindicated in patients with atrial fibrillation"]'::jsonb, 'Digoxin is contraindicated in patients with atrial fibrillation', '[]'::jsonb, 'Digoxin is a long-established rate-control drug in atrial fibrillation, particularly with coexisting heart failure, because it slows AV nodal conduction through vagal effects. It is contraindicated only when AF coexists with an accessory pathway (WPW). Digitoxin is more lipid-soluble and hepatically cleared, while ouabain is given only IV.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.090 Q21') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-dacd1f5263', 'pharm-drugs-used-in-angina', 'mcq', 'Which drug is not used in angina treatment?', '["Nicorandil", "Amyl nitrite", "Verapamil", "Isosorbide mononitrate", "Ergotamine"]'::jsonb, 'Ergotamine', '[]'::jsonb, 'Ergotamine is an ergot alkaloid that constricts arteries, including coronary arteries, through α-adrenergic and 5-HT receptors, so it can provoke angina and is contraindicated in ischaemic heart disease. Nitrates, including amyl nitrite and isosorbide mononitrate, the potassium channel opener nicorandil, and calcium channel blockers such as verapamil all treat angina.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.090 Q23') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-25dfdcfc84', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'The following are associated with thiazide diuretic use EXCEPT:', '["Hyperuricaemia", "Low cholesterol", "Hyperglycaemia", "Hypokalaemia", "Reduced libido"]'::jsonb, 'Low cholesterol', '[]'::jsonb, 'Thiazides tend to raise total cholesterol, LDL and triglycerides modestly, rather than lower them. Their other metabolic effects include hypokalaemia, hyperuricaemia (precipitating gout), impaired glucose tolerance, hyponatraemia and hypercalcaemia. Erectile dysfunction and reduced libido are recognised adverse effects in men.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.090 Q24') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-13981e62e1', 'pharm-major-tranquilizer', 'mcq', 'Which of the following is a second-generation antipsychotic agent?', '["Chlorpromazine", "Thioridazine", "Promethazine", "Haloperidol", "Quetiapine"]'::jsonb, 'Quetiapine', '[]'::jsonb, 'Quetiapine is an atypical (second-generation) antipsychotic with weak, rapidly dissociating D2 binding and stronger 5-HT2A antagonism, giving a very low extrapyramidal risk but marked sedation. Chlorpromazine and thioridazine are first-generation phenothiazines, haloperidol is a first-generation butyrophenone, and promethazine is a phenothiazine antihistamine.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.090 Q25') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-92d6ddf673', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'The following drugs have prokinetic effects EXCEPT:', '["Neostigmine", "Erythromycin", "Scopolamine", "Bethanechol", "Cisapride"]'::jsonb, 'Scopolamine', '[]'::jsonb, 'Scopolamine (hyoscine) is an antimuscarinic that reduces gut motility and secretions; it is used for motion sickness and colicky spasm. Prokinetic drugs increase motility: neostigmine and bethanechol increase cholinergic stimulation, erythromycin activates motilin receptors, and cisapride enhances acetylcholine release through 5-HT4 receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.092 Q33') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-emetics-antiemetics-and-prokinetic-age-718f3fe75d', 'pharm-emetics-antiemetics-and-prokinetic-agents', 'mcq', 'Which of the following is not appropriately matched with its clinical indication?', '["Promethazine: morning sickness of pregnancy", "Hyoscine: chemotherapy-induced vomiting", "Ondansetron: radiotherapy-induced vomiting", "Chlorpromazine: cancer-related vomiting", "Dronabinol: chemotherapy-induced vomiting refractory to other agents"]'::jsonb, 'Hyoscine: chemotherapy-induced vomiting', '[]'::jsonb, 'Hyoscine (scopolamine) is the most effective drug for preventing motion sickness, acting on vestibular muscarinic pathways; it has little effect on chemotherapy-induced emesis, which is driven by 5-HT3 and NK1 receptors. Promethazine is used in pregnancy sickness, ondansetron for chemo- and radiotherapy vomiting, and dronabinol for refractory chemotherapy vomiting.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.093 Q40. Changed dronabinol''s match from ''drug induced vomiting'' to make the item unambiguous.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-9b1540ab6b', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'All of the following are true about the stages of general anaesthesia EXCEPT:', '["Stage I begins with inhalation of anaesthetic and ends with loss of consciousness", "Minor surgical procedures like tooth extraction can be done in stage I", "Stage II is marked by irregular respiration in both rate and volume", "Unpleasant reactions in stage II are the same for all general anaesthetic agents", "The end of stage III is marked by cessation of spontaneous respiration"]'::jsonb, 'Unpleasant reactions in stage II are the same for all general anaesthetic agents', '[]'::jsonb, 'The excitement of stage II varies greatly between agents: it was prominent with slow-acting ether but is hardly seen with rapid modern agents such as propofol or sevoflurane. Stage I (analgesia) runs from induction to loss of consciousness and allowed brief procedures historically; stage III ends when spontaneous respiration ceases, heralding stage IV.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.093 Q41') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-8826e40410', 'pharm-inhalational-anesthetic-agents', 'mcq', 'All of the following are true about nitrous oxide EXCEPT:', '["It lacks analgesic properties", "It is rapidly absorbed on inhalation", "It is a sweet-smelling, non-irritating, colourless gas", "It is non-flammable but supports combustion", "Its boiling point is -89 °C"]'::jsonb, 'It lacks analgesic properties', '[]'::jsonb, 'Nitrous oxide is a good analgesic at subanaesthetic concentrations (as Entonox, 50% with oxygen, in labour and emergencies), acting partly through NMDA antagonism and endogenous opioid release. It is a weak anaesthetic (MAC about 105%), so it is combined with other agents. It has a low blood:gas coefficient, giving rapid onset, and supports combustion.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.095 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-66a39cacc5', 'pharm-intravenous-anesthetic-agents', 'mcq', 'All of the following are true of thiopentone EXCEPT:', '["It causes hypnosis in less than one minute", "Its metabolism is faster than its tissue redistribution", "It has no analgesic properties", "It depresses the respiratory centre", "It is contraindicated in porphyria"]'::jsonb, 'Its metabolism is faster than its tissue redistribution', '[]'::jsonb, 'Thiopentone''s rapid recovery after a single dose is due to redistribution from brain to muscle and fat; hepatic metabolism is slow, at about 10 to 15% per hour. It acts within one arm-brain circulation time, is anti-analgesic rather than analgesic, depresses respiration, and can precipitate acute porphyria by inducing ALA synthase.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.095 Q3') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-8566f0bda8', 'pharm-local-anesthetic-agents', 'mcq', 'Which of the following local anaesthetics is primarily hydrolysed by plasma cholinesterase?', '["Lignocaine", "Proparacaine", "Etidocaine", "Ropivacaine", "Prilocaine"]'::jsonb, 'Proparacaine', '[]'::jsonb, 'Proparacaine (proxymetacaine) is an ester local anaesthetic, used as eye drops, and like other esters it is hydrolysed by plasma pseudocholinesterase. Lignocaine, etidocaine, ropivacaine and prilocaine are amides metabolised by hepatic enzymes; prilocaine''s metabolite o-toluidine can cause methaemoglobinaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.097 Q1') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-d29a3bd8e7', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which of the following muscle relaxants does not cause histamine release?', '["Pancuronium", "Tubocurarine", "Atracurium", "Mivacurium", "Succinylcholine"]'::jsonb, 'Pancuronium', '[]'::jsonb, 'Pancuronium is an aminosteroid neuromuscular blocker, and steroidal agents (pancuronium, vecuronium, rocuronium) do not release histamine; pancuronium instead causes tachycardia by vagal blockade. Benzylisoquinolines such as tubocurarine, atracurium and mivacurium release histamine, causing flushing, hypotension and bronchospasm, and succinylcholine releases some too.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.097 Q2') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-treating-pancreatic-disorder-bf253caaaa', 'pharm-drugs-for-treating-pancreatic-disorders-aprotinin-glucagon-use-o', 'mcq', 'Which of the following drugs is not used to reduce the risk of bleeding from oesophageal varices?', '["Isosorbide dinitrate", "Propranolol", "Atenolol", "Somatostatin", "Nitroglycerin"]'::jsonb, 'Atenolol', '[]'::jsonb, 'Atenolol is β1-selective, so it does not block β2-mediated splanchnic vasodilation and lowers portal pressure much less than non-selective propranolol or nadolol. Somatostatin and its analogue octreotide reduce splanchnic flow during acute bleeds, and nitrates have been combined with vasopressin or β-blockers to lower portal pressure.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.097 Q3') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-for-inflammatory-and-irritable-b-ea74a7e21a', 'pharm-drugs-for-inflammatory-and-irritable-bowel-disease', 'mcq', 'Which of the following preparations is a suppository used in the management of inflammatory bowel disease?', '["Canasa", "Rowasa", "Asacol", "Pentasa", "Olsalazine"]'::jsonb, 'Canasa', '[]'::jsonb, 'Canasa is a mesalazine (5-ASA) rectal suppository that delivers drug to the rectum for ulcerative proctitis. Rowasa is a mesalazine enema reaching the descending colon, Asacol and Pentasa are oral delayed- or controlled-release mesalazine, and olsalazine is an oral azo-bonded 5-ASA dimer split by colonic bacteria.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.097 Q4. Brand-name question; brand availability varies between countries.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-cec8c14d90', 'pharm-sedative-hypnotic-drugs', 'mcq', 'Which of the following sedative-hypnotics acts selectively on GABA-A receptors?', '["Buspirone", "Pyrilamine", "Hydroxyzine", "Ethanol", "Nitrazepam"]'::jsonb, 'Nitrazepam', '[]'::jsonb, 'Nitrazepam is a benzodiazepine that binds the benzodiazepine site of GABA-A receptors and increases the frequency of chloride channel opening. Ethanol also enhances GABA-A function but acts on many other targets, including NMDA receptors. Buspirone is a 5-HT1A partial agonist, and pyrilamine and hydroxyzine are H1 antagonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.097 Q5') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-1158252f79', 'pharm-antidepressants-and-lithium', 'mcq', 'All of the following are true of tricyclic antidepressants EXCEPT:', '["Their antidepressant effect is realised only after 2 to 3 months", "They can be used for prolonged treatment of depression without tolerance", "They block α-adrenoceptors", "They are used for treatment of severe endogenous depression", "They readily penetrate the CNS"]'::jsonb, 'Their antidepressant effect is realised only after 2 to 3 months', '[]'::jsonb, 'The mood-lifting effect of tricyclics appears after about 2 to 4 weeks, not months, although full recovery may take longer. They are lipid-soluble and enter the brain readily, keep working without tolerance during long-term therapy, block α1 adrenoceptors (postural hypotension) as well as muscarinic and H1 receptors, and are effective in severe depression.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.098 Q6') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-leukotriene-inhibitors-other-drugs-7b9e54b1a5', 'pharm-leukotriene-inhibitors-other-drugs', 'mcq', 'Which statement regarding zileuton is true?', '["It is a competitive antagonist at leukotriene LTD4 receptors", "It is given once a day", "It is indicated as a reliever medication in asthma", "It decreases the clearance of theophylline", "It is available as an inhaler for management of asthma"]'::jsonb, 'It decreases the clearance of theophylline', '[]'::jsonb, 'Zileuton inhibits 5-lipoxygenase, blocking synthesis of all leukotrienes; it is not a receptor antagonist like montelukast. It is taken orally several times daily (or twice daily as modified-release) as a controller, not a reliever. It inhibits CYP1A2, raising theophylline and warfarin levels, and can cause raised liver enzymes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.104 Q7') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-addiction-and-abuse-addiction-to--147b0f8d47', 'pharm-drug-addiction-and-abuse-addiction-to-cannabinoids-inhalants', 'mcq', 'Features of nicotine withdrawal include all the following EXCEPT:', '["Irritability", "Powerful craving for tobacco", "Decreased appetite", "Attention difficulties", "Insomnia"]'::jsonb, 'Decreased appetite', '[]'::jsonb, 'Nicotine suppresses appetite, so withdrawal increases appetite and causes weight gain, a common reason for relapse. Other withdrawal features are craving, irritability, anxiety, restlessness, difficulty concentrating, low mood and insomnia, peaking in the first week. Nicotine replacement, varenicline and bupropion reduce these symptoms.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.104 Q8') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenergic-neurone-blocking-drugs-c81da81454', 'pharm-adrenergic-neurone-blocking-drugs', 'mcq', 'Which adrenergic neuron-blocking drug works by inhibiting the vesicular membrane-associated transporter?', '["Guanadrel", "Reserpine", "Debrisoquine", "Bethanidine", "Guanethidine"]'::jsonb, 'Reserpine', '[]'::jsonb, 'Reserpine irreversibly blocks VMAT2, the vesicular monoamine transporter, so noradrenaline, dopamine and serotonin cannot be stored and are degraded by MAO. Guanethidine, guanadrel, debrisoquine and bethanidine are taken up by the neuronal noradrenaline transporter, enter vesicles, displace noradrenaline and block its release.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.104 Q9') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-anesthesia-classificat-7fad050ac0', 'pharm-introduction-to-anesthesia-classification-and-mechanism-of-actio', 'mcq', 'The following general anaesthetics act on GABA-A receptors EXCEPT:', '["Propofol", "Thiopental", "Ketamine", "Halothane", "Etomidate"]'::jsonb, 'Ketamine', '[]'::jsonb, 'Ketamine acts mainly by non-competitive blockade of NMDA glutamate receptors, producing dissociative anaesthesia with analgesia, and has little effect on GABA-A receptors. Propofol, thiopental and etomidate enhance GABA-A receptor function, and volatile agents such as halothane potentiate GABA-A and glycine receptors as well as other targets.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.104 Q10') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-3c4aa09eca', 'pharm-preanesthetic-agent', 'mcq', 'Pre-anaesthesia medications are administered to produce the following effects EXCEPT:', '["Amnesia", "Relief of pain", "Reduced salivation", "Emesis", "Reduced anxiety"]'::jsonb, 'Emesis', '[]'::jsonb, 'Premedication aims to prevent, not cause, postoperative nausea and vomiting, which is why antiemetics such as ondansetron or metoclopramide are given. Its other aims are anxiolysis and amnesia (benzodiazepines), analgesia (opioids), reduced secretions (antimuscarinics) and reduced gastric acidity and volume (H2 antagonists, PPIs, antacids).', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.105 Q11') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-8b2000cbf5', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'The following are true EXCEPT:', '["Desmopressin has greater antidiuretic activity than vasopressin", "Desmopressin is used in haemophilia A and von Willebrand disease", "Vasopressin is used to reduce oesophageal variceal bleeding", "Vasopressin constricts vascular smooth muscle via V1 receptors", "Desmopressin causes seizures because it causes hypernatraemia"]'::jsonb, 'Desmopressin causes seizures because it causes hypernatraemia', '[]'::jsonb, 'Desmopressin is a V2-selective analogue with a much higher antidiuretic-to-pressor ratio than vasopressin. By promoting water retention it can cause dilutional hyponatraemia, which leads to cerebral oedema and seizures, especially with excess fluid intake. It also releases factor VIII and von Willebrand factor, while vasopressin''s V1 vasoconstriction reduces portal flow.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.105 Q13. Replaced ''Vasopressin is contraindicated in acute renal failure'' (debatable) with a clearly true V1 statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-333856c121', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'All of the following are true of loop diuretics EXCEPT:', '["They act at the thick ascending limb of the loop of Henle", "Furosemide is a sulfonamide derivative", "Probenecid inhibits furosemide excretion", "They are used in hepatic encephalopathy", "They are ototoxic"]'::jsonb, 'They are used in hepatic encephalopathy', '[]'::jsonb, 'Loop diuretics can precipitate hepatic encephalopathy, because hypokalaemia and alkalosis increase renal ammonia production and its entry into the brain; hepatic encephalopathy is treated with lactulose and rifaximin. Furosemide is a sulfonamide derivative secreted by organic anion transporters (which probenecid blocks), acts on the thick ascending limb, and is ototoxic at high doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.105 Q14') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-f0a0c1ac66', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'All of the following are true of α-methyldopa EXCEPT:', '["It reduces peripheral vascular resistance", "It has α2-agonist effects in the CNS", "It is a centrally acting sympathoplegic agent", "It is a prodrug", "Insomnia is common"]'::jsonb, 'Insomnia is common', '[]'::jsonb, 'Methyldopa''s commonest adverse effect is sedation, not insomnia; it also causes depression, nightmares, dry mouth, hyperprolactinaemia, a positive Coombs test and occasionally haemolytic anaemia or hepatitis. As a prodrug converted to α-methylnoradrenaline, it stimulates central α2 receptors and lowers blood pressure mainly by reducing peripheral resistance.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.105 Q15') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-6f82b689b0', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'The following are manifestations of the propranolol withdrawal syndrome EXCEPT:', '["Increased intensity of angina", "Rebound hypertension", "Bradycardia", "Myocardial infarction", "Nervousness"]'::jsonb, 'Bradycardia', '[]'::jsonb, 'Long-term β-blockade up-regulates β receptors, so abrupt withdrawal exposes a supersensitive heart to catecholamines. This causes tachycardia, not bradycardia, along with palpitations, nervousness, sweating, rebound hypertension, worsening angina and even myocardial infarction. β-blockers should therefore be tapered over 1 to 2 weeks.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.105 Q16') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-e8f66bc90d', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which statement about phenytoin is untrue?', '["Its absorption from the IM route is unpredictable", "It is a prodrug of fosphenytoin", "It is given IV in status epilepticus", "It is largely bound to plasma proteins", "Its elimination is dose-dependent"]'::jsonb, 'It is a prodrug of fosphenytoin', '[]'::jsonb, 'The relationship is the other way round: fosphenytoin is the water-soluble phosphate prodrug that is converted to phenytoin. Phenytoin precipitates in muscle, so IM absorption is erratic, and it is about 90% bound to albumin. Its metabolism saturates within the therapeutic range, so elimination changes from first- to zero-order kinetics.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.106 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-fc16b02920', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which antiparkinsonian drug is not a dopaminergic drug?', '["Entacapone", "Amantadine", "Levodopa", "Lisuride", "Benztropine"]'::jsonb, 'Benztropine', '[]'::jsonb, 'Benztropine is a central antimuscarinic: it rebalances striatal cholinergic overactivity, improving tremor and rigidity, without acting on dopamine systems. The others enhance dopaminergic transmission: levodopa is a dopamine precursor, entacapone prolongs levodopa''s action, lisuride is a dopamine agonist, and amantadine promotes dopamine release.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.107 Q25') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methadone-and-congeners-partial-agonis-38c943184a', 'pharm-methadone-and-congeners-partial-agonists-opioid-antagonists', 'mcq', 'Which is the correct statement?', '["Methadone is a potent μ-receptor antagonist", "Propoxyphene has potent analgesic activity", "Diphenoxylate is used for the treatment of constipation", "Methadone is used in treatment of opioid dependence", "Meperidine is the opioid of choice in epilepsy"]'::jsonb, 'Methadone is used in treatment of opioid dependence', '[]'::jsonb, 'Methadone is a long-acting oral μ agonist; once-daily dosing prevents withdrawal and blunts the euphoria of injected heroin, making it the standard opioid substitution therapy. Propoxyphene is a weak analgesic (withdrawn for cardiotoxicity), diphenoxylate treats diarrhoea, and meperidine''s metabolite normeperidine lowers the seizure threshold.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.107 Q27') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-43652506f1', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which is the false statement about inhaled anaesthesia?', '["Drugs with low solubility in blood have a faster onset of action", "Hyperventilation increases the speed of induction", "Clearance of inhaled anaesthetic agents via the kidneys is the major route of elimination", "Nitrous oxide is not metabolised by human tissues", "Isoflurane is a volatile liquid"]'::jsonb, 'Clearance of inhaled anaesthetic agents via the kidneys is the major route of elimination', '[]'::jsonb, 'Inhaled anaesthetics are eliminated mainly by exhalation through the lungs, the reverse of uptake, so recovery depends on ventilation and blood:gas solubility. Low blood solubility gives fast induction and recovery, and hyperventilation speeds induction. Nitrous oxide is essentially not metabolised, and isoflurane is a volatile liquid delivered by vaporiser.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.108 Q28') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-8758c30053', 'pharm-inhalational-anesthetic-agents', 'mcq', 'All of the following are true about halothane EXCEPT:', '["It decreases mean arterial pressure", "It causes bronchoconstriction", "It increases cerebral blood flow", "It can cause hepatitis", "It relaxes uterine smooth muscle"]'::jsonb, 'It causes bronchoconstriction', '[]'::jsonb, 'Halothane is a bronchodilator and has been used in severe refractory asthma. Like other volatile agents it lowers arterial pressure, dilates cerebral vessels (raising cerebral blood flow and intracranial pressure) and relaxes uterine muscle, increasing postpartum bleeding. Immune-mediated hepatitis is its most feared adverse effect.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.108 Q29') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-8b1f521649', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which statement about neuromuscular blocking agents is true?', '["They must be administered parenterally", "Atracurium is activated by Hofmann elimination", "Mivacurium causes hypertension", "Succinylcholine has a long duration of action", "Non-depolarising relaxant drugs undergo phase I and phase II block"]'::jsonb, 'They must be administered parenterally', '[]'::jsonb, 'Neuromuscular blockers are highly polar quaternary ammonium compounds that are not absorbed from the gut, so they are given IV. Hofmann elimination inactivates, rather than activates, atracurium. Mivacurium''s histamine release lowers blood pressure, succinylcholine is short-acting, and phase I and II blocks describe depolarising agents.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.108 Q30') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-377b605629', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which statement about acetazolamide is false?', '["It is a carbonic anhydrase inhibitor", "An increase in urine pH occurs within 30 minutes", "It depresses bicarbonate reabsorption in the proximal convoluted tubule", "It is used for glaucoma", "It characteristically causes insomnia"]'::jsonb, 'It characteristically causes insomnia', '[]'::jsonb, 'Acetazolamide typically causes drowsiness and paraesthesiae rather than insomnia, along with hyperchloraemic metabolic acidosis, hypokalaemia, calcium phosphate stones and sulfonamide allergy. By inhibiting proximal tubular carbonic anhydrase, it alkalinises the urine within minutes, and it reduces aqueous humour formation in glaucoma.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.108 Q32. The original ''Causes insomnia'' was not a clearly established fact either way; reworded to ''characteristically''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-41aea4fcde', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'The following are adverse effects of thiazide diuretics EXCEPT:', '["Metabolic alkalosis", "Hypernatraemia", "Hyperuricaemia", "Hyperlipidaemia", "Hyperglycaemia"]'::jsonb, 'Hypernatraemia', '[]'::jsonb, 'Thiazides cause hyponatraemia rather than hypernatraemia, because they impair urinary dilution in the distal tubule while ADH-driven water retention continues; elderly women are especially at risk. Their other adverse effects include hypokalaemic metabolic alkalosis, hyperuricaemia, raised lipids and impaired glucose tolerance.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.108 Q33') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-opioid-analgesics-clas-b22d535583', 'pharm-introduction-to-opioid-analgesics-classification-mechanism-of-ac', 'mcq', 'The following are indications of opioid analgesics EXCEPT:', '["Analgesia", "Acute pulmonary oedema", "Constipation", "Post-anaesthetic shivering", "Cough"]'::jsonb, 'Constipation', '[]'::jsonb, 'Opioids cause constipation, which is a major adverse effect, by increasing segmental tone and reducing propulsive peristalsis; they are used to treat diarrhoea, not constipation. Indications include pain, cough suppression (codeine), dyspnoea in acute pulmonary oedema (morphine), and post-anaesthetic shivering (pethidine).', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.109 Q39') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-opioid-use-and-abuse-6575c557ae', 'pharm-opioid-use-and-abuse', 'mcq', 'The following are withdrawal signs of opioids EXCEPT:', '["Rhinorrhoea", "Miosis", "Yawning", "Chills", "Gooseflesh"]'::jsonb, 'Miosis', '[]'::jsonb, 'Opioid withdrawal produces mydriasis, the opposite of the pinpoint pupils seen with opioid use. Other signs reflect rebound autonomic hyperactivity: rhinorrhoea, lacrimation, yawning, chills with piloerection (''cold turkey''), sweating, abdominal cramps, diarrhoea, muscle aches and anxiety. Clonidine helps the autonomic symptoms.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.109 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-a3f20e9faa', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which of the following intravenous anaesthetics is known for increasing intracranial pressure?', '["Thiopental sodium", "Ketamine", "Etomidate", "Propofol", "Althesin"]'::jsonb, 'Ketamine', '[]'::jsonb, 'Ketamine increases cerebral blood flow, cerebral metabolic rate and intracranial pressure through sympathetic stimulation and cerebral vasodilation, so it has traditionally been avoided in raised ICP, though this is now debated with controlled ventilation. Thiopental, propofol and etomidate reduce cerebral metabolism, blood flow and ICP.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.109 Q41') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-22eea8f06f', 'pharm-major-tranquilizer', 'mcq', 'The following are adverse effects of chlorpromazine EXCEPT:', '["Obstructive (cholestatic) jaundice", "Leucocytosis", "Contact dermatitis", "Parkinsonism", "Tardive dyskinesia"]'::jsonb, 'Leucocytosis', '[]'::jsonb, 'Chlorpromazine can cause agranulocytosis or leucopenia, an idiosyncratic and potentially fatal reaction, rather than leucocytosis. Other effects are cholestatic jaundice, skin reactions including contact dermatitis in people handling it and photosensitivity, extrapyramidal syndromes such as parkinsonism and tardive dyskinesia, sedation and postural hypotension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.109 Q42') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-567ac268fc', 'pharm-sedative-hypnotic-drugs', 'mcq', 'The following drugs may be used as anxiolytics EXCEPT:', '["Clonazepam", "Propranolol", "Suvorexant", "Venlafaxine", "Olanzapine"]'::jsonb, 'Suvorexant', '[]'::jsonb, 'Suvorexant is a dual orexin receptor antagonist licensed for insomnia; it blocks wake-promoting orexin signalling and has no established anxiolytic role. Clonazepam is a benzodiazepine used for panic disorder, propranolol relieves somatic symptoms of performance anxiety, venlafaxine is first-line in generalised anxiety, and low-dose atypicals are sometimes used as adjuncts.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.109 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sedative-hypnotic-drugs-20a394d542', 'pharm-sedative-hypnotic-drugs', 'mcq', 'All of the following are true of buspirone EXCEPT:', '["It has a fast onset of action", "Dosage adjustment is required in liver failure", "It is used in generalised anxiety states", "It is not associated with withdrawal signs on abrupt discontinuation", "It has minimal abuse liability"]'::jsonb, 'It has a fast onset of action', '[]'::jsonb, 'Buspirone takes 1 to 2 weeks or more to produce an anxiolytic effect, so it is useless for acute anxiety or panic. It is used for generalised anxiety disorder, causes little sedation, dependence or withdrawal, and has minimal abuse potential. It undergoes extensive CYP3A4 first-pass metabolism, so doses are reduced in hepatic impairment.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.110 Q46') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-git-pharmacology-class-8d6d1585b9', 'pharm-introduction-to-git-pharmacology-classification-of-drugs-for-pep', 'mcq', 'The following factors affect the acid-neutralising capacity of an antacid EXCEPT:', '["Its rate of dissolution", "Its lipid solubility", "Its water solubility", "Its rate of reaction with HCl", "The rate of gastric emptying"]'::jsonb, 'Its lipid solubility', '[]'::jsonb, 'Antacids are weak bases that act locally in the stomach lumen, so their neutralising capacity depends on how quickly they dissolve and react with hydrochloric acid, their water solubility and how long they stay in the stomach (gastric emptying; taking them after meals prolongs their effect). Lipid solubility, which governs absorption across membranes, is irrelevant.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.110 Q47') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-63dcd4706e', 'pharm-local-anesthetic-agents', 'mcq', 'Which is false regarding local anaesthetics?', '["Lidocaine is an amide", "Esters have a short half-life", "They act by opening voltage-gated sodium channels", "Their duration of action is increased when combined with adrenaline", "They have effects on the heart if given systemically"]'::jsonb, 'They act by opening voltage-gated sodium channels', '[]'::jsonb, 'Local anaesthetics block voltage-gated sodium channels, binding from inside the cell to channels in the open and inactivated states, so action potentials cannot be propagated. Esters are rapidly hydrolysed in plasma, adrenaline prolongs block by vasoconstriction, and systemic absorption depresses cardiac conduction and contractility.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.112 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-667589df58', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which is a class III antiarrhythmic drug?', '["Propranolol", "Amiodarone", "Lignocaine", "Phenytoin", "Digoxin"]'::jsonb, 'Amiodarone', '[]'::jsonb, 'Class III drugs prolong the action potential and refractory period, mainly by blocking potassium currents: amiodarone, sotalol, dofetilide, ibutilide and dronedarone. Amiodarone also has class I, II and IV actions. Propranolol is class II, lignocaine and phenytoin are class Ib, and digoxin is outside the Vaughan Williams classes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.113 Q49') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-4fd44754c7', 'pharm-antidepressants-and-lithium', 'mcq', 'Which is not a clinical indication for amitriptyline?', '["Depression", "Post-herpetic neuralgia", "Migraine prophylaxis", "Schizophrenia", "Chronic pain syndromes"]'::jsonb, 'Schizophrenia', '[]'::jsonb, 'Amitriptyline is used for depression and, at low doses, for neuropathic pain such as post-herpetic neuralgia, migraine prophylaxis and other chronic pain syndromes. It has no antipsychotic action and may worsen psychosis by its anticholinergic effects; schizophrenia is treated with antipsychotics.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.114 Q51. Replaced ''Eating disorders'' (an uncertain indication) with chronic pain syndromes.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-048ddf432d', 'pharm-sympathomimetics', 'mcq', 'Administration of adrenaline has the following physiological effects EXCEPT:', '["Increased heart rate", "Bronchoconstriction", "Decreased peristalsis and anal sphincter contraction", "Urine retention", "Mydriasis"]'::jsonb, 'Bronchoconstriction', '[]'::jsonb, 'Adrenaline stimulates β2 receptors in bronchial smooth muscle, causing bronchodilation, which makes it lifesaving in anaphylaxis. It increases heart rate (β1), relaxes gut smooth muscle while contracting sphincters, contracts the bladder sphincter (favouring retention), and dilates the pupil through α1 receptors on the radial muscle.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.114 Q52') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-7f1b7161cb', 'pharm-adrenoceptor-blockers', 'mcq', 'Which of the following acts on both α1 and α2 receptors?', '["Prazosin", "Terazosin", "Phenoxybenzamine", "Atenolol", "α-methyldopa"]'::jsonb, 'Phenoxybenzamine', '[]'::jsonb, 'Phenoxybenzamine binds covalently to α1 and α2 receptors, blocking both; α2 blockade increases noradrenaline release and causes marked reflex tachycardia. Prazosin and terazosin are selective α1 antagonists, atenolol is a β1 blocker, and methyldopa acts through its metabolite α-methylnoradrenaline, an α2 agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.114 Q54') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-fc37b872fb', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following is a side effect of thiazide diuretics?', '["Hypoglycaemia", "Precipitation of gout attacks", "Hypercalciuria", "Increased virility", "Thrombocytosis"]'::jsonb, 'Precipitation of gout attacks', '[]'::jsonb, 'Thiazides compete with uric acid for secretion by the organic anion transporter in the proximal tubule, raising serum urate and sometimes precipitating gout. They cause hyperglycaemia rather than hypoglycaemia, reduce urinary calcium, can cause erectile dysfunction, and only rarely cause thrombocytopenia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.115 Q57. Replaced ''Hyponatraemia'' (also a thiazide side effect, so a second correct answer) with hypercalciuria; corrected ''Thrombocytothermia''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-bc957d4a17', 'pharm-intravenous-fluids', 'mcq', 'Which intravenous fluid is most appropriate for a patient with dehydration due to diarrhoea?', '["10% dextrose solution", "Normal saline", "Hartmann''s solution", "Dextrose saline solution", "Ringer''s solution"]'::jsonb, 'Hartmann''s solution', '[]'::jsonb, 'Diarrhoea loses water, sodium, potassium and bicarbonate, causing hypokalaemic metabolic acidosis. Hartmann''s solution (Ringer''s lactate) replaces sodium, potassium and calcium, and its lactate is metabolised to bicarbonate, helping correct the acidosis. Normal saline is acceptable but can worsen acidosis through its chloride load; dextrose solutions do not restore volume.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.115 Q58. Normal saline (or WHO-recommended Ringer''s lactate) are both used; the intended answer appears to be Hartmann''s.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-interactions-c8f4a473e8', 'pharm-drug-interactions', 'mcq', 'Which is not a pharmacodynamic drug interaction?', '["β-blockers and thiazides", "Trimethoprim and sulfamethoxazole", "Tetracycline and aluminium hydroxide (antacid)", "Histamine and adrenaline", "Flumazenil and diazepam"]'::jsonb, 'Tetracycline and aluminium hydroxide (antacid)', '[]'::jsonb, 'Aluminium and other polyvalent cations chelate tetracycline in the gut, reducing its absorption; this is a pharmacokinetic interaction. The others act at the level of drug effect: additive antihypertensive effects, sequential folate pathway blockade, physiological antagonism of histamine by adrenaline, and competitive receptor antagonism of diazepam by flumazenil.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.116 Q5') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-biotransformation-8b3f905a1b', 'pharm-biotransformation', 'mcq', 'The following are enzyme inducers EXCEPT:', '["Carbamazepine", "Sodium valproate", "Phenytoin", "Phenobarbital", "Rifampicin"]'::jsonb, 'Sodium valproate', '[]'::jsonb, 'Sodium valproate is an enzyme inhibitor: it blocks glucuronidation and some CYP enzymes, raising lamotrigine and phenobarbital levels. Carbamazepine (which also induces its own metabolism), phenytoin, phenobarbital and rifampicin are potent inducers of CYP3A4 and other enzymes, reducing the effect of oral contraceptives, warfarin and many other drugs.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.116 Q6') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-blockers-7178cdcd96', 'pharm-adrenoceptor-blockers', 'mcq', 'Which is NOT a clinical use of α-adrenoceptor antagonists?', '["Hyperthyroidism", "Phaeochromocytoma", "Peripheral vascular disease (Raynaud''s)", "Benign prostatic hyperplasia", "Chronic hypertension"]'::jsonb, 'Hyperthyroidism', '[]'::jsonb, 'Hyperthyroid symptoms are driven mainly by β-adrenergic hypersensitivity, so β-blockers such as propranolol are used, not α blockers. α antagonists are used for phaeochromocytoma (phenoxybenzamine before surgery), benign prostatic hyperplasia (tamsulosin, prazosin), hypertension (doxazosin) and Raynaud''s phenomenon.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.117 Q7') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-e951f7e098', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which is an angiotensin II receptor blocker?', '["Clonidine", "Enalapril", "Remikiren", "Losartan", "Propranolol"]'::jsonb, 'Losartan', '[]'::jsonb, 'Losartan competitively blocks the AT1 receptor, preventing angiotensin II-induced vasoconstriction, aldosterone release and cardiac and vascular remodelling; it also has a uricosuric effect. Enalapril is an ACE inhibitor, remikiren a renin inhibitor, clonidine a central α2 agonist and propranolol a β-blocker that reduces renin release.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.118 Q11') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-pharmacology-routes-of-b22adfa5ab', 'pharm-introduction-to-pharmacology-routes-of-drug-administration', 'mcq', 'Which is the FALSE statement regarding intravenous drug administration?', '["It gives a rapid onset of action", "It is titratable", "It is convenient for large volumes", "It is suitable for oily substances", "It is useful in the unconscious patient"]'::jsonb, 'It is suitable for oily substances', '[]'::jsonb, 'Oily solutions and insoluble suspensions must never be given IV because they can cause fat or particle embolism; they are given IM as depots instead. IV administration gives complete bioavailability and immediate onset, allows titration and large-volume infusion, and works in unconscious patients, but once given it cannot be recalled.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.118 Q12. Option a was ''easily reversible'', which is also false; replaced with ''rapid onset of action''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-5744832020', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Which of the following causes dissociative anaesthesia?', '["Sodium thiopental", "Ketamine", "Etomidate", "Halothane", "Nitrous oxide"]'::jsonb, 'Ketamine', '[]'::jsonb, 'Ketamine blocks NMDA receptors and functionally dissociates the cortex from the limbic system: the patient may keep their eyes open, swallow and move, yet is unaware and has profound analgesia and amnesia. Emergence can bring vivid dreams and hallucinations. Thiopental, etomidate and halothane produce conventional anaesthesia without dissociation.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.119 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-c2e8c4ffe9', 'pharm-calcium-channel-blocker', 'mcq', 'Which is the drug of choice in treating vasospasm associated with subarachnoid haemorrhage?', '["Verapamil", "Diltiazem", "Nimodipine", "Felodipine", "Nifedipine"]'::jsonb, 'Nimodipine', '[]'::jsonb, 'Nimodipine is a lipophilic dihydropyridine that crosses the blood-brain barrier and preferentially dilates cerebral arteries. Given orally for 21 days after aneurysmal subarachnoid haemorrhage, it reduces delayed ischaemic deficits and improves outcome. Blood pressure must be watched, as hypotension can worsen cerebral perfusion.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.121 Q34. Corrected ''Telodipine'' to felodipine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-850dc9fcac', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which is not a dopamine receptor agonist used in the treatment of Parkinson''s disease?', '["Bromocriptine", "Pergolide", "Selegiline", "Pramipexole", "Rotigotine"]'::jsonb, 'Selegiline', '[]'::jsonb, 'Selegiline is a selective, irreversible MAO-B inhibitor that slows dopamine breakdown in the striatum; it does not stimulate dopamine receptors and is partly metabolised to amphetamine derivatives. Bromocriptine and pergolide are ergot dopamine agonists (pergolide is withdrawn for valvular fibrosis), while pramipexole and transdermal rotigotine are non-ergot agonists.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.123 Q37') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-be01888aee', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Non-selective β-adrenergic blockers should be used with caution in the following conditions EXCEPT:', '["Hyperthyroidism", "Asthma", "Cardiac conduction disease", "Bradycardia", "Diabetes mellitus"]'::jsonb, 'Hyperthyroidism', '[]'::jsonb, 'Non-selective β-blockers such as propranolol are actively used in hyperthyroidism to control tachycardia, tremor and anxiety. Caution is needed in asthma (β2 blockade causes bronchospasm), heart block and bradycardia, and diabetes, where they mask hypoglycaemic warning signs and delay glucose recovery.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.124 Q40') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-transport-and-distribution-2ca08a8db7', 'pharm-transport-and-distribution', 'mcq', 'Acidic drugs bind mainly to:', '["α1-acid glycoprotein", "Thyroxine-binding globulin", "Lipoprotein", "Albumin", "Globulin"]'::jsonb, 'Albumin', '[]'::jsonb, 'Albumin is the main plasma protein binding weak acids such as warfarin, phenytoin, NSAIDs, sulfonamides and valproate; low albumin (liver disease, nephrotic syndrome) increases their free fraction. Basic drugs such as lidocaine, propranolol and many antidepressants bind mostly to α1-acid glycoprotein, an acute-phase protein.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.125 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-08cbd6d0a0', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which is a loop diuretic?', '["Hydrochlorothiazide", "Triamterene", "Acetazolamide", "Furosemide", "Glycerin"]'::jsonb, 'Furosemide', '[]'::jsonb, 'Furosemide inhibits the Na+/K+/2Cl- cotransporter (NKCC2) in the thick ascending limb, producing a powerful, rapid diuresis; bumetanide, torsemide and ethacrynic acid are the other loop diuretics. Hydrochlorothiazide is a thiazide, triamterene is potassium-sparing, acetazolamide is a carbonic anhydrase inhibitor, and glycerin is an osmotic agent.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.125 Q45') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-major-tranquilizer-e5759c4264', 'pharm-major-tranquilizer', 'mcq', 'Which is not a major tranquilliser (antipsychotic)?', '["Haloperidol", "Clozapine", "Triazolam", "Pimozide", "Chlorpromazine"]'::jsonb, 'Triazolam', '[]'::jsonb, 'Triazolam is a short-acting benzodiazepine hypnotic, a ''minor tranquilliser'' in older terminology. Major tranquillisers are antipsychotics: haloperidol, pimozide and chlorpromazine are typical agents and clozapine is the atypical drug reserved for treatment-resistant schizophrenia because of its agranulocytosis risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.125 Q46') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiarrhythmic-drugs-6330eddb33', 'pharm-antiarrhythmic-drugs', 'mcq', 'Which is NOT a class IB antiarrhythmic drug?', '["Quinidine", "Lidocaine", "Mexiletine", "Phenytoin", "Tocainide"]'::jsonb, 'Quinidine', '[]'::jsonb, 'Quinidine is a class IA drug: it blocks sodium channels with intermediate kinetics and also blocks potassium channels, prolonging the action potential and QT interval. Class IB drugs (lidocaine, mexiletine, tocainide and phenytoin) dissociate quickly, shorten the action potential, and act mainly on depolarised, ischaemic ventricular tissue.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.126 Q53') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-preanesthetic-agent-70994462a0', 'pharm-preanesthetic-agent', 'mcq', 'Which is not a preanaesthetic medication?', '["Neostigmine", "Opioids", "Promethazine", "Atropine", "H2 receptor antagonists"]'::jsonb, 'Neostigmine', '[]'::jsonb, 'Neostigmine is given at the end of anaesthesia, with glycopyrrolate or atropine, to reverse non-depolarising neuromuscular block; it is not premedication. Premedication includes opioids for analgesia, promethazine for sedation and antiemesis, atropine to dry secretions and block vagal reflexes, and H2 antagonists to reduce aspiration risk.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.126 Q54') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-b3e2400730', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which is the TRUE statement about angiotensin II?', '["It is a less potent vasoconstrictor than noradrenaline", "It inhibits aldosterone synthesis", "It is dipsogenic", "It is anti-mitogenic", "It has a slow onset of action"]'::jsonb, 'It is dipsogenic', '[]'::jsonb, 'Angiotensin II acts on circumventricular organs in the brain to stimulate thirst (dipsogenesis) and ADH release, helping restore volume. It is roughly 40 times more potent than noradrenaline as a vasoconstrictor, acts within seconds, stimulates aldosterone synthesis, and promotes cell growth and fibrosis in the heart and vessels, which ACE inhibitors and ARBs counteract.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.127 Q58') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-indirect-acting-cholinomimetics-fbf9190648', 'pharm-indirect-acting-cholinomimetics', 'mcq', 'Which is the FALSE statement about physostigmine?', '["It is poorly absorbed", "It is distributed in the central nervous system", "It is more toxic than neostigmine", "It is a tertiary carbamic acid ester", "It is used in the treatment of glaucoma"]'::jsonb, 'It is poorly absorbed', '[]'::jsonb, 'Physostigmine is a tertiary amine, so it is well absorbed from the gut and mucous membranes and crosses the blood-brain barrier, which lets it reverse central anticholinergic toxicity but also makes it more toxic than quaternary neostigmine. It is a carbamate cholinesterase inhibitor and has been used topically for glaucoma.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.127 Q60') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-79911b56e6', 'pharm-sympathomimetics', 'mcq', 'Which is not an effect of sympathomimetic drugs?', '["Vasoconstriction through α receptors", "Vasodilation through β2 receptors", "Bronchoconstriction through β2 receptors", "Reduced salt and water flux into the intestinal lumen through α2 receptors", "Tachycardia through β1 receptors"]'::jsonb, 'Bronchoconstriction through β2 receptors', '[]'::jsonb, 'β2 receptor stimulation relaxes bronchial smooth muscle, causing bronchodilation, which is the basis for β2 agonists in asthma. Sympathomimetics also constrict vessels via α1 receptors, dilate skeletal muscle vessels via β2, increase heart rate via β1, and reduce intestinal secretion via α2 receptors, which is why clonidine can help diarrhoea.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.128 Q62') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-diuretics-osmotic-diur-27f469a5fb', 'pharm-introduction-to-diuretics-osmotic-diuretics', 'mcq', 'Which is NOT an indication for diuretic therapy?', '["Hypertension", "Urinary tract infection", "Heart failure", "Oedema in renal failure", "Nephrotic syndrome"]'::jsonb, 'Urinary tract infection', '[]'::jsonb, 'Urinary tract infection is treated with antibiotics and fluids; diuretics have no role. Diuretics are used to lower blood pressure (thiazides), relieve congestion in heart failure (loop diuretics, plus mineralocorticoid antagonists for survival), control fluid overload in renal failure, and treat the oedema of nephrotic syndrome and cirrhosis.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.129 Q66') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-8e7eadc179', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which drug blocks both α- and β-adrenergic receptors?', '["Propranolol", "Atenolol", "Carvedilol", "Esmolol", "Acebutolol"]'::jsonb, 'Carvedilol', '[]'::jsonb, 'Carvedilol blocks β1, β2 and α1 receptors and has antioxidant properties; its α1 blockade adds vasodilation. It is one of the β-blockers shown to reduce mortality in heart failure. Propranolol is non-selective β only, while atenolol, esmolol and acebutolol are β1-selective.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.130 Q68') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-a765b1a0ec', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'Which is NOT an indication for desmopressin?', '["Central diabetes insipidus", "Primary nocturnal enuresis", "Haemophilia A", "Von Willebrand disease", "Congestive cardiac failure"]'::jsonb, 'Congestive cardiac failure', '[]'::jsonb, 'Desmopressin causes water retention through V2 receptors, which would worsen fluid overload and hyponatraemia in heart failure. It replaces ADH in central diabetes insipidus, reduces night-time urine output in nocturnal enuresis, and releases factor VIII and von Willebrand factor from endothelium in mild haemophilia A and type 1 von Willebrand disease.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.131 Q72') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-d753b5c8cf', 'pharm-calcium-channel-blocker', 'mcq', 'Which is NOT a dihydropyridine calcium channel blocker?', '["Amlodipine", "Nicardipine", "Nifedipine", "Felodipine", "Verapamil"]'::jsonb, 'Verapamil', '[]'::jsonb, 'Verapamil is a phenylalkylamine that acts mainly on cardiac L-type channels, slowing SA and AV nodal conduction and reducing contractility; it treats supraventricular tachycardias and causes constipation. Dihydropyridines, recognisable by the ''-dipine'' suffix, act mainly on vascular smooth muscle, causing vasodilation, flushing and ankle oedema.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.132 Q74') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-21b266441c', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which drug is used in the management of malignant hyperthermia?', '["Tizanidine", "Baclofen", "Dantrolene", "Diazepam", "Doxacurium"]'::jsonb, 'Dantrolene', '[]'::jsonb, 'Malignant hyperthermia is an inherited disorder, usually of the RyR1 ryanodine receptor, triggered by volatile anaesthetics and succinylcholine; uncontrolled calcium release causes rigidity, hypercarbia and hyperthermia. IV dantrolene blocks RyR1 and stops calcium release, together with stopping the trigger, cooling and correcting acidosis and hyperkalaemia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.133 Q76') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-94812a8763', 'pharm-intravenous-anesthetic-agents', 'mcq', 'All of the following are true of barbiturate anaesthetics EXCEPT:', '["They have a rapid onset of effect", "They have an analgesic effect", "They cause respiratory depression", "They are desirable for patients with cerebral swelling", "They are highly lipid-soluble"]'::jsonb, 'They have an analgesic effect', '[]'::jsonb, 'Barbiturates such as thiopental have no analgesic effect; at subanaesthetic doses they may even lower the pain threshold (anti-analgesia). They are highly lipid-soluble, so they act within one arm-brain circulation time, cause dose-dependent respiratory depression, and lower cerebral metabolism and intracranial pressure, which is useful with cerebral oedema.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.133 Q77') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drugs-used-in-angina-c22dc96607', 'pharm-drugs-used-in-angina', 'mcq', 'Which drug is NOT used in the management of angina?', '["Isosorbide dinitrate", "Propranolol", "Nifedipine", "Pentoxifylline", "Ranolazine"]'::jsonb, 'Pentoxifylline', '[]'::jsonb, 'Pentoxifylline is a methylxanthine derivative that improves red cell deformability and lowers blood viscosity; it is used for intermittent claudication in peripheral arterial disease, not angina. Nitrates, β-blockers and calcium channel blockers are standard antianginals, and ranolazine inhibits the late sodium current, reducing calcium overload in ischaemic myocytes.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.134 Q79') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-475f967c4a', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement about lithium is true?', '["Its half-life is 4 to 6 hours", "It is highly plasma protein bound", "The onset of its pharmacological effect is 10 hours", "It has a narrow therapeutic index", "Long-term use causes hyperthyroidism"]'::jsonb, 'It has a narrow therapeutic index', '[]'::jsonb, 'Lithium''s therapeutic range (about 0.6 to 1.0 mmol/L) is close to toxic levels, so serum levels are checked 12 hours after a dose. It is not protein-bound, distributes in total body water, and has a half-life of about 20 hours. Its antimanic effect takes 1 to 2 weeks, and long-term use mainly causes hypothyroidism and goitre.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.137 Q21') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidiarrheal-agents-laxatives-738bc610d9', 'pharm-antidiarrheal-agents-laxatives', 'mcq', 'Which of the following is a bulk laxative?', '["Calcium polycarbophil", "Frangula", "Mannitol", "Bisacodyl", "Sodium docusate"]'::jsonb, 'Calcium polycarbophil', '[]'::jsonb, 'Bulk-forming laxatives such as calcium polycarbophil, methylcellulose, psyllium (ispaghula) and bran are indigestible fibres that absorb water, increasing stool mass and stimulating peristalsis over 1 to 3 days. Frangula and bisacodyl are stimulant laxatives, mannitol is an osmotic agent, and docusate is a stool softener.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.137 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-1d92f6b0ee', 'pharm-sympathomimetics', 'mcq', 'Which statement about dobutamine is true?', '["It has no arrhythmogenic effect", "It decreases myocardial oxygen consumption", "It is a non-selective β agonist", "It predominantly affects D2 receptors in the central nervous system", "It may be used in heart failure"]'::jsonb, 'It may be used in heart failure', '[]'::jsonb, 'Dobutamine is a relatively β1-selective agonist given by IV infusion to increase contractility and cardiac output in acute decompensated heart failure and cardiogenic shock, and in cardiac stress testing. It increases myocardial oxygen demand and can provoke arrhythmias and angina, and it does not act on dopamine receptors despite its name.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.138 Q19') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-08f73ff67e', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which of the following antihypertensives acts on the vasomotor centre?', '["Prazosin", "Methyldopa", "Hydralazine", "Reserpine", "Losartan"]'::jsonb, 'Methyldopa', '[]'::jsonb, 'Methyldopa''s metabolite α-methylnoradrenaline stimulates α2 receptors in the vasomotor centre of the medulla, reducing sympathetic outflow to the heart and vessels; clonidine acts at the same site directly. Prazosin blocks peripheral α1 receptors, hydralazine dilates arterioles directly, reserpine depletes amine stores, and losartan blocks AT1 receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.138 Q20') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-valproic-acid-oxazolidinediones-benzod-847198b117', 'pharm-valproic-acid-oxazolidinediones-benzodiazepines', 'mcq', 'All of the following are true about sodium valproate EXCEPT:', '["It stabilises mood in bipolar disorder", "It is contraindicated in the treatment of absence seizures", "It is teratogenic", "It can cause liver damage", "It can cause hair loss in chronic use"]'::jsonb, 'It is contraindicated in the treatment of absence seizures', '[]'::jsonb, 'Valproate is a first-line drug for absence seizures, especially when tonic-clonic seizures coexist, and is broad-spectrum for generalised epilepsies. It is also a mood stabiliser. It is strongly teratogenic (neural tube defects, developmental delay), can cause fatal hepatotoxicity especially in young children, and causes hair thinning, weight gain and tremor.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.139 Q40. Reworded options a, c, d and e slightly for accuracy.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-84338f4f41', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which statement regarding theophylline is false?', '["It is a methylxanthine", "It inhibits cholinesterase", "It has a narrow therapeutic window", "Its clearance is increased in cigarette smokers", "It may cause seizures"]'::jsonb, 'It inhibits cholinesterase', '[]'::jsonb, 'Theophylline inhibits phosphodiesterase and antagonises adenosine receptors; it does not inhibit cholinesterase. It has a narrow therapeutic window (about 10 to 20 mg/L), with toxicity causing arrhythmias and seizures. Smoking induces CYP1A2 and increases its clearance, so smokers need higher doses and levels rise when they stop.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.139 Q41') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-b2802847a0', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'The mechanism of action of digitalis is associated with:', '["Decrease in calcium uptake by the sarcoplasmic reticulum", "Increase in ATP synthesis", "Modification of the actin molecule", "Increase in cytoplasmic calcium levels", "Blockade of cardiac β-adrenoceptors"]'::jsonb, 'Increase in cytoplasmic calcium levels', '[]'::jsonb, 'Digitalis inhibits Na+/K+ ATPase, so intracellular sodium rises and the Na+/Ca2+ exchanger removes less calcium. More calcium is stored in the sarcoplasmic reticulum and released with each beat, increasing cytoplasmic calcium available to troponin and strengthening contraction. Excess calcium also causes delayed afterdepolarisations and arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.140 Q30') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-adrenoceptor-receptor-blocking-drugs-v-1faa3ff694', 'pharm-adrenoceptor-receptor-blocking-drugs-vasodilators', 'mcq', 'Which drug is used in severe hypertensive emergencies, is very short-acting and is given as an intravenous infusion?', '["Diazoxide", "Hydralazine", "Sodium nitroprusside", "Fenoldopam", "Labetalol"]'::jsonb, 'Sodium nitroprusside', '[]'::jsonb, 'Sodium nitroprusside acts within seconds and wears off within 1 to 2 minutes of stopping, so blood pressure can be titrated precisely by continuous infusion, protected from light. It dilates arterioles and venules through nitric oxide. Prolonged or high-dose use releases cyanide and thiocyanate, which must be monitored.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.140. Fenoldopam is also a short-acting IV infusion for hypertensive emergencies; nitroprusside is the classic answer.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-7047ed2e91', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Regarding drugs used in the treatment of status epilepticus, which statement is true?', '["Phenytoin is useful in status for its sedating as well as anticonvulsant activity", "Phenytoin may be diluted in both saline and dextrose", "The effect of IV diazepam is long-lasting", "Respiratory depression is a common complication of phenobarbitone", "Phenytoin should be administered at a rate of at least 50 mg/min"]'::jsonb, 'Respiratory depression is a common complication of phenobarbitone', '[]'::jsonb, 'IV phenobarbitone causes sedation, hypotension and respiratory depression, particularly after benzodiazepines, so ventilatory support must be available. Phenytoin controls seizures without sedation, precipitates in dextrose (dilute in saline only), and must be infused no faster than 50 mg/min to avoid arrhythmias and hypotension. Diazepam''s effect is brief because of redistribution.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.141 Q42. Reworded option e to reflect that 50 mg/min is a maximum rate.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhibitors-of-angiotensin-raas-inhibit-c09be6b985', 'pharm-inhibitors-of-angiotensin-raas-inhibitors', 'mcq', 'Which statement about ACE inhibitors is true?', '["They decrease levels of bradykinin", "They cause hyperkalaemia less often in patients with diabetes", "They are contraindicated in patients on NSAIDs", "They decrease glomerular efferent arteriolar resistance", "They lead to decreased prostaglandin synthesis"]'::jsonb, 'They decrease glomerular efferent arteriolar resistance', '[]'::jsonb, 'Angiotensin II preferentially constricts the efferent arteriole, so ACE inhibitors dilate it, lowering glomerular pressure; this reduces proteinuria and protects the kidney in diabetes, but can drop GFR in bilateral renal artery stenosis. They increase bradykinin and prostaglandins, cause hyperkalaemia more often in diabetics, and interact with NSAIDs, which is a caution rather than a contraindication.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.141 Q43') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-methotrexate-chloroquine-hydroxychloro-34e2f81529', 'pharm-methotrexate-chloroquine-hydroxychloroquine', 'mcq', 'Which of the following is given to reduce the toxicity, including gastrointestinal toxicity, of methotrexate?', '["Cyclophosphamide", "Prednisolone", "Leucovorin", "Azathioprine", "Ciclosporin"]'::jsonb, 'Leucovorin', '[]'::jsonb, 'Leucovorin (folinic acid) is a reduced folate that bypasses methotrexate''s blockade of dihydrofolate reductase, rescuing normal cells from mucositis, GI toxicity and marrow suppression after high-dose methotrexate. In low-dose methotrexate for rheumatoid arthritis, weekly folic acid serves the same purpose. The other drugs are immunosuppressants.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.143 Q44') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antiseizure-barbiturates-hydantoin-5870c6f48b', 'pharm-antiseizure-barbiturates-hydantoin', 'mcq', 'Which statement about phenytoin is incorrect?', '["It causes less sedation than phenobarbitone", "It causes gingival hyperplasia", "It is not effective for absence seizures", "Its plasma half-life increases as the dose is increased", "It is safe to use in pregnancy"]'::jsonb, 'It is safe to use in pregnancy', '[]'::jsonb, 'Phenytoin is teratogenic, causing fetal hydantoin syndrome (craniofacial anomalies, nail and digit hypoplasia, growth and developmental delay), and as an enzyme inducer it can cause neonatal vitamin K deficiency bleeding. It sedates less than phenobarbitone, causes gum hyperplasia, does not help absences, and its saturable metabolism means half-life rises with dose.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.143 Q45. Replaced option b (''not indicated for children less than 5 years of age'', which was unclear) with gingival hyperplasia.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-cns-depressants-psychedel-469b74dba6', 'pharm-addiction-to-cns-depressants-psychedelic-agents', 'mcq', 'Which statement about ethanol is true?', '["It stimulates ADH secretion", "It stimulates gastric secretion", "It increases core body temperature", "Its absorption from the GIT is increased in the presence of food", "It has no effect on the liver''s handling of other drugs"]'::jsonb, 'It stimulates gastric secretion', '[]'::jsonb, 'Ethanol in low concentrations stimulates gastric acid secretion, which is why it was once used as an appetite stimulant; higher concentrations irritate the mucosa. It inhibits ADH release, causing diuresis, causes cutaneous vasodilation that lowers core temperature, is absorbed more slowly with food, and acutely inhibits but chronically induces drug metabolism.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.143 Q47. Replaced option a (''CNS stimulant if taken in small quantities'', an apparent disinhibition effect that is arguable) with a clearly false statement.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-172708115f', 'pharm-antidepressants-and-lithium', 'mcq', 'Which statement about tricyclic antidepressants is true?', '["They show similar therapeutic efficacy to one another", "They selectively inhibit uptake of noradrenaline into neurons", "They have an immediate therapeutic effect", "They must be administered intramuscularly", "Hypertension is a common adverse effect"]'::jsonb, 'They show similar therapeutic efficacy to one another', '[]'::jsonb, 'The various tricyclics are about equally effective as antidepressants; they differ mainly in adverse effects (secondary amines such as nortriptyline are less sedating and anticholinergic) and toxicity. Most block both noradrenaline and serotonin reuptake, act after 2 to 4 weeks, are taken orally, and cause postural hypotension rather than hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.143 Q48') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-anticholinergics-and-ganglion-blockers-a5135f75ef', 'pharm-anticholinergics-and-ganglion-blockers', 'mcq', 'Which statement about atropine is true?', '["It can cause bronchodilation", "It produces miosis", "It is not lipid-soluble", "It blocks reuptake of acetylcholine", "It causes an increase in salivary gland secretions"]'::jsonb, 'It can cause bronchodilation', '[]'::jsonb, 'Atropine blocks muscarinic M3 receptors on bronchial smooth muscle, causing bronchodilation and reducing secretions; inhaled quaternary derivatives such as ipratropium exploit this. Atropine is a lipid-soluble tertiary amine that enters the brain, dilates the pupil, dries the mouth, and competitively blocks receptors rather than acting on acetylcholine reuptake.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.145 Q8') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-aldosterone-oxytocin-vasopressin-12c57a3444', 'pharm-aldosterone-oxytocin-vasopressin', 'mcq', 'All of the following are true of desmopressin EXCEPT:', '["It increases water permeability of the collecting duct", "It increases secretion of von Willebrand factor", "It increases sodium chloride transport in the nephron", "It increases secretion of factor VIII", "It causes marked vasoconstriction"]'::jsonb, 'It causes marked vasoconstriction', '[]'::jsonb, 'Desmopressin is a V2-selective vasopressin analogue with minimal V1 activity, so it causes little vasoconstriction or blood pressure rise. Through V2 receptors it inserts aquaporin-2 into collecting duct membranes, stimulates NaCl reabsorption in the thick ascending limb, and releases von Willebrand factor and factor VIII from endothelial stores.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.146 Q85') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-calcium-channel-blocker-81558f6661', 'pharm-calcium-channel-blocker', 'mcq', 'Regarding calcium channel blockers, which statement is true?', '["None are active when given orally", "Most have half-lives of 24 to 48 hours", "Their mechanism of action is blockade of voltage-dependent L-type calcium channels", "They have no effect on bronchiolar smooth muscle", "Dihydropyridines typically cause bradycardia"]'::jsonb, 'Their mechanism of action is blockade of voltage-dependent L-type calcium channels', '[]'::jsonb, 'Clinically used calcium channel blockers bind L-type voltage-gated channels in vascular smooth muscle and myocardium, reducing calcium entry, relaxing arterioles and, for verapamil and diltiazem, slowing the heart. Most are orally active with half-lives of a few hours (amlodipine excepted), relax bronchial smooth muscle slightly, and dihydropyridines cause reflex tachycardia.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.147 Q28. Changed option b from ''8 to 12 hours'' to ''24 to 48 hours'' so it is clearly false for most CCBs.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-0a0178c84e', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'Which of the following is untrue regarding neuromuscular blocking drugs?', '["Non-depolarising agents act as antagonists at nicotinic receptors of the neuromuscular end plate", "Atracurium causes histamine release from mast cells", "They are indicated to control intractable seizures", "Sugammadex reverses rocuronium-induced neuromuscular blockade", "Succinylcholine is a depolarising blocker"]'::jsonb, 'They are indicated to control intractable seizures', '[]'::jsonb, 'Neuromuscular blockers stop the muscle movements of a seizure but have no effect on the abnormal electrical activity in the brain, so seizures can continue unseen; they are used only to allow ventilation, with EEG monitoring and antiseizure drugs. Sugammadex encapsulates steroidal blockers such as rocuronium and vecuronium, not benzylisoquinolines.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.148 Q91. Option D said sugammadex reverses doxacurium (false, as doxacurium is a benzylisoquinoline); changed to rocuronium and added a fifth option.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-c42d7555a0', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which drug reduces the diuretic response to loop diuretics?', '["Amphotericin B", "Warfarin", "Probenecid", "Lithium", "Propranolol"]'::jsonb, 'Probenecid', '[]'::jsonb, 'Loop diuretics act from the tubular lumen and reach it by secretion through the proximal tubule organic anion transporters. Probenecid competes for these transporters, reducing furosemide delivery to the thick ascending limb and blunting the diuresis. NSAIDs reduce the response by inhibiting renal prostaglandins.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.148 Q92') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-92ca466840', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'Which of the following is untrue of thiazide diuretics?', '["Most are sulfonamide derivatives", "They cause more hyponatraemia than loop diuretics", "Indapamide is excreted primarily by the biliary system", "They are indicated in nephrogenic diabetes insipidus", "They cause irreversible male impotence"]'::jsonb, 'They cause irreversible male impotence', '[]'::jsonb, 'Thiazides can cause erectile dysfunction, but it is reversible when the drug is stopped. They cause hyponatraemia more often than loop diuretics because they impair dilution without impairing concentration. Most are sulfonamide derivatives, indapamide is largely metabolised and excreted in bile, and thiazides paradoxically reduce polyuria in nephrogenic DI.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.148 Q93. Changed ''All are sulfonamides'' to ''Most are sulfonamide derivatives''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-salicylates-enolic-acids-nalbumetone-a-05e6b8128b', 'pharm-salicylates-enolic-acids-nalbumetone-and-pyrazolone-derivatives', 'mcq', 'Which of the following is false?', '["Non-acetylated salicylates cause less GIT bleeding", "Large doses of aspirin confer a uricosuric effect", "Aspirin has no effect on thromboxane A2", "Large doses of aspirin may cause hyperglycaemia", "Aspirin should be avoided in the third trimester of pregnancy"]'::jsonb, 'Aspirin has no effect on thromboxane A2', '[]'::jsonb, 'Low-dose aspirin irreversibly acetylates platelet COX-1, blocking thromboxane A2 synthesis for the platelet''s 8 to 10-day lifespan, which is its antiplatelet mechanism. Non-acetylated salicylates such as salsalate spare platelets and the stomach. High-dose salicylates are uricosuric and can disturb glucose, and aspirin is avoided late in pregnancy because it closes the ductus and prolongs labour.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.150 Q88') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-a38f394773', 'pharm-inhalational-anesthetic-agents', 'mcq', 'All the following are true of inhalational anaesthetics EXCEPT:', '["Halothane is stable in light", "Halothane has a bronchodilator effect", "Nitrous oxide is not flammable", "Nitrous oxide has an analgesic effect", "Rapid recovery is one of the properties that make nitrous oxide useful in short surgeries"]'::jsonb, 'Halothane is stable in light', '[]'::jsonb, 'Halothane decomposes on exposure to light, so it is stored in amber bottles with thymol as a preservative, which can accumulate in vaporisers. It is a bronchodilator. Nitrous oxide is non-flammable (though it supports combustion), provides good analgesia, and its low blood solubility gives rapid onset and recovery.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.150 Q89') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-local-anesthetic-agents-e17e832b17', 'pharm-local-anesthetic-agents', 'mcq', 'All of the following are true of lidocaine EXCEPT:', '["It blocks voltage-gated sodium channels", "Its duration of action is prolonged by adrenaline", "It is an antiarrhythmic agent", "It is metabolised by pseudocholinesterase", "It causes loss of pain sensation"]'::jsonb, 'It is metabolised by pseudocholinesterase', '[]'::jsonb, 'Lidocaine is an amide, metabolised in the liver by CYP1A2 and CYP3A4 to active metabolites; ester local anaesthetics are the ones hydrolysed by plasma pseudocholinesterase. It blocks voltage-gated sodium channels, adrenaline prolongs its local effect by vasoconstriction, and it is a class Ib antiarrhythmic for ventricular arrhythmias.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.151 Q51') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-5d9a44f936', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are true of baclofen EXCEPT:', '["It is a spasmolytic agent", "It can be administered intrathecally", "It acts on GABA receptors", "It markedly reduces muscle strength in the way dantrolene does", "Its dose should be reduced gradually on stopping"]'::jsonb, 'It markedly reduces muscle strength in the way dantrolene does', '[]'::jsonb, 'Baclofen is a GABA-B agonist that acts in the spinal cord to reduce release of excitatory transmitters, relieving spasticity with less loss of muscle strength than dantrolene, which acts directly on muscle. Intrathecal pumps are used for severe spasticity. Abrupt withdrawal can cause seizures, hallucinations and rebound spasticity, so it is tapered.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.152 Q50. Reworded option d (''reduces muscle strength'') to a comparison with dantrolene, as baclofen can cause some weakness.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-organization-and-function-of-adrenergi-b6e4144148', 'pharm-organization-and-function-of-adrenergic-cholinergic-and-nanc-neu', 'mcq', 'Which of the following inhibits reuptake of noradrenaline into the presynaptic neuron?', '["Tricyclic antidepressants", "Tyramine", "Phentolamine", "Reserpine", "Clonidine"]'::jsonb, 'Tricyclic antidepressants', '[]'::jsonb, 'Tricyclic antidepressants block the noradrenaline transporter (uptake 1), as does cocaine, increasing synaptic noradrenaline. Tyramine is an indirect sympathomimetic that releases noradrenaline, reserpine blocks vesicular storage, phentolamine blocks α receptors, and clonidine reduces noradrenaline release through presynaptic α2 receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.156 Q67. Replaced amphetamine (which also inhibits reuptake while releasing noradrenaline) with clonidine.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-62f08392df', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'All of the following are true of acetazolamide EXCEPT:', '["It is well absorbed from the GIT", "Its half-life is about 3 to 6 hours", "It is excreted by the kidneys", "Tolerance to its diuretic effect develops on repeated use", "It is as effective a diuretic as a thiazide"]'::jsonb, 'It is as effective a diuretic as a thiazide', '[]'::jsonb, 'Acetazolamide is a weak diuretic: most bicarbonate it spares is reabsorbed further down the nephron, and the resulting metabolic acidosis reduces filtered bicarbonate, so the effect wanes within days (self-limiting tolerance). It is well absorbed orally and excreted unchanged by tubular secretion. It is used mainly for glaucoma and altitude sickness, not oedema.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.157 Q79. Changed ''Half life is 3 hours'' to a 3 to 6 hour range.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sunscreens-minoxidil-capsaicin-7e44e1decc', 'pharm-sunscreens-minoxidil-capsaicin', 'mcq', 'Which of the following antihypertensives is used in the treatment of alopecia?', '["Minoxidil", "Clonidine", "Reserpine", "Diazoxide", "Phentolamine"]'::jsonb, 'Minoxidil', '[]'::jsonb, 'Minoxidil is a potassium channel opener and potent arteriolar dilator; its common adverse effect, hypertrichosis, led to topical minoxidil for androgenetic alopecia, where it prolongs the hair growth phase. Orally it is reserved for severe resistant hypertension with a β-blocker and diuretic to counter reflex tachycardia and fluid retention.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.164 Q70') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-thiazide-diuretics-potassium-sparing-d-aa97bf461a', 'pharm-thiazide-diuretics-potassium-sparing-diuretics-carbonic-anhydras', 'mcq', 'The following are potassium-sparing diuretics EXCEPT:', '["Spironolactone", "Metolazone", "Amiloride", "Eplerenone", "Triamterene"]'::jsonb, 'Metolazone', '[]'::jsonb, 'Metolazone is a thiazide-like diuretic that acts on the distal convoluted tubule and causes potassium loss; unlike thiazides it remains effective at low GFR and is combined with loop diuretics for resistant oedema. Spironolactone and eplerenone block aldosterone receptors, and amiloride and triamterene block epithelial sodium channels, all sparing potassium.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.167 Q12') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-cardiac-glycosides-other-positive-iono-9e0183c9df', 'pharm-cardiac-glycosides-other-positive-ionotropic-drugs', 'mcq', 'Which of the following drugs is a positive inotropic agent that works via inhibition of phosphodiesterase?', '["Ouabain", "Dopamine", "Amrinone", "Istaroxime", "Levosimendan"]'::jsonb, 'Amrinone', '[]'::jsonb, 'Amrinone (inamrinone) and milrinone selectively inhibit phosphodiesterase-3, raising cAMP in heart and vascular smooth muscle; they increase contractility and cause vasodilation (''inodilators''), and are used short term IV in acute heart failure. Ouabain and istaroxime inhibit Na+/K+ ATPase, dopamine acts on receptors, and levosimendan mainly sensitises troponin C to calcium.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.168 Q13. Levosimendan also has some PDE-3 inhibitory activity, though calcium sensitisation is its main action.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-corticosteroids-in-asthma-mast-cell-st-a6690a1295', 'pharm-corticosteroids-in-asthma-mast-cell-stabilisers', 'mcq', 'The following corticosteroids are available in inhaled form EXCEPT:', '["Beclometasone", "Mometasone", "Ciclesonide", "Dexamethasone", "Fluticasone"]'::jsonb, 'Dexamethasone', '[]'::jsonb, 'Dexamethasone is a long-acting systemic glucocorticoid given orally or by injection, for example in cerebral oedema, croup and antenatal lung maturation; it is not used by inhalation. Beclometasone, mometasone, ciclesonide, fluticasone and budesonide are inhaled steroids with high topical potency and extensive first-pass metabolism.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.168 Q14') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-iminostilbenes-succinimides-lamotrigin-813d44e131', 'pharm-iminostilbenes-succinimides-lamotrigine', 'mcq', 'Which of the following anticonvulsant agents is incorrectly classified?', '["Primidone: barbiturate", "Lamotrigine: iminostilbene", "Trimethadione: oxazolidinedione", "Valproic acid: fatty carboxylic acid", "Tiagabine: nipecotic acid derivative"]'::jsonb, 'Lamotrigine: iminostilbene', '[]'::jsonb, 'Lamotrigine is a phenyltriazine; the iminostilbenes are carbamazepine and oxcarbazepine. The other pairings are correct: primidone is a deoxybarbiturate, trimethadione an oxazolidinedione, valproic acid a branched-chain fatty acid, and tiagabine a nipecotic acid derivative that inhibits GABA reuptake.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.168 Q15') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-654c056874', 'pharm-inhalational-anesthetic-agents', 'mcq', 'The following are adverse effects of halothane EXCEPT:', '["Hypotension", "Cardiac arrhythmias", "Hepatotoxicity", "Malignant hyperthermia", "Anaemia"]'::jsonb, 'Anaemia', '[]'::jsonb, 'Halothane''s adverse effects are hypotension, arrhythmias (especially with catecholamines), immune-mediated hepatitis, and triggering of malignant hyperthermia in susceptible people. Anaemia, more precisely megaloblastic bone marrow depression, is associated with prolonged nitrous oxide exposure, which oxidises vitamin B12 and inhibits methionine synthase.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.169 Q20') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-inhalational-anesthetic-agents-c68b820661', 'pharm-inhalational-anesthetic-agents', 'mcq', 'Which is the false statement about nitrous oxide?', '["It is a colourless gas", "It has a rapid onset of action", "It is used to reduce pain during childbirth", "It is a highly potent anaesthetic agent", "Prolonged exposure can cause bone marrow suppression"]'::jsonb, 'It is a highly potent anaesthetic agent', '[]'::jsonb, 'Nitrous oxide is a weak anaesthetic: its MAC is about 105%, so it cannot produce surgical anaesthesia alone at safe oxygen concentrations and is used as a carrier with volatile agents. Its low blood solubility gives rapid onset, it is a good analgesic (Entonox in labour), and prolonged exposure inactivates vitamin B12, causing marrow suppression and neuropathy.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.169 Q21. Changed option a from ''An odourless gas'' (nitrous oxide has a faint sweet smell) to ''colourless''.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-neuromuscular-blocking-agents-spasmoly-77af5b0d6a', 'pharm-neuromuscular-blocking-agents-spasmolytics', 'mcq', 'All of the following are true about suxamethonium EXCEPT:', '["It has a short duration of action (about 10 minutes)", "It can cause bradycardia", "It is a competitive antagonist at the acetylcholine receptor", "It is hydrolysed by plasma cholinesterase", "It is used for brief procedures such as tracheal intubation"]'::jsonb, 'It is a competitive antagonist at the acetylcholine receptor', '[]'::jsonb, 'Suxamethonium (succinylcholine) is a depolarising agonist at the nicotinic receptor: it opens the channel, causing fasciculations, then maintains depolarisation so the muscle cannot respond. Its rapid onset and short action, ended by plasma cholinesterase, suit intubation, and stimulation of cardiac muscarinic receptors can cause bradycardia, especially with repeated doses.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.169 Q22') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-direct-acting-cholinomimetics-53c5e23a89', 'pharm-direct-acting-cholinomimetics', 'mcq', 'The following are pharmacological effects of bethanechol EXCEPT:', '["Negative chronotropy", "Bronchoconstriction", "Increased ureteral peristalsis", "Constipation", "Miosis"]'::jsonb, 'Constipation', '[]'::jsonb, 'Bethanechol is a muscarinic agonist resistant to cholinesterase; it increases gut and bladder smooth muscle activity and is used for non-obstructive urinary retention and postoperative ileus, so it relieves rather than causes constipation. Like other muscarinic agonists it can slow the heart, constrict bronchi, constrict the pupil and increase secretions.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.170 Q28') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-drug-agonists-and-antagonists-4b97e3de95', 'pharm-drug-agonists-and-antagonists', 'mcq', 'All of the following are true about drug antagonism EXCEPT:', '["An antagonist provokes a biological response", "It reduces the agonist-mediated response", "An antagonist has affinity for the receptor", "An antagonist has no efficacy", "Antagonism can be reversible"]'::jsonb, 'An antagonist provokes a biological response', '[]'::jsonb, 'A pure antagonist binds the receptor (it has affinity) but does not activate it (zero efficacy), so on its own it produces no response; it acts only by preventing or reducing an agonist''s effect. Competitive antagonism is reversible and surmountable by more agonist, while irreversible antagonists such as phenoxybenzamine are not.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.170 Q29') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-antidepressants-and-lithium-cd16b29906', 'pharm-antidepressants-and-lithium', 'mcq', 'All of the following are true about lithium salts EXCEPT:', '["They are used in the treatment of manic-depressive illness", "They take up to 10 days to take effect after starting", "They have a low therapeutic index", "Long-term use may lead to non-toxic goitre", "They are safe to use in the first 3 months of pregnancy"]'::jsonb, 'They are safe to use in the first 3 months of pregnancy', '[]'::jsonb, 'First-trimester lithium exposure is linked to cardiac malformations, notably Ebstein''s anomaly, so it is avoided or carefully reviewed in early pregnancy. Lithium treats bipolar (manic-depressive) disorder, takes 1 to 2 weeks to control mania, has a narrow therapeutic index requiring levels, and inhibits thyroid hormone release, causing goitre and hypothyroidism.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.172 Q53') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-pharmacologic-management-of-parkinsoni-f1cf7e5d98', 'pharm-pharmacologic-management-of-parkinsonism-and-other-movement-diso', 'mcq', 'Which of the following antiparkinsonian drugs is not a dopaminergic drug?', '["Amantadine", "Orphenadrine", "Ropinirole", "Entacapone", "Levodopa"]'::jsonb, 'Orphenadrine', '[]'::jsonb, 'Orphenadrine is a centrally acting antimuscarinic (also with antihistamine activity) that reduces tremor and rigidity by correcting relative cholinergic excess. Levodopa replaces dopamine, ropinirole is a dopamine agonist, entacapone prolongs levodopa''s action by COMT inhibition, and amantadine increases dopamine release and blocks NMDA receptors.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.173') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-introduction-to-antihypertensive-drugs-fdfabc3c76', 'pharm-introduction-to-antihypertensive-drugs-centrally-acting-sympatho', 'mcq', 'Which is not true about clonidine?', '["Intravenous administration is associated with an acute rise in blood pressure", "It is available as a transdermal patch", "Dry mouth and sedation are rare adverse effects", "It can cause a withdrawal syndrome", "It is a centrally acting sympathoplegic drug"]'::jsonb, 'Dry mouth and sedation are rare adverse effects', '[]'::jsonb, 'Dry mouth and sedation are clonidine''s commonest adverse effects, from α2 stimulation in the brainstem and salivary glands. Rapid IV injection can cause a transient rise in blood pressure by stimulating peripheral postsynaptic α2 receptors on vessels before the central effect dominates. It comes as a transdermal patch, and abrupt withdrawal causes rebound hypertension.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.175 Q68') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-appetite-stimulants-and-suppressants-84a96b4d82', 'pharm-appetite-stimulants-and-suppressants', 'mcq', 'Which drug inhibits pancreatic lipase?', '["Amphetamine", "Cyproheptadine", "Orlistat", "Fluoxetine", "Phentermine"]'::jsonb, 'Orlistat', '[]'::jsonb, 'Orlistat binds covalently to the serine site of gastric and pancreatic lipases, preventing hydrolysis of dietary triglycerides, so about 30% of ingested fat is excreted. This causes oily stools, faecal urgency and reduced absorption of fat-soluble vitamins. Amphetamine and phentermine suppress appetite centrally, and cyproheptadine stimulates appetite.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.176 Q74') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-16acf3f905', 'pharm-sympathomimetics', 'mcq', 'Which of the following is a selective β1-adrenergic agonist?', '["Isoproterenol", "Bitolterol", "Cocaine", "Dobutamine", "Clonidine"]'::jsonb, 'Dobutamine', '[]'::jsonb, 'Dobutamine is relatively β1-selective, increasing contractility more than heart rate, which makes it useful for short-term inotropic support in cardiogenic shock and acute heart failure. Isoproterenol stimulates β1 and β2 non-selectively, bitolterol is a β2 agonist prodrug, cocaine blocks catecholamine reuptake, and clonidine is an α2 agonist.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.177 Q79') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-anesthetic-agents-5635ff7b28', 'pharm-intravenous-anesthetic-agents', 'mcq', 'Regarding ketamine, which is the false statement?', '["It produces dissociative anaesthesia", "It has a high abuse potential", "It acts by blocking AMPA glutamate receptors", "It is excreted in both urine and bile", "It causes cardiovascular stimulation"]'::jsonb, 'It acts by blocking AMPA glutamate receptors', '[]'::jsonb, 'Ketamine blocks NMDA-type glutamate receptors (by binding the phencyclidine site within the channel), not AMPA receptors. This produces dissociative anaesthesia with analgesia and amnesia. It stimulates the sympathetic system, raising heart rate and blood pressure, and is abused recreationally for its hallucinogenic effects.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.178 Q82') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-intravenous-fluids-bbb4a37e79', 'pharm-intravenous-fluids', 'mcq', 'Which acid-base imbalance is incorrectly matched with its appropriate treatment?', '["Acute metabolic acidosis: IV bicarbonate", "Chronic metabolic acidosis: potassium citrate", "Alcoholic ketoacidosis: dextrose saline", "Metabolic alkalosis: correcting volume and chloride deficit", "Respiratory alkalosis: increased ventilation"]'::jsonb, 'Respiratory alkalosis: increased ventilation', '[]'::jsonb, 'Respiratory alkalosis results from hyperventilation blowing off CO2, so treatment is to reduce ventilation and correct the cause, such as anxiety, pain or hypoxia; increasing ventilation would worsen it. Severe acute metabolic acidosis may receive bicarbonate, chronic acidosis oral citrate, alcoholic ketoacidosis dextrose and saline, and metabolic alkalosis saline and potassium chloride.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.178 Q84. Option d was ''Metabolic alkalosis: reduce ventilation''; replaced with standard treatment to avoid a second arguable mismatch.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-addiction-to-opioids-cocaine-amphetami-d00ef2fbe4', 'pharm-addiction-to-opioids-cocaine-amphetamines', 'mcq', 'The following symptoms and signs are seen with cocaine intake EXCEPT:', '["Increased blood pressure", "Tachycardia", "Ventricular arrhythmias", "Increased appetite", "Insomnia"]'::jsonb, 'Increased appetite', '[]'::jsonb, 'Cocaine blocks reuptake of noradrenaline, dopamine and serotonin, causing euphoria, alertness, insomnia, reduced appetite, tachycardia, hypertension, vasoconstriction, arrhythmias, myocardial infarction and seizures. Appetite is suppressed during use and increases only during the ''crash'' after a binge.', 'admin', 'published', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.178 Q85') on conflict (id) do nothing;
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, source, status, marks, long_answer, key_points, review_note) values ('pharm-sympathomimetics-methylxanthines-a2d7015d47', 'pharm-sympathomimetics-methylxanthines', 'mcq', 'Which second messenger causes smooth muscle relaxation in the respiratory system in asthma?', '["cGMP", "cAMP", "Ca2+", "DAG", "IP3"]'::jsonb, 'cAMP', '[]'::jsonb, 'β2 agonists activate Gs, stimulating adenylyl cyclase; the rise in cAMP activates protein kinase A, which phosphorylates targets that lower intracellular calcium and inactivate myosin light-chain kinase, relaxing bronchial smooth muscle. Theophylline raises cAMP by inhibiting its breakdown. Calcium, IP3 and DAG mediate contraction through muscarinic M3 and other Gq-coupled receptors.', 'admin', 'draft', 1, false, '[]'::jsonb, 'L3 CAT2 Compilation pt2 (Older CAT/exam) p.179 Q87. cGMP also relaxes airway smooth muscle (for example via nitric oxide), but cAMP is the principal messenger for asthma therapy.') on conflict (id) do nothing;
